insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (337, 39, 32, 40, 'سورة الزمر ٣٢ – ٤٠', 'الزمر: أليس الله بكافٍ عبده', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 337) = $j$[{"lbl": "الآيات ٣٢ – ٣٥", "q": "۞فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ ﴿٣٢﴾ وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ ﴿٣٣﴾ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ ﴿٣٤﴾ لِيُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِي عَمِلُواْ وَيَجۡزِيَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِي كَانُواْ يَعۡمَلُونَ ﴿٣٥﴾", "w": [["ومن أظلم ممن كذب على الله", "بأن نسب إليه ما هو بريء منه كالزوج والولد والشريك."], ["وكذّب بالصدق إذ جاءه", "بالقرآن والنبي والتوحيد والبعث والجزاء."], ["مثوى للكافرين", "مأوى ومكان إقامة ونزول."], ["والذي جاء بالصدق وصدّق به", "محمد ﷺ، والذي صدّق به أبو بكر وكل أصحاب رسول الله."], ["أولئك هم المتقون", "لعذاب الله بإيمانهم وتقواهم بترك الشرك والمعاصي."], ["ذلك جزاء المحسنين", "المذكور من نعيم الجنة جزاء المحسنين في أعمالهم."], ["ليكفّر الله عنهم أسوأ الذي عملوا", "ييسّر الله لهم ذلك ويوفّقهم إليه ليكفّر عنهم ذنوبهم."]], "m": "يخبر تعالى عباده منذراً بأنه لا أظلم ممن كذب على الله فقال عنه ما لم يقل، أو حرّم ولم يحرّم، أو أذن ولم يأذن، أو شرع ولم يشرع، وكذّب بالصدق وهو القرآن والنبي وما جاء به من الهدى ودين الحق. أليس في جهنم مثوى للكافرين؟ بلى، جزاؤهم الإقامة الدائمة فيها. والذي جاء بالصدق وصدّق به، وهم الصادقون في كل ما يخبرون به المصدّقون بما أوجب الله التصديق به، ويدخل فيهم دخولاً أولياً رسول الله ﷺ وأبو بكر الصديق ثم سائر الصحابة والمؤمنين إلى يوم الدين، أولئك هم الذين اتقوا كل ما يغضب الله من الشرك والمعاصي، فاستوجبوا النجاة من النار ودخول الجنة: لهم ما يشاؤون عند ربهم من نعيم بعضه لم يخطر على بال أحد ولم تره عين، ذلك جزاء المحسنين الذين أحسنوا الاعتقاد والقول والعمل، وفّقهم للإحسان ليكفّر عنهم أسوأ الذي عملوا من الذنوب، ويجزيهم أجرهم بأحسن الذي كانوا يعملون، إذ يضاعف لهم الأجر فتكون الحسنات الصغيرة كالكبيرة، فأصبح الجزاء كله على الأحسن.", "h": ["التنديد بالكذب على الله تعالى، والتكذيب به وبما جاء به رسوله ﷺ من الدين.", "بيان جزاء الكاذبين على الله ورسوله والمكذّبين بما جاء به رسول الله عن الله من الشرع.", "الترغيب في الصدق في الاعتقادات والأقوال والأعمال.", "فضل التقوى والإحسان وبيان جزائهما عند الله تعالى يوم القيامة."], "k": "«ومن أظلم ممن كذب على الله»… هل قلتُ يوماً «هذا حرام» أو «هذا حلال» بلا علم؟"}, {"lbl": "الآيات ٣٦ – ٤٠", "q": "أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ ﴿٣٦﴾ وَمَن يَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ أَلَيۡسَ ٱللَّهُ بِعَزِيزٖ ذِي ٱنتِقَامٖ ﴿٣٧﴾ وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِيَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوۡ أَرَادَنِي بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِيَ ٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ ﴿٣٨﴾ قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ فَسَوۡفَ تَعۡلَمُونَ ﴿٣٩﴾ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ ﴿٤٠﴾", "w": [["أليس الله بكافٍ عبده", "بلى، هو كافٍ عبده ورسوله محمداً ﷺ كل ما يهمّه."], ["ويخوّفونك بالذين من دونه", "بالأصنام والأوثان أن تصيبك بما يسوءك ويضرّك."], ["أليس الله بعزيز ذي انتقام", "بلى، هو عزيز غالب على أمره، صاحب انتقام شديد من أعدائه."], ["ليقولُنّ الله", "لوضوح البرهان وقوة الدليل وانقطاع الحجة."], ["قل أفرأيتم", "أخبروني."], ["هل هنّ ممسكات رحمته", "لا، إذاً فقل: حسبي الله، ولا حاجة لي بغيره."], ["اعملوا على مكانتكم", "على حالتكم التي أنتم عليها من الكفر والعناد."], ["إني عامل", "على حالتي التي أنا عليها من الإيمان والانقياد."], ["من يأتيه عذاب يخزيه", "في الدنيا بالقتل والأسر والجوع والقحط."], ["ويحلّ عليه عذاب مقيم", "عذاب النار بعد الموت لا يبرح."]], "m": "ما زال السياق في الدفاع عن الرسول ﷺ والرد على خصومه الذين استبطؤوا موته، فقال: إنك ميت وإنهم ميتون، فلا شماتة في الموت. وقوله: أليس الله بكافٍ عبده؟ دالّ على أن القوم حاولوا قتله لما لم يمت، وقد قرّروا قتله وأعطوا الجوائز لمن يقتله، فطمأنه الله أنهم لا يصلون إليه وأنه كافيه مؤامراتهم. ويخوّفونك بما يعبدون من دوننا من أصنام بأن تصيبك بقتل أو خبل، فلا يهمّك ذلك فإنها لا تضر ولا تنفع. ومن يهد الله فما له من مضل، وقد هداك ربك، ومن يضلل الله كقومك فما له من هاد. أليس الله بعزيز ذي انتقام؟ بلى، فسينتقم من أعدائه لأوليائه إن استمروا في أذاهم، وقد فعل. ولئن سألتهم من خلق السماوات والأرض ليقولُنّ الله، فما دام اعترافهم لازماً بأنه الخالق فلِمَ عبادة غيره؟ قل: أخبروني عما تدعون من دون الله إن أرادني الله بضر هل هن كاشفات ضره، أو أرادني برحمة من صحة وعافية وغنى ونصر هل هن ممسكات رحمته؟ لا، فإنها جماد، إذاً فقل: حسبي الله أعبده وأتوكل عليه، عليه وحده يتوكل المتوكلون فيثقون في كفايته ويفوّضون أمورهم إليه. قل يا قوم: لما أبيتم إلا العناد بعد ما قامت الحجج فاعملوا على حالتكم من الشرك، إني عامل على حالتي من الإيمان والتوحيد، فسوف تعلمون من يأتيه عذاب يذلّه في الدنيا بالقتل والأسر والجوع والقحط، ويحلّ عليه عذاب النار المقيم في الآخرة.", "h": ["تقرير كفاية الله وولايته لعباده المؤمنين، وخاصة ساداتهم من الأنبياء والأولياء.", "تقرير مقتضى الولاية، وهو النقمة من أعدائه تعالى لأوليائه وإن طال الزمن.", "تقرير التوحيد وإبطال التنديد.", "مظاهر ربوبية الله الموجبة لألوهيته.", "وجوب التوكل على الله واعتقاد كفايته لأوليائه.", "تقرير إنجاز الله وعده لرسوله والمؤمنين."], "k": "«أليس الله بكافٍ عبده»… كم أقلق مما يخوّفونني به؛ فهل أعيش بيقين «حسبي الله»؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 337;
insert into public.tdb_cards(topic, i, body) select 337, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٢ – ٣٥", "q": "۞فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَآءَهُۥٓۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡكَٰفِرِينَ ﴿٣٢﴾ وَٱلَّذِي جَآءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦٓ أُوْلَـٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ ﴿٣٣﴾ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمۡۚ ذَٰلِكَ جَزَآءُ ٱلۡمُحۡسِنِينَ ﴿٣٤﴾ لِيُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِي عَمِلُواْ وَيَجۡزِيَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِي كَانُواْ يَعۡمَلُونَ ﴿٣٥﴾", "w": [["ومن أظلم ممن كذب على الله", "بأن نسب إليه ما هو بريء منه كالزوج والولد والشريك."], ["وكذّب بالصدق إذ جاءه", "بالقرآن والنبي والتوحيد والبعث والجزاء."], ["مثوى للكافرين", "مأوى ومكان إقامة ونزول."], ["والذي جاء بالصدق وصدّق به", "محمد ﷺ، والذي صدّق به أبو بكر وكل أصحاب رسول الله."], ["أولئك هم المتقون", "لعذاب الله بإيمانهم وتقواهم بترك الشرك والمعاصي."], ["ذلك جزاء المحسنين", "المذكور من نعيم الجنة جزاء المحسنين في أعمالهم."], ["ليكفّر الله عنهم أسوأ الذي عملوا", "ييسّر الله لهم ذلك ويوفّقهم إليه ليكفّر عنهم ذنوبهم."]], "m": "يخبر تعالى عباده منذراً بأنه لا أظلم ممن كذب على الله فقال عنه ما لم يقل، أو حرّم ولم يحرّم، أو أذن ولم يأذن، أو شرع ولم يشرع، وكذّب بالصدق وهو القرآن والنبي وما جاء به من الهدى ودين الحق. أليس في جهنم مثوى للكافرين؟ بلى، جزاؤهم الإقامة الدائمة فيها. والذي جاء بالصدق وصدّق به، وهم الصادقون في كل ما يخبرون به المصدّقون بما أوجب الله التصديق به، ويدخل فيهم دخولاً أولياً رسول الله ﷺ وأبو بكر الصديق ثم سائر الصحابة والمؤمنين إلى يوم الدين، أولئك هم الذين اتقوا كل ما يغضب الله من الشرك والمعاصي، فاستوجبوا النجاة من النار ودخول الجنة: لهم ما يشاؤون عند ربهم من نعيم بعضه لم يخطر على بال أحد ولم تره عين، ذلك جزاء المحسنين الذين أحسنوا الاعتقاد والقول والعمل، وفّقهم للإحسان ليكفّر عنهم أسوأ الذي عملوا من الذنوب، ويجزيهم أجرهم بأحسن الذي كانوا يعملون، إذ يضاعف لهم الأجر فتكون الحسنات الصغيرة كالكبيرة، فأصبح الجزاء كله على الأحسن.", "h": ["التنديد بالكذب على الله تعالى، والتكذيب به وبما جاء به رسوله ﷺ من الدين.", "بيان جزاء الكاذبين على الله ورسوله والمكذّبين بما جاء به رسول الله عن الله من الشرع.", "الترغيب في الصدق في الاعتقادات والأقوال والأعمال.", "فضل التقوى والإحسان وبيان جزائهما عند الله تعالى يوم القيامة."], "k": "«ومن أظلم ممن كذب على الله»… هل قلتُ يوماً «هذا حرام» أو «هذا حلال» بلا علم؟"}, {"lbl": "الآيات ٣٦ – ٤٠", "q": "أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ ﴿٣٦﴾ وَمَن يَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ أَلَيۡسَ ٱللَّهُ بِعَزِيزٖ ذِي ٱنتِقَامٖ ﴿٣٧﴾ وَلَئِن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ لَيَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِيَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوۡ أَرَادَنِي بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِيَ ٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ ﴿٣٨﴾ قُلۡ يَٰقَوۡمِ ٱعۡمَلُواْ عَلَىٰ مَكَانَتِكُمۡ إِنِّي عَٰمِلٞۖ فَسَوۡفَ تَعۡلَمُونَ ﴿٣٩﴾ مَن يَأۡتِيهِ عَذَابٞ يُخۡزِيهِ وَيَحِلُّ عَلَيۡهِ عَذَابٞ مُّقِيمٌ ﴿٤٠﴾", "w": [["أليس الله بكافٍ عبده", "بلى، هو كافٍ عبده ورسوله محمداً ﷺ كل ما يهمّه."], ["ويخوّفونك بالذين من دونه", "بالأصنام والأوثان أن تصيبك بما يسوءك ويضرّك."], ["أليس الله بعزيز ذي انتقام", "بلى، هو عزيز غالب على أمره، صاحب انتقام شديد من أعدائه."], ["ليقولُنّ الله", "لوضوح البرهان وقوة الدليل وانقطاع الحجة."], ["قل أفرأيتم", "أخبروني."], ["هل هنّ ممسكات رحمته", "لا، إذاً فقل: حسبي الله، ولا حاجة لي بغيره."], ["اعملوا على مكانتكم", "على حالتكم التي أنتم عليها من الكفر والعناد."], ["إني عامل", "على حالتي التي أنا عليها من الإيمان والانقياد."], ["من يأتيه عذاب يخزيه", "في الدنيا بالقتل والأسر والجوع والقحط."], ["ويحلّ عليه عذاب مقيم", "عذاب النار بعد الموت لا يبرح."]], "m": "ما زال السياق في الدفاع عن الرسول ﷺ والرد على خصومه الذين استبطؤوا موته، فقال: إنك ميت وإنهم ميتون، فلا شماتة في الموت. وقوله: أليس الله بكافٍ عبده؟ دالّ على أن القوم حاولوا قتله لما لم يمت، وقد قرّروا قتله وأعطوا الجوائز لمن يقتله، فطمأنه الله أنهم لا يصلون إليه وأنه كافيه مؤامراتهم. ويخوّفونك بما يعبدون من دوننا من أصنام بأن تصيبك بقتل أو خبل، فلا يهمّك ذلك فإنها لا تضر ولا تنفع. ومن يهد الله فما له من مضل، وقد هداك ربك، ومن يضلل الله كقومك فما له من هاد. أليس الله بعزيز ذي انتقام؟ بلى، فسينتقم من أعدائه لأوليائه إن استمروا في أذاهم، وقد فعل. ولئن سألتهم من خلق السماوات والأرض ليقولُنّ الله، فما دام اعترافهم لازماً بأنه الخالق فلِمَ عبادة غيره؟ قل: أخبروني عما تدعون من دون الله إن أرادني الله بضر هل هن كاشفات ضره، أو أرادني برحمة من صحة وعافية وغنى ونصر هل هن ممسكات رحمته؟ لا، فإنها جماد، إذاً فقل: حسبي الله أعبده وأتوكل عليه، عليه وحده يتوكل المتوكلون فيثقون في كفايته ويفوّضون أمورهم إليه. قل يا قوم: لما أبيتم إلا العناد بعد ما قامت الحجج فاعملوا على حالتكم من الشرك، إني عامل على حالتي من الإيمان والتوحيد، فسوف تعلمون من يأتيه عذاب يذلّه في الدنيا بالقتل والأسر والجوع والقحط، ويحلّ عليه عذاب النار المقيم في الآخرة.", "h": ["تقرير كفاية الله وولايته لعباده المؤمنين، وخاصة ساداتهم من الأنبياء والأولياء.", "تقرير مقتضى الولاية، وهو النقمة من أعدائه تعالى لأوليائه وإن طال الزمن.", "تقرير التوحيد وإبطال التنديد.", "مظاهر ربوبية الله الموجبة لألوهيته.", "وجوب التوكل على الله واعتقاد كفايته لأوليائه.", "تقرير إنجاز الله وعده لرسوله والمؤمنين."], "k": "«أليس الله بكافٍ عبده»… كم أقلق مما يخوّفونني به؛ فهل أعيش بيقين «حسبي الله»؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (338, 39, 41, 52, 'سورة الزمر ٤١ – ٥٢', 'الزمر: الله يتوفى الأنفس', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 338) = $j$[{"lbl": "الآيات ٤١ – ٤٥", "q": "إِنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٍ ﴿٤١﴾ ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي لَمۡ تَمُتۡ فِي مَنَامِهَاۖ فَيُمۡسِكُ ٱلَّتِي قَضَىٰ عَلَيۡهَا ٱلۡمَوۡتَ وَيُرۡسِلُ ٱلۡأُخۡرَىٰٓ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿٤٢﴾ أَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـٔٗا وَلَا يَعۡقِلُونَ ﴿٤٣﴾ قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعٗاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ ﴿٤٤﴾ وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ ﴿٤٥﴾", "w": [["إنا أنزلنا عليك الكتاب بالحق", "أنزلنا عليك يا رسولنا القرآن ملتبساً بالحق."], ["وما أنت عليهم بوكيل", "ليس عليك أمر هدايتهم فتجبرهم على الإيمان."], ["الله يتوفّى الأنفس حين موتها", "ينهي حياة العباد بقبض أرواحهم عند نهاية آجالهم."], ["والتي لم تمت في منامها", "يتوفّاها وقت النوم فيحبسها عن التصرف."], ["فيمسك التي قضى عليها الموت", "يقبضها لحكمة بالموت عليها حال النوم."], ["ويرسل الأخرى إلى أجل مسمى", "التي لم يحكم بموتها يرسلها فيعيش صاحبها إلى نهاية أجله."], ["إن في ذلك لآيات لقوم يتفكرون", "في قبض الأرواح وإرسالها دلائل على قدرة الله على البعث الذي أنكروه."], ["أم اتخذوا من دون الله شفعاء", "لو كانوا يتفكرون لما أنكروا البعث ولا اتخذوا شفعاء لوضوح بطلان ذلك."], ["أوَلو كانوا لا يملكون شيئاً", "أيشفعون لكم ولو كانوا أصناماً لا تملك ولا تعقل؟"], ["قل لله الشفاعة جميعاً", "جميع الشفاعات لله، فشفاعة الأنبياء والشهداء والعلماء والأطفال مملوكة لله فلا يشفع أحد إلا بإذنه."], ["وإذا ذُكر الله وحده اشمأزّت", "إذا قيل: لا إله إلا الله نفرت نفوس المشركين وانقبضت وظهر الغضب في وجوههم."], ["إذا هم يستبشرون", "فرحون لافتتانهم بأصنامهم ونسيانهم حق الله."]], "m": "كان السياق في الصراع بين الرسول ﷺ وقومه، وهنا يسلّيه ربه: إنا أنزلنا عليك القرآن لهداية الناس ملتبساً بالحق، فمن اهتدى فعائد ذلك له، ينجو من النار ويدخل الجنة، ومن ضل فإنما يضل على نفسه، يُحرم الجنة ويُلقى في النار، وما أنت عليهم بوكيل، إن عليك إلا البلاغ، لم تُكلّف حفظ أعمالهم ولا أمر هدايتهم. الله يقبض الأرواح عند نهاية آجالها، يأمر ملك الموت فيخرجها بإذنه، والتي لم تمت يحبسها عن التصرف حال النوم، فإن أراد موتها لم يردّها إلى جسدها، وإن لم يرد أرسلها فيعيش صاحبها إلى أجله. إن في ذلك لدلائل على أن القادر على هذا قادر على البعث، وأن صاحب هذه القدرة هو صاحب الحق المطلق في العبادة، لقوم يتفكرون وهم الأحياء بالإيمان، أما الأموات بالشرك فلا يجدون في ذلك آية. بل اتخذ المشركون بدل التوحيد أوثاناً سمّوها شفعاء يرجون شفاعتها في قضاء حوائجهم لجهلهم، قل لهم: أيشفعون لكم ولو كانوا لا يملكون شيئاً من أسباب الشفاعة ولا يعقلون معناها لأنهم أحجار؟ قل لله الشفاعة جميعاً، ملك له مختصة به، فاطلبوها من مالكها الذي له ملك السماوات والأرض لا ممن هو مملوك له، ثم إليه ترجعون بعد الموت أحببتم أم كرهتم. وإذا ذُكر الله وحده نفر المشركون وانقبضوا وظهر الغضب في وجوههم، يكادون يسطون على من قال: لا إله إلا الله، وإذا ذُكرت أصنامهم إذا هم فرحون مسرورون، لافتتانهم بها ونسيانهم حقوق ربهم عليهم.", "h": ["تسلية الرسول ﷺ وحمله على الصبر والثبات في أصعب الظروف.", "مظاهر قدرة الله في الموت والحياة مما يقتضي الإيمان به وبلقائه وتوحيده.", "إبطال حجة المشركين في عبادة الأوثان من أجل الشفاعة لهم، إذ الشفاعة كلها لله.", "بيان خطأ من يطلب الشفاعة من غير الله، إذ لا يملك الشفاعة إلا الله.", "بيان سفه المشركين وضلالهم في غضبهم عند سماع التوحيد وفرحهم عند سماع الشرك."], "k": "«الله يتوفّى الأنفس… والتي لم تمت في منامها»… كل نومة موتة صغرى؛ فعلى أي حال أنام الليلة؟"}, {"lbl": "الآيات ٤٦ – ٤٨", "q": "قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿٤٦﴾ وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ ﴿٤٧﴾ وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٤٨﴾", "w": [["قل اللهم فاطر السماوات والأرض", "قل يا نبينا: يا الله يا خالق السماوات والأرض."], ["عالم الغيب والشهادة", "عالم ما غاب عن الأبصار والحواس، والشهادة خلاف الغيب."], ["فيما كانوا فيه يختلفون", "من أمور الدين عقائد وعبادات."], ["ولو أن للذين ظلموا", "ظلموا أنفسهم بالشرك والمعاصي."], ["وبدا لهم من الله ما لم يكونوا يحتسبون", "ظهر لهم من عذاب الله ما لم يكونوا يظنّون."], ["وحاق بهم ما كانوا به يستهزئون", "أحاط بهم العذاب الذي كانوا في الدنيا يستهزئون به."]], "m": "هذا إرشاد من الله لرسوله أن يفزع إليه بالدعاء إذا استحكم الخلاف بينه وبين خصومه وضاق الصدر: قل: يا الله خالق السماوات والأرض، عالم ما غاب عن الأبصار وما رُئي بها، أنت تحكم بين عبادك مؤمنهم وكافرهم فيما كانوا فيه يختلفون من الإيمان بك وبلقائك وصفاتك وعبادتك، اهدني لما اختُلف فيه من الحق بإذنك. ولو أن للذين ظلموا أنفسهم بالشرك والمعاصي عند معاينة العذاب يوم القيامة ما في الأرض جميعاً من أموال ونفائس ومثله معه وقُبل منهم الفداء لافتدوا به من سوء العذاب وما تردّدوا، وهذا دالّ على شدة العذاب وأنه لا يطاق مع حرمانهم من الجنة. وظهر لأولئك الذين إذا ذُكر الله وحده اشمأزّت قلوبهم من ألوان العذاب ما لم يكونوا يظنّون، وظهرت لهم سيئات ما كسبوا من الشرك والفسق والعصيان فاشتد كربهم، وأحاط بهم العذاب الذي كانوا إذا خُوّفوا به استهزؤوا به وبمن يذكّرهم به كالرسول ﷺ.", "h": ["مشروعية اللجوء إلى الله تعالى عند اشتداد الكرب وعظم الخلاف، والدعاء بهذا الدعاء: «اللهم رب جبريل وميكائيل وإسرافيل، فاطر السماوات والأرض، عالم الغيب والشهادة، أنت تحكم بين عبادك فيما كانوا فيه يختلفون، اهدني لما اختُلف فيه من الحق بإذنك، إنك تهدي من تشاء إلى صراط مستقيم»، إذ ثبتت السنة به والآية ذكرت أصله.", "بيان عظم العذاب وشدته يوم القيامة، وأن المرء لو يُقبل منه فداء لافتدى منه بما في الأرض من أموال ومثله معه.", "التحذير من الاستهزاء بأخبار الله تعالى ووعده ووعيده."], "k": "«اهدني لما اختُلف فيه من الحق بإذنك»… حين تكثر الآراء حولي، هل أفزع إلى الله بهذا الدعاء؟"}, {"lbl": "الآيات ٤٩ – ٥٢", "q": "فَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَانَا ثُمَّ إِذَا خَوَّلۡنَٰهُ نِعۡمَةٗ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۭۚ بَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٤٩﴾ قَدۡ قَالَهَا ٱلَّذِينَ مِن قَبۡلِهِمۡ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ ﴿٥٠﴾ فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْۚ وَٱلَّذِينَ ظَلَمُواْ مِنۡ هَـٰٓؤُلَآءِ سَيُصِيبُهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَمَا هُم بِمُعۡجِزِينَ ﴿٥١﴾ أَوَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٥٢﴾", "w": [["فإذا مسّ الإنسان ضرّ دعانا", "أصاب الكافر مرض وغيره مما يضره سأل كشف ضرّه."], ["ثم إذا خوّلناه نعمة منا", "أعطيناه نعمة من صحة أو مال وغيرهما."], ["إنما أوتيته على علم", "على علم من الله بأني أهل له."], ["بل هي فتنة", "لم يُعطها لأهليته لها وإنما أُعطيها فتنة."], ["ولكن أكثرهم لا يعلمون", "أن ما أُعطوه فتنة لهم وليس لرضا الله عنهم."], ["قد قالها الذين من قبلهم", "قال قولتهم من كان قبلهم كقارون فلم يلبثوا أن أُخذوا."], ["والذين ظلموا من هؤلاء", "بالشرك من كفار قريش."], ["سيصيبهم سيئات ما كسبوا", "كما أصاب من قبلهم، وقد أصابهم قحط سبع سنين وقُتلوا."], ["وما هم بمعجزين", "فائتين الله ولا غالبين له."], ["يبسط الرزق لمن يشاء ويقدر", "يوسّعه لمن يشاء امتحاناً ويضيّقه ابتلاءً."], ["إن في ذلك لآيات لقوم يؤمنون", "علامات على قدرة الله وكمال تدبيره لأمور خلقه."]], "m": "ما زال السياق في بيان حيرة المشركين وفساد قلوبهم: ذلك الكافر الذي إذا ذُكر الله وحده اشمأزّت نفسه، إذا مسّه ضر من مرض أو غيره دعا ربه منيباً ولم يشرك معه أحداً لعلمه أن الأوثان لا تكشف ضراً، فإذا أعطاه الله نعمة ابتلاءً قال: إنما أوتيته على علم من الله بأني أهل له، فأكذبه الله: بل هي فتنة، ولكن أكثرهم لا يعلمون أن الله إنما أعطاهم ليفتنهم لا لحبه لهم. والدليل أن قولتهم هذه قد قالها من قبلهم كقارون فأخذهم الله بذنوبهم فما أغنى عنهم ما كانوا يكسبون من أموال طائلة، والذين ظلموا من كفار قريش سيصيبهم أيضاً سيئات ما كسبوا وما هم بفائتين، وقد أصابهم قحط سبع سنين وقُتلوا وأُسروا في بدر. أوَلم يعلموا أن الله يبسط الرزق لمن يشاء امتحاناً أيشكر أم يكفر، ويضيّق على من يشاء ابتلاءً أيصبر أم يضجر، فليس البسط حباً للمبسوط له ولا التضييق كرهاً للمضيّق عليه، وإنما هو لحكمة التربية والتدبير. والكافرون يجهلون هذا فيقولون الباطل، أما المؤمنون فيجدون في هذا التدبير آيات دالّة على علم الله وحكمته فيزدادون إيماناً وبصيرة.", "h": ["بيان تناقض أهل الكفر والجهل والضلال في كل حياتهم.", "تقرير أنه ما من مصيبة إلا بذنب جليّ أو خفيّ، كبير أو صغير.", "بيان أن بسط الرزق وتضييقه على الأفراد أو الجماعات لا يعود إلى حب الله للعبد أو كرهه له، وإنما يعود لسنن التربية الإلهية وحِكم التدبير لشؤون الخلق.", "أهل الإيمان هم الذين ينتفعون بالآيات والدلائل لأنهم أحياء يبصرون ويعقلون، أما أهل الكفر فهم أموات لا يرون الآيات ولا يعقلونها.", "تهديد الله تعالى للظالمين ووعيده الشديد بأنه سيصيبهم كما أصاب غيرهم جزاء ظلمهم وكسبهم الفاسد."], "k": "«إنما أوتيته على علم»… حين أنجح، هل أنسبه لذكائي أم أراه فتنة وامتحاناً من الله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 338;
insert into public.tdb_cards(topic, i, body) select 338, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٥", "q": "إِنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۖ وَمَآ أَنتَ عَلَيۡهِم بِوَكِيلٍ ﴿٤١﴾ ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا وَٱلَّتِي لَمۡ تَمُتۡ فِي مَنَامِهَاۖ فَيُمۡسِكُ ٱلَّتِي قَضَىٰ عَلَيۡهَا ٱلۡمَوۡتَ وَيُرۡسِلُ ٱلۡأُخۡرَىٰٓ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿٤٢﴾ أَمِ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ شُفَعَآءَۚ قُلۡ أَوَلَوۡ كَانُواْ لَا يَمۡلِكُونَ شَيۡـٔٗا وَلَا يَعۡقِلُونَ ﴿٤٣﴾ قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعٗاۖ لَّهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ ثُمَّ إِلَيۡهِ تُرۡجَعُونَ ﴿٤٤﴾ وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمۡ يَسۡتَبۡشِرُونَ ﴿٤٥﴾", "w": [["إنا أنزلنا عليك الكتاب بالحق", "أنزلنا عليك يا رسولنا القرآن ملتبساً بالحق."], ["وما أنت عليهم بوكيل", "ليس عليك أمر هدايتهم فتجبرهم على الإيمان."], ["الله يتوفّى الأنفس حين موتها", "ينهي حياة العباد بقبض أرواحهم عند نهاية آجالهم."], ["والتي لم تمت في منامها", "يتوفّاها وقت النوم فيحبسها عن التصرف."], ["فيمسك التي قضى عليها الموت", "يقبضها لحكمة بالموت عليها حال النوم."], ["ويرسل الأخرى إلى أجل مسمى", "التي لم يحكم بموتها يرسلها فيعيش صاحبها إلى نهاية أجله."], ["إن في ذلك لآيات لقوم يتفكرون", "في قبض الأرواح وإرسالها دلائل على قدرة الله على البعث الذي أنكروه."], ["أم اتخذوا من دون الله شفعاء", "لو كانوا يتفكرون لما أنكروا البعث ولا اتخذوا شفعاء لوضوح بطلان ذلك."], ["أوَلو كانوا لا يملكون شيئاً", "أيشفعون لكم ولو كانوا أصناماً لا تملك ولا تعقل؟"], ["قل لله الشفاعة جميعاً", "جميع الشفاعات لله، فشفاعة الأنبياء والشهداء والعلماء والأطفال مملوكة لله فلا يشفع أحد إلا بإذنه."], ["وإذا ذُكر الله وحده اشمأزّت", "إذا قيل: لا إله إلا الله نفرت نفوس المشركين وانقبضت وظهر الغضب في وجوههم."], ["إذا هم يستبشرون", "فرحون لافتتانهم بأصنامهم ونسيانهم حق الله."]], "m": "كان السياق في الصراع بين الرسول ﷺ وقومه، وهنا يسلّيه ربه: إنا أنزلنا عليك القرآن لهداية الناس ملتبساً بالحق، فمن اهتدى فعائد ذلك له، ينجو من النار ويدخل الجنة، ومن ضل فإنما يضل على نفسه، يُحرم الجنة ويُلقى في النار، وما أنت عليهم بوكيل، إن عليك إلا البلاغ، لم تُكلّف حفظ أعمالهم ولا أمر هدايتهم. الله يقبض الأرواح عند نهاية آجالها، يأمر ملك الموت فيخرجها بإذنه، والتي لم تمت يحبسها عن التصرف حال النوم، فإن أراد موتها لم يردّها إلى جسدها، وإن لم يرد أرسلها فيعيش صاحبها إلى أجله. إن في ذلك لدلائل على أن القادر على هذا قادر على البعث، وأن صاحب هذه القدرة هو صاحب الحق المطلق في العبادة، لقوم يتفكرون وهم الأحياء بالإيمان، أما الأموات بالشرك فلا يجدون في ذلك آية. بل اتخذ المشركون بدل التوحيد أوثاناً سمّوها شفعاء يرجون شفاعتها في قضاء حوائجهم لجهلهم، قل لهم: أيشفعون لكم ولو كانوا لا يملكون شيئاً من أسباب الشفاعة ولا يعقلون معناها لأنهم أحجار؟ قل لله الشفاعة جميعاً، ملك له مختصة به، فاطلبوها من مالكها الذي له ملك السماوات والأرض لا ممن هو مملوك له، ثم إليه ترجعون بعد الموت أحببتم أم كرهتم. وإذا ذُكر الله وحده نفر المشركون وانقبضوا وظهر الغضب في وجوههم، يكادون يسطون على من قال: لا إله إلا الله، وإذا ذُكرت أصنامهم إذا هم فرحون مسرورون، لافتتانهم بها ونسيانهم حقوق ربهم عليهم.", "h": ["تسلية الرسول ﷺ وحمله على الصبر والثبات في أصعب الظروف.", "مظاهر قدرة الله في الموت والحياة مما يقتضي الإيمان به وبلقائه وتوحيده.", "إبطال حجة المشركين في عبادة الأوثان من أجل الشفاعة لهم، إذ الشفاعة كلها لله.", "بيان خطأ من يطلب الشفاعة من غير الله، إذ لا يملك الشفاعة إلا الله.", "بيان سفه المشركين وضلالهم في غضبهم عند سماع التوحيد وفرحهم عند سماع الشرك."], "k": "«الله يتوفّى الأنفس… والتي لم تمت في منامها»… كل نومة موتة صغرى؛ فعلى أي حال أنام الليلة؟"}, {"lbl": "الآيات ٤٦ – ٤٨", "q": "قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ عَٰلِمَ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ أَنتَ تَحۡكُمُ بَيۡنَ عِبَادِكَ فِي مَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿٤٦﴾ وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ ﴿٤٧﴾ وَبَدَا لَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٤٨﴾", "w": [["قل اللهم فاطر السماوات والأرض", "قل يا نبينا: يا الله يا خالق السماوات والأرض."], ["عالم الغيب والشهادة", "عالم ما غاب عن الأبصار والحواس، والشهادة خلاف الغيب."], ["فيما كانوا فيه يختلفون", "من أمور الدين عقائد وعبادات."], ["ولو أن للذين ظلموا", "ظلموا أنفسهم بالشرك والمعاصي."], ["وبدا لهم من الله ما لم يكونوا يحتسبون", "ظهر لهم من عذاب الله ما لم يكونوا يظنّون."], ["وحاق بهم ما كانوا به يستهزئون", "أحاط بهم العذاب الذي كانوا في الدنيا يستهزئون به."]], "m": "هذا إرشاد من الله لرسوله أن يفزع إليه بالدعاء إذا استحكم الخلاف بينه وبين خصومه وضاق الصدر: قل: يا الله خالق السماوات والأرض، عالم ما غاب عن الأبصار وما رُئي بها، أنت تحكم بين عبادك مؤمنهم وكافرهم فيما كانوا فيه يختلفون من الإيمان بك وبلقائك وصفاتك وعبادتك، اهدني لما اختُلف فيه من الحق بإذنك. ولو أن للذين ظلموا أنفسهم بالشرك والمعاصي عند معاينة العذاب يوم القيامة ما في الأرض جميعاً من أموال ونفائس ومثله معه وقُبل منهم الفداء لافتدوا به من سوء العذاب وما تردّدوا، وهذا دالّ على شدة العذاب وأنه لا يطاق مع حرمانهم من الجنة. وظهر لأولئك الذين إذا ذُكر الله وحده اشمأزّت قلوبهم من ألوان العذاب ما لم يكونوا يظنّون، وظهرت لهم سيئات ما كسبوا من الشرك والفسق والعصيان فاشتد كربهم، وأحاط بهم العذاب الذي كانوا إذا خُوّفوا به استهزؤوا به وبمن يذكّرهم به كالرسول ﷺ.", "h": ["مشروعية اللجوء إلى الله تعالى عند اشتداد الكرب وعظم الخلاف، والدعاء بهذا الدعاء: «اللهم رب جبريل وميكائيل وإسرافيل، فاطر السماوات والأرض، عالم الغيب والشهادة، أنت تحكم بين عبادك فيما كانوا فيه يختلفون، اهدني لما اختُلف فيه من الحق بإذنك، إنك تهدي من تشاء إلى صراط مستقيم»، إذ ثبتت السنة به والآية ذكرت أصله.", "بيان عظم العذاب وشدته يوم القيامة، وأن المرء لو يُقبل منه فداء لافتدى منه بما في الأرض من أموال ومثله معه.", "التحذير من الاستهزاء بأخبار الله تعالى ووعده ووعيده."], "k": "«اهدني لما اختُلف فيه من الحق بإذنك»… حين تكثر الآراء حولي، هل أفزع إلى الله بهذا الدعاء؟"}, {"lbl": "الآيات ٤٩ – ٥٢", "q": "فَإِذَا مَسَّ ٱلۡإِنسَٰنَ ضُرّٞ دَعَانَا ثُمَّ إِذَا خَوَّلۡنَٰهُ نِعۡمَةٗ مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمِۭۚ بَلۡ هِيَ فِتۡنَةٞ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ﴿٤٩﴾ قَدۡ قَالَهَا ٱلَّذِينَ مِن قَبۡلِهِمۡ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ ﴿٥٠﴾ فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْۚ وَٱلَّذِينَ ظَلَمُواْ مِنۡ هَـٰٓؤُلَآءِ سَيُصِيبُهُمۡ سَيِّـَٔاتُ مَا كَسَبُواْ وَمَا هُم بِمُعۡجِزِينَ ﴿٥١﴾ أَوَلَمۡ يَعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٥٢﴾", "w": [["فإذا مسّ الإنسان ضرّ دعانا", "أصاب الكافر مرض وغيره مما يضره سأل كشف ضرّه."], ["ثم إذا خوّلناه نعمة منا", "أعطيناه نعمة من صحة أو مال وغيرهما."], ["إنما أوتيته على علم", "على علم من الله بأني أهل له."], ["بل هي فتنة", "لم يُعطها لأهليته لها وإنما أُعطيها فتنة."], ["ولكن أكثرهم لا يعلمون", "أن ما أُعطوه فتنة لهم وليس لرضا الله عنهم."], ["قد قالها الذين من قبلهم", "قال قولتهم من كان قبلهم كقارون فلم يلبثوا أن أُخذوا."], ["والذين ظلموا من هؤلاء", "بالشرك من كفار قريش."], ["سيصيبهم سيئات ما كسبوا", "كما أصاب من قبلهم، وقد أصابهم قحط سبع سنين وقُتلوا."], ["وما هم بمعجزين", "فائتين الله ولا غالبين له."], ["يبسط الرزق لمن يشاء ويقدر", "يوسّعه لمن يشاء امتحاناً ويضيّقه ابتلاءً."], ["إن في ذلك لآيات لقوم يؤمنون", "علامات على قدرة الله وكمال تدبيره لأمور خلقه."]], "m": "ما زال السياق في بيان حيرة المشركين وفساد قلوبهم: ذلك الكافر الذي إذا ذُكر الله وحده اشمأزّت نفسه، إذا مسّه ضر من مرض أو غيره دعا ربه منيباً ولم يشرك معه أحداً لعلمه أن الأوثان لا تكشف ضراً، فإذا أعطاه الله نعمة ابتلاءً قال: إنما أوتيته على علم من الله بأني أهل له، فأكذبه الله: بل هي فتنة، ولكن أكثرهم لا يعلمون أن الله إنما أعطاهم ليفتنهم لا لحبه لهم. والدليل أن قولتهم هذه قد قالها من قبلهم كقارون فأخذهم الله بذنوبهم فما أغنى عنهم ما كانوا يكسبون من أموال طائلة، والذين ظلموا من كفار قريش سيصيبهم أيضاً سيئات ما كسبوا وما هم بفائتين، وقد أصابهم قحط سبع سنين وقُتلوا وأُسروا في بدر. أوَلم يعلموا أن الله يبسط الرزق لمن يشاء امتحاناً أيشكر أم يكفر، ويضيّق على من يشاء ابتلاءً أيصبر أم يضجر، فليس البسط حباً للمبسوط له ولا التضييق كرهاً للمضيّق عليه، وإنما هو لحكمة التربية والتدبير. والكافرون يجهلون هذا فيقولون الباطل، أما المؤمنون فيجدون في هذا التدبير آيات دالّة على علم الله وحكمته فيزدادون إيماناً وبصيرة.", "h": ["بيان تناقض أهل الكفر والجهل والضلال في كل حياتهم.", "تقرير أنه ما من مصيبة إلا بذنب جليّ أو خفيّ، كبير أو صغير.", "بيان أن بسط الرزق وتضييقه على الأفراد أو الجماعات لا يعود إلى حب الله للعبد أو كرهه له، وإنما يعود لسنن التربية الإلهية وحِكم التدبير لشؤون الخلق.", "أهل الإيمان هم الذين ينتفعون بالآيات والدلائل لأنهم أحياء يبصرون ويعقلون، أما أهل الكفر فهم أموات لا يرون الآيات ولا يعقلونها.", "تهديد الله تعالى للظالمين ووعيده الشديد بأنه سيصيبهم كما أصاب غيرهم جزاء ظلمهم وكسبهم الفاسد."], "k": "«إنما أوتيته على علم»… حين أنجح، هل أنسبه لذكائي أم أراه فتنة وامتحاناً من الله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (339, 39, 53, 66, 'سورة الزمر ٥٣ – ٦٦', 'الزمر: لا تقنطوا من رحمة الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 339) = $j$[{"lbl": "الآيات ٥٣ – ٥٩", "q": "۞قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٥٣﴾ وَأَنِيبُوٓاْ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُواْ لَهُۥ مِن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ ﴿٥٤﴾ وَٱتَّبِعُوٓاْ أَحۡسَنَ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ بَغۡتَةٗ وَأَنتُمۡ لَا تَشۡعُرُونَ ﴿٥٥﴾ أَن تَقُولَ نَفۡسٞ يَٰحَسۡرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِي جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّـٰخِرِينَ ﴿٥٦﴾ أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ ﴿٥٧﴾ أَوۡ تَقُولَ حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةٗ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِينَ ﴿٥٨﴾ بَلَىٰ قَدۡ جَآءَتۡكَ ءَايَٰتِي فَكَذَّبۡتَ بِهَا وَٱسۡتَكۡبَرۡتَ وَكُنتَ مِنَ ٱلۡكَٰفِرِينَ ﴿٥٩﴾", "w": [["يا عبادي الذين أسرفوا على أنفسهم", "أفرطوا في الجناية عليها بالإسراف في المعاصي."], ["لا تقنطوا من رحمة الله", "لا تيأسوا من المغفرة لكم ودخول الجنة."], ["إن الله يغفر الذنوب جميعاً", "ذنوب من أشرك وفسق إن هو تاب توبة نصوحاً."], ["وأنيبوا إلى ربكم", "ارجعوا إليه بالإيمان والطاعة."], ["وأسلموا له", "أخلصوا له أعمالكم."], ["واتبعوا أحسن ما أُنزل إليكم", "القرآن الكريم، فأحلّوا حلاله وحرّموا حرامه."], ["أن تقول نفس يا حسرتى", "نفس الكافر والمجرم: يا ندامتي."], ["على ما فرّطت في جنب الله", "في جانب حق الله فلم أطعه كما أطاعه غيري."], ["وإن كنت لمن الساخرين", "المستهزئين بدين الله وعباده المؤمنين."], ["لو أن لي كرّة فأكون من المحسنين", "لو أن لي رجعة إلى الدنيا فأكون من المؤمنين الذين أحسنوا القصد والعمل."], ["بلى قد جاءتك آياتي", "ليس الأمر كما تزعم أنك تتمنى الهداية، بل جاءتك آياتي فكذّبت بها واستكبرت."]], "m": "صحّ أن أناساً كانوا قد أشركوا وقتلوا وزنوا فكبُر عليهم ذلك، فقالوا: نبعث إلى رسول الله من يسأله: هل لنا من توبة؟ وقبل أن يصل رسولهم نزلت: قل يا عبادي الذين أفرطوا في ارتكاب الجرائم فأسرفوا على أنفسهم، لا تيأسوا من رحمة الله بأن يغفر ذنوبكم ويدخلكم الجنة إن أنتم تبتم، إن الله يغفر الذنوب جميعاً لمن تاب منها، لا يستعصي عليه ذنب، إنه هو الغفور الرحيم. وأنيبوا إلى ربكم أيها المسرفون بفعل المأمور وترك المنهي، وأخلصوا له أعمالكم ظاهراً وباطناً، مبادرين بذلك حلول العذاب الذي لا تقدرون على دفعه. واتبعوا أحسن ما أُنزل إليكم في هذا القرآن فامتثلوا الأمر واجتنبوا النهي، من قبل أن يأتيكم العذاب فجأة وأنتم لا تشعرون. بادروا بالتوبة قبل أن تقول نفس: يا ندامتي على تفريطي في حق الله، ما عبدته حق عبادته ولا ذكرته ولا شكرته، وإن كنت لمن المستهزئين بدينه وعباده المؤمنين، يا له من اعتراف يُودي بصاحبه في سواء الجحيم! أو تقول: لو أن الله هداني لكنت من المتقين، أو تقول حين ترى العذاب: لو أن لي رجعة إلى الدنيا فأكون من المحسنين. فقال تعالى رادّاً على تمنّياتهم الكاذبة: بلى قد جاءتك آياتي هادية لك فكذّبت بها واستكبرت وكنت من الكافرين.", "h": ["بيان فضل الله ورحمته على عباده بقبول توبة العبد إن تاب مهما كانت ذنوبه.", "دعوة الله الرحيم عباده المذنبين بالإنابة إليه والإسلام الخالص له.", "تقرير البعث والجزاء بذكر ما يحدث فيه وما يجري في ساحته من أهوال.", "وجوب تعجيل التوبة والمبادرة بها قبل حلول العذاب في الدنيا أو الموت، والموت أدهى وأمرّ حيث لا تُقبل توبة بعد الموت أبداً.", "الترغيب في الأخذ بالعزائم وترك الرخص لغير ضرورة.", "إبطال مذهب الجبرية الذين يرون أنهم مجبورون على فعل المعاصي وغشيان الذنوب، كقول أحدهم: لو أن الله هداني لفعلت كذا أو تركت كذا.", "فضل التقوى والإحسان وفضل المتقين والمحسنين."], "k": "«لا تقنطوا من رحمة الله»… مهما ثقل ذنبي فباب ربي مفتوح؛ فما الذي يؤخّرني عن الرجوع الآن؟"}, {"lbl": "الآيات ٦٠ – ٦٦", "q": "وَيَوۡمَ ٱلۡقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُواْ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡمُتَكَبِّرِينَ ﴿٦٠﴾ وَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمۡ يَحۡزَنُونَ ﴿٦١﴾ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ ﴿٦٢﴾ لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٦٣﴾ قُلۡ أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا ٱلۡجَٰهِلُونَ ﴿٦٤﴾ وَلَقَدۡ أُوحِيَ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ لَئِنۡ أَشۡرَكۡتَ لَيَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴿٦٥﴾ بَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّـٰكِرِينَ ﴿٦٦﴾", "w": [["ترى الذين كذبوا على الله", "باتخاذ أولياء من دونه وبالقول الكاذب عليه سبحانه."], ["وجوههم مسودّة", "سوداء من الكرب والحزن، وعلامة على أنهم من أهل النار."], ["أليس في جهنم مثوى للمتكبرين", "بلى، إن لهم فيها لمثوى، بئس هو من مثوى للمتكبرين عن عبادة الله."], ["وينجّي الله الذين اتقوا", "ينجيهم من النار بسبب تقواهم الشرك والمعاصي."], ["بمفازتهم لا يمسّهم السوء ولا هم يحزنون", "بفوزهم بالجنة لا يمسّهم العذاب ولا يحزنون لما نالهم من النعيم."], ["له مقاليد السماوات والأرض", "مفاتيح خزائن السماوات والأرض."], ["أولئك هم الخاسرون", "الخاسرون لأنفسهم وأهليهم يوم القيامة."], ["أفغير الله تأمرونّي أعبد", "قل للذين طلبوا منك أن تعبد معهم آلهتهم: أتأمرونني بعبادة غير الله وهو رب كل شيء؟"], ["لئن أشركت ليحبطنّ عملك", "من باب الفرض: لو أشركت بالله غيره في عبادته لحبط عملك."], ["بل الله فاعبد وكن من الشاكرين", "اعبد الله وحده، وكن من الشاكرين له على إنعامه عليك بالنبوة والرسالة والعصمة."]], "m": "تقدّم الأمر بتعجيل التوبة قبل الموت، لأن يوم القيامة يوم أهوال، وهنا بيان ذلك: ويوم القيامة ترى الذين كذبوا على الله فنسبوا إليه الولد والشريك والتحليل والتحريم وجوههم مسودّة علامة أنهم من أهل النار. أليس في جهنم مأوى للمتكبرين عن الإيمان والعبادة؟ بلى. وحال أخرى: ينجّي الله الذين اتقوا الشرك والمعاصي بفوزهم بالجنة، لا يمسّهم السوء في عرصات القيامة، ولا هم يحزنون على ما خلّفوا في الدنيا لأن نعيم الجنة أنساهم إياه. الله خالق كل شيء، ما من كائن سواه إلا وهو مخلوق، وهو على كل شيء قيّم حافظ، فلذا وجبت له العبادة. له مفاتيح خزائن الرحمات والخيرات، يفتح ما يشاء ويمسك ما يشاء، فلا يصح الطلب إلا منه، وما عبد الناس الأوثان إلا رغبة ورهبة، فلو علموا أن الرهبة لا تكون إلا من القادر على كل شيء، والرغبة لا تكون إلا فيمن بيده كل شيء، ما عبدوا غيره. والذين كفروا بآيات الله فلم يؤمنوا بها ولم يعملوا بما فيها أولئك هم الخاسرون أنفسهم وأهليهم يوم القيامة. ثم ردّ على المشركين الذين طلبوا من الرسول أن يعترف بآلهتهم مقابل أن يعترفوا بما جاء به: قل: أفغير الله تأمرونّي أعبد أيها الجاهلون؟ لن يكون هذا أبداً، ووصفهم بالجهل لأن جهلهم بالله وعظمته هو الذي سوّل لهم عبادة غيره. ولقد أُوحي إليك كما أُوحي إلى الأنبياء من قبلك: لئن أشركت ليبطلنّ عملك كله ولا تُثاب على شيء منه، ولتكوننّ من الخاسرين. بل الله وحده فاعبده وكن من الشاكرين له على إنعامه وإفضاله عليك.", "h": ["اسوداد الوجه يوم القيامة علامة الكفر والخلود في جهنم.", "ابيضاض الوجوه يوم القيامة علامة الإيمان والخلود في الجنة.", "تقرير البعث والجزاء بوصف أحواله وما يدور فيه.", "بيد الله كل شيء فلا يصح أن يُطلب شيء من غيره أبداً، ومن طلب شيئاً من غير الله فهو من أجهل الخلق.", "التنديد بالشرك وبيان خطورته، إذ هو محبط للأعمال بالكلية.", "وجوب عبادة الله بفعل أوامره واجتناب نواهيه، ووجوب حمده وشكره، إذ كل إنعام منه وكل إفضال له، فلله الحمد والمنة."], "k": "«له مقاليد السماوات والأرض»… المفاتيح كلها بيده؛ فلماذا أطرق أبواب غيره؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 339;
insert into public.tdb_cards(topic, i, body) select 339, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٣ – ٥٩", "q": "۞قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٥٣﴾ وَأَنِيبُوٓاْ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُواْ لَهُۥ مِن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ ﴿٥٤﴾ وَٱتَّبِعُوٓاْ أَحۡسَنَ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن يَأۡتِيَكُمُ ٱلۡعَذَابُ بَغۡتَةٗ وَأَنتُمۡ لَا تَشۡعُرُونَ ﴿٥٥﴾ أَن تَقُولَ نَفۡسٞ يَٰحَسۡرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِي جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّـٰخِرِينَ ﴿٥٦﴾ أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِي لَكُنتُ مِنَ ٱلۡمُتَّقِينَ ﴿٥٧﴾ أَوۡ تَقُولَ حِينَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِي كَرَّةٗ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِينَ ﴿٥٨﴾ بَلَىٰ قَدۡ جَآءَتۡكَ ءَايَٰتِي فَكَذَّبۡتَ بِهَا وَٱسۡتَكۡبَرۡتَ وَكُنتَ مِنَ ٱلۡكَٰفِرِينَ ﴿٥٩﴾", "w": [["يا عبادي الذين أسرفوا على أنفسهم", "أفرطوا في الجناية عليها بالإسراف في المعاصي."], ["لا تقنطوا من رحمة الله", "لا تيأسوا من المغفرة لكم ودخول الجنة."], ["إن الله يغفر الذنوب جميعاً", "ذنوب من أشرك وفسق إن هو تاب توبة نصوحاً."], ["وأنيبوا إلى ربكم", "ارجعوا إليه بالإيمان والطاعة."], ["وأسلموا له", "أخلصوا له أعمالكم."], ["واتبعوا أحسن ما أُنزل إليكم", "القرآن الكريم، فأحلّوا حلاله وحرّموا حرامه."], ["أن تقول نفس يا حسرتى", "نفس الكافر والمجرم: يا ندامتي."], ["على ما فرّطت في جنب الله", "في جانب حق الله فلم أطعه كما أطاعه غيري."], ["وإن كنت لمن الساخرين", "المستهزئين بدين الله وعباده المؤمنين."], ["لو أن لي كرّة فأكون من المحسنين", "لو أن لي رجعة إلى الدنيا فأكون من المؤمنين الذين أحسنوا القصد والعمل."], ["بلى قد جاءتك آياتي", "ليس الأمر كما تزعم أنك تتمنى الهداية، بل جاءتك آياتي فكذّبت بها واستكبرت."]], "m": "صحّ أن أناساً كانوا قد أشركوا وقتلوا وزنوا فكبُر عليهم ذلك، فقالوا: نبعث إلى رسول الله من يسأله: هل لنا من توبة؟ وقبل أن يصل رسولهم نزلت: قل يا عبادي الذين أفرطوا في ارتكاب الجرائم فأسرفوا على أنفسهم، لا تيأسوا من رحمة الله بأن يغفر ذنوبكم ويدخلكم الجنة إن أنتم تبتم، إن الله يغفر الذنوب جميعاً لمن تاب منها، لا يستعصي عليه ذنب، إنه هو الغفور الرحيم. وأنيبوا إلى ربكم أيها المسرفون بفعل المأمور وترك المنهي، وأخلصوا له أعمالكم ظاهراً وباطناً، مبادرين بذلك حلول العذاب الذي لا تقدرون على دفعه. واتبعوا أحسن ما أُنزل إليكم في هذا القرآن فامتثلوا الأمر واجتنبوا النهي، من قبل أن يأتيكم العذاب فجأة وأنتم لا تشعرون. بادروا بالتوبة قبل أن تقول نفس: يا ندامتي على تفريطي في حق الله، ما عبدته حق عبادته ولا ذكرته ولا شكرته، وإن كنت لمن المستهزئين بدينه وعباده المؤمنين، يا له من اعتراف يُودي بصاحبه في سواء الجحيم! أو تقول: لو أن الله هداني لكنت من المتقين، أو تقول حين ترى العذاب: لو أن لي رجعة إلى الدنيا فأكون من المحسنين. فقال تعالى رادّاً على تمنّياتهم الكاذبة: بلى قد جاءتك آياتي هادية لك فكذّبت بها واستكبرت وكنت من الكافرين.", "h": ["بيان فضل الله ورحمته على عباده بقبول توبة العبد إن تاب مهما كانت ذنوبه.", "دعوة الله الرحيم عباده المذنبين بالإنابة إليه والإسلام الخالص له.", "تقرير البعث والجزاء بذكر ما يحدث فيه وما يجري في ساحته من أهوال.", "وجوب تعجيل التوبة والمبادرة بها قبل حلول العذاب في الدنيا أو الموت، والموت أدهى وأمرّ حيث لا تُقبل توبة بعد الموت أبداً.", "الترغيب في الأخذ بالعزائم وترك الرخص لغير ضرورة.", "إبطال مذهب الجبرية الذين يرون أنهم مجبورون على فعل المعاصي وغشيان الذنوب، كقول أحدهم: لو أن الله هداني لفعلت كذا أو تركت كذا.", "فضل التقوى والإحسان وفضل المتقين والمحسنين."], "k": "«لا تقنطوا من رحمة الله»… مهما ثقل ذنبي فباب ربي مفتوح؛ فما الذي يؤخّرني عن الرجوع الآن؟"}, {"lbl": "الآيات ٦٠ – ٦٦", "q": "وَيَوۡمَ ٱلۡقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُواْ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَيۡسَ فِي جَهَنَّمَ مَثۡوٗى لِّلۡمُتَكَبِّرِينَ ﴿٦٠﴾ وَيُنَجِّي ٱللَّهُ ٱلَّذِينَ ٱتَّقَوۡاْ بِمَفَازَتِهِمۡ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمۡ يَحۡزَنُونَ ﴿٦١﴾ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ ﴿٦٢﴾ لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ أُوْلَـٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ ﴿٦٣﴾ قُلۡ أَفَغَيۡرَ ٱللَّهِ تَأۡمُرُوٓنِّيٓ أَعۡبُدُ أَيُّهَا ٱلۡجَٰهِلُونَ ﴿٦٤﴾ وَلَقَدۡ أُوحِيَ إِلَيۡكَ وَإِلَى ٱلَّذِينَ مِن قَبۡلِكَ لَئِنۡ أَشۡرَكۡتَ لَيَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴿٦٥﴾ بَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّـٰكِرِينَ ﴿٦٦﴾", "w": [["ترى الذين كذبوا على الله", "باتخاذ أولياء من دونه وبالقول الكاذب عليه سبحانه."], ["وجوههم مسودّة", "سوداء من الكرب والحزن، وعلامة على أنهم من أهل النار."], ["أليس في جهنم مثوى للمتكبرين", "بلى، إن لهم فيها لمثوى، بئس هو من مثوى للمتكبرين عن عبادة الله."], ["وينجّي الله الذين اتقوا", "ينجيهم من النار بسبب تقواهم الشرك والمعاصي."], ["بمفازتهم لا يمسّهم السوء ولا هم يحزنون", "بفوزهم بالجنة لا يمسّهم العذاب ولا يحزنون لما نالهم من النعيم."], ["له مقاليد السماوات والأرض", "مفاتيح خزائن السماوات والأرض."], ["أولئك هم الخاسرون", "الخاسرون لأنفسهم وأهليهم يوم القيامة."], ["أفغير الله تأمرونّي أعبد", "قل للذين طلبوا منك أن تعبد معهم آلهتهم: أتأمرونني بعبادة غير الله وهو رب كل شيء؟"], ["لئن أشركت ليحبطنّ عملك", "من باب الفرض: لو أشركت بالله غيره في عبادته لحبط عملك."], ["بل الله فاعبد وكن من الشاكرين", "اعبد الله وحده، وكن من الشاكرين له على إنعامه عليك بالنبوة والرسالة والعصمة."]], "m": "تقدّم الأمر بتعجيل التوبة قبل الموت، لأن يوم القيامة يوم أهوال، وهنا بيان ذلك: ويوم القيامة ترى الذين كذبوا على الله فنسبوا إليه الولد والشريك والتحليل والتحريم وجوههم مسودّة علامة أنهم من أهل النار. أليس في جهنم مأوى للمتكبرين عن الإيمان والعبادة؟ بلى. وحال أخرى: ينجّي الله الذين اتقوا الشرك والمعاصي بفوزهم بالجنة، لا يمسّهم السوء في عرصات القيامة، ولا هم يحزنون على ما خلّفوا في الدنيا لأن نعيم الجنة أنساهم إياه. الله خالق كل شيء، ما من كائن سواه إلا وهو مخلوق، وهو على كل شيء قيّم حافظ، فلذا وجبت له العبادة. له مفاتيح خزائن الرحمات والخيرات، يفتح ما يشاء ويمسك ما يشاء، فلا يصح الطلب إلا منه، وما عبد الناس الأوثان إلا رغبة ورهبة، فلو علموا أن الرهبة لا تكون إلا من القادر على كل شيء، والرغبة لا تكون إلا فيمن بيده كل شيء، ما عبدوا غيره. والذين كفروا بآيات الله فلم يؤمنوا بها ولم يعملوا بما فيها أولئك هم الخاسرون أنفسهم وأهليهم يوم القيامة. ثم ردّ على المشركين الذين طلبوا من الرسول أن يعترف بآلهتهم مقابل أن يعترفوا بما جاء به: قل: أفغير الله تأمرونّي أعبد أيها الجاهلون؟ لن يكون هذا أبداً، ووصفهم بالجهل لأن جهلهم بالله وعظمته هو الذي سوّل لهم عبادة غيره. ولقد أُوحي إليك كما أُوحي إلى الأنبياء من قبلك: لئن أشركت ليبطلنّ عملك كله ولا تُثاب على شيء منه، ولتكوننّ من الخاسرين. بل الله وحده فاعبده وكن من الشاكرين له على إنعامه وإفضاله عليك.", "h": ["اسوداد الوجه يوم القيامة علامة الكفر والخلود في جهنم.", "ابيضاض الوجوه يوم القيامة علامة الإيمان والخلود في الجنة.", "تقرير البعث والجزاء بوصف أحواله وما يدور فيه.", "بيد الله كل شيء فلا يصح أن يُطلب شيء من غيره أبداً، ومن طلب شيئاً من غير الله فهو من أجهل الخلق.", "التنديد بالشرك وبيان خطورته، إذ هو محبط للأعمال بالكلية.", "وجوب عبادة الله بفعل أوامره واجتناب نواهيه، ووجوب حمده وشكره، إذ كل إنعام منه وكل إفضال له، فلله الحمد والمنة."], "k": "«له مقاليد السماوات والأرض»… المفاتيح كلها بيده؛ فلماذا أطرق أبواب غيره؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (340, 39, 67, 75, 'سورة الزمر ٦٧ – ٧٥', 'الزمر: وما قدروا الله حق قدره', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 340) = $j$[{"lbl": "الآيات ٦٧ – ٧٠", "q": "وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦ وَٱلۡأَرۡضُ جَمِيعٗا قَبۡضَتُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطۡوِيَّـٰتُۢ بِيَمِينِهِۦۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٦٧﴾ وَنُفِخَ فِي ٱلصُّورِ فَصَعِقَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِيهِ أُخۡرَىٰ فَإِذَا هُمۡ قِيَامٞ يَنظُرُونَ ﴿٦٨﴾ وَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلۡكِتَٰبُ وَجِاْيٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ ﴿٦٩﴾ وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا يَفۡعَلُونَ ﴿٧٠﴾", "w": [["وما قدروا الله حق قدره", "ما عظّموه حق عظمته ولا عرفوه حق معرفته حين أشركوا في عبادته غيره."], ["والأرض جميعاً قبضته", "والأرض بجميع أجزائها قبضته."], ["والسماوات مطويات", "والسماوات السبع مطويات بيمينه."], ["سبحانه وتعالى عما يشركون", "تقدّس وتنزّه عما يشرك به المشركون."], ["ونُفخ في الصور", "نفخ إسرافيل نفخة الصعق."], ["ثم نُفخ فيه أخرى", "مرة أخرى، وهي نفخة القيام لرب العالمين."], ["وأشرقت الأرض بنور ربها", "أضاءت الأرض بنور الله تعالى حين يتجلّى لفصل القضاء."], ["ووُضع الكتاب", "كتاب الأعمال للحساب."], ["وجيء بالنبيين والشهداء", "بالنبيين ليشهدوا على أممهم، والشهداء محمد ﷺ وأمته."], ["وقُضي بينهم بالحق", "بالعدل، وهم لا يُظلمون بنقص حسناتهم ولا بزيادة سيئاتهم."], ["وهو أعلم بما يفعلون", "أعلم حتى من العاملين أنفسهم."]], "m": "ناعياً على المشركين شركهم ودعوتهم نبيه إلى الشرك أخبر تعالى أنهم بذلك ما عظّموه حق عظمته لجهلهم به: فالذي يجعل الأرض بكل طبقاتها في قبضته يوم القيامة، والسماوات يطويها بيمينه، ويقول: أنا الملك، أين الملوك؟ كيف يُعبد معه أصنام وتماثيل؟ سبحانه وتعالى عن الشريك والنظير والصاحبة والولد وعن صفات المحدَثين. ثم عرض مظاهر القدرة التي يتنافى معها عقلاً وجود من يستحق العبادة معه: ونفخ الملك الموكَّل بالصور نفخة فصعق من في السماوات ومن في الأرض إلا من شاء الله، والاستثناء دالّ على أن بعض المخلوقات لم يُصعق، ثم نُفخ فيه نفخة أخرى فإذا هم قيام ينظرون، وهي نفخة القيام لله رب العالمين للحساب. وأشرقت الأرض بنور ربها، ووُضع كتاب الأعمال، وجيء بالنبيين ليشهدوا على أممهم، وبالشهداء وهم أمة محمد يشهدون على الأمم السابقة بأن رسلها قد بلّغتهم، بناءً على ما أخبرهم الله في القرآن، كما قال: وكذلك جعلناكم أمة وسطاً لتكونوا شهداء على الناس. وحكم الله بين العباد بالعدل، ووُفّيت كل نفس ما عملت، وهو أعلم بما يفعلون حتى من العاملين أنفسهم، فالحساب عادل لا حيف فيه لتنزّه الباري عن الخطأ والجهل والنسيان.", "h": ["بيان مظاهر عظمة الرب تعالى التي يتنافى معها الشرك به عز وجل في عباداته.", "تقرير البعث والجزاء وبيان أحواله وما يجري فيه.", "بيان عدالة الله في قضائه بين عباده في عرصات القيامة.", "فضيلة هذه الأمة بقبولها شاهدة على الأمم التي سبقتها."], "k": "«وما قدروا الله حق قدره»… هل يليق بعظمته أن أقدّم عليه خوفاً من الناس أو حباً للدنيا؟"}, {"lbl": "الآيات ٧١ – ٧٥", "q": "وَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَتۡلُونَ عَلَيۡكُمۡ ءَايَٰتِ رَبِّكُمۡ وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ بَلَىٰ وَلَٰكِنۡ حَقَّتۡ كَلِمَةُ ٱلۡعَذَابِ عَلَى ٱلۡكَٰفِرِينَ ﴿٧١﴾ قِيلَ ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ ﴿٧٢﴾ وَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ ﴿٧٣﴾ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ نَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَيۡثُ نَشَآءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ ﴿٧٤﴾ وَتَرَى ٱلۡمَلَـٰٓئِكَةَ حَآفِّينَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡۚ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّۚ وَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٧٥﴾", "w": [["وسيق الذين كفروا", "ساقتهم الملائكة بعنف."], ["إلى جهنم زُمَراً", "جماعات: جماعة المشركين وجماعة المجرمين وغيرهم."], ["وقال لهم خزنتها", "الموكّلون بالنار من الملائكة، الواحد خازن."], ["ألم يأتكم رسل", "الاستفهام للتقرير والتوبيخ."], ["حقّت كلمة العذاب", "وجب العذاب للكافرين."], ["وسيق الذين اتقوا", "ساقتهم الملائكة بلطف على النجائب، الذين أطاعوا ربهم ولم يشركوا به."], ["وفُتحت أبوابها", "والحال أن أبواب الجنة قد فُتحت لاستقبالهم."], ["الحمد لله الذي صدقنا وعده", "أنجز لنا وعده بالجنة."], ["وأورثنا الأرض", "أرض الجنة، نظراً إلى وعده: تلك الجنة التي نورث من عبادنا من كان تقياً."], ["نتبوّأ من الجنة حيث نشاء", "ننزل منها حيث نشاء."], ["فنعم أجر العاملين", "الجنة."], ["حافّين من حول العرش", "محدقين بالعرش من كل جانب."], ["يسبّحون بحمد ربهم", "يقولون: سبحان الله وبحمده."], ["وقيل الحمد لله رب العالمين", "وقالت الملائكة والمؤمنون: الحمد لله على استقرار أهل الجنة في الجنة وأهل النار في النار."]], "m": "بعد الفراغ من الحكم على أهل الموقف أخبر تعالى عن مصير الفريقين: وسيق الذين كفروا، ساقتهم الملائكة بشدة لأنهم لا يريدون الذهاب، إلى جهنم جماعات، حتى إذا جاؤوها فُتحت أبوابها، إذ كانت مغلقة كأبواب السجون لا تُفتح إلا عند المجيء بالسجناء، وقال لهم خزنتها موبّخين: ألم يأتكم رسل منكم يتلون عليكم آيات ربكم المبيّنة للهدى من الضلال، ويدعونكم إلى فعل المحابّ وترك المكاره لتنجوا؟ قالوا: بلى، ولكن حقّت كلمة العذاب على الكافرين ونحن منهم. فتقول الملائكة: ادخلوا أبواب جهنم خالدين فيها، فبئس مأوى المتكبرين. وسيق الذين اتقوا ربهم إلى الجنة سوق لطف وتكريم على النجائب، زمراً: زمرة الجهاد وزمرة الصدقات وزمرة العلماء وزمرة الصلوات، حتى إذا جاؤوها وقد فُتحت أبوابها من قبل لاستقبالهم معزّزين مكرّمين، قال لهم خزنتها: سلام عليكم طبتم، طابت أرواحكم بأعمالكم الطيبة، فنعم التحية مقابل توبيخ الزبانية لأهل النار، فادخلوها خالدين. فقالوا بعد نزولهم قصورها: الحمد لله الذي صدقنا وعده، وأورثنا أرض الجنة ننزل منها حيث نريد، وفيه إشارة إلى أنهم ورثوها من أبويهم آدم وحواء إذ كانت لهما قبل نزولهما منها، فنعم أجر العاملين بالإيمان والتقوى. وترى أيها الرائي الملائكة محدقين بعرش الرحمن يسبّحون بحمد ربهم، وقضى الله بين الخلائق بالعدل، ولما استقر أهل النار وأهل الجنة قيل: الحمد لله رب العالمين، حمدت الملائكة ربها وحمده معهم المؤمنون وهم في دار النعيم المقيم.", "h": ["بيان إهانة أهل النار بسوقهم على أرجلهم بعنف وتأنيبهم وتوبيخهم.", "التنديد بالاستكبار عن عبادة الله تعالى، وعن عباده المؤمنين به المتقين له.", "بيان إكرام الله تعالى لأوليائه، إذ يُحملون على نجائب رحالها من ذهب إلى الجنة، ويلقون فيها تحية وسلاماً: تحية احترام وإكرام، وسلام أمان من كل مكروه.", "بيان نهاية الموقف باستقرار أهل النار من الكفار والفجار في النار، واستقرار أهل الجنة من المؤمنين الأتقياء الأبرار في الجنة دار الأبرار.", "ختم كل عمل بالحمد، فقد ابتدأ الله الخلق بالحمد فقال: الحمد لله الذي خلق السماوات والأرض، وختم بالحمد: وقيل الحمد لله رب العالمين."], "k": "«سلام عليكم طبتم»… أي عمل في يومي سيجعلهم يقولونها لي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 340;
insert into public.tdb_cards(topic, i, body) select 340, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٧ – ٧٠", "q": "وَمَا قَدَرُواْ ٱللَّهَ حَقَّ قَدۡرِهِۦ وَٱلۡأَرۡضُ جَمِيعٗا قَبۡضَتُهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطۡوِيَّـٰتُۢ بِيَمِينِهِۦۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٦٧﴾ وَنُفِخَ فِي ٱلصُّورِ فَصَعِقَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِيهِ أُخۡرَىٰ فَإِذَا هُمۡ قِيَامٞ يَنظُرُونَ ﴿٦٨﴾ وَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلۡكِتَٰبُ وَجِاْيٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ ﴿٦٩﴾ وَوُفِّيَتۡ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا يَفۡعَلُونَ ﴿٧٠﴾", "w": [["وما قدروا الله حق قدره", "ما عظّموه حق عظمته ولا عرفوه حق معرفته حين أشركوا في عبادته غيره."], ["والأرض جميعاً قبضته", "والأرض بجميع أجزائها قبضته."], ["والسماوات مطويات", "والسماوات السبع مطويات بيمينه."], ["سبحانه وتعالى عما يشركون", "تقدّس وتنزّه عما يشرك به المشركون."], ["ونُفخ في الصور", "نفخ إسرافيل نفخة الصعق."], ["ثم نُفخ فيه أخرى", "مرة أخرى، وهي نفخة القيام لرب العالمين."], ["وأشرقت الأرض بنور ربها", "أضاءت الأرض بنور الله تعالى حين يتجلّى لفصل القضاء."], ["ووُضع الكتاب", "كتاب الأعمال للحساب."], ["وجيء بالنبيين والشهداء", "بالنبيين ليشهدوا على أممهم، والشهداء محمد ﷺ وأمته."], ["وقُضي بينهم بالحق", "بالعدل، وهم لا يُظلمون بنقص حسناتهم ولا بزيادة سيئاتهم."], ["وهو أعلم بما يفعلون", "أعلم حتى من العاملين أنفسهم."]], "m": "ناعياً على المشركين شركهم ودعوتهم نبيه إلى الشرك أخبر تعالى أنهم بذلك ما عظّموه حق عظمته لجهلهم به: فالذي يجعل الأرض بكل طبقاتها في قبضته يوم القيامة، والسماوات يطويها بيمينه، ويقول: أنا الملك، أين الملوك؟ كيف يُعبد معه أصنام وتماثيل؟ سبحانه وتعالى عن الشريك والنظير والصاحبة والولد وعن صفات المحدَثين. ثم عرض مظاهر القدرة التي يتنافى معها عقلاً وجود من يستحق العبادة معه: ونفخ الملك الموكَّل بالصور نفخة فصعق من في السماوات ومن في الأرض إلا من شاء الله، والاستثناء دالّ على أن بعض المخلوقات لم يُصعق، ثم نُفخ فيه نفخة أخرى فإذا هم قيام ينظرون، وهي نفخة القيام لله رب العالمين للحساب. وأشرقت الأرض بنور ربها، ووُضع كتاب الأعمال، وجيء بالنبيين ليشهدوا على أممهم، وبالشهداء وهم أمة محمد يشهدون على الأمم السابقة بأن رسلها قد بلّغتهم، بناءً على ما أخبرهم الله في القرآن، كما قال: وكذلك جعلناكم أمة وسطاً لتكونوا شهداء على الناس. وحكم الله بين العباد بالعدل، ووُفّيت كل نفس ما عملت، وهو أعلم بما يفعلون حتى من العاملين أنفسهم، فالحساب عادل لا حيف فيه لتنزّه الباري عن الخطأ والجهل والنسيان.", "h": ["بيان مظاهر عظمة الرب تعالى التي يتنافى معها الشرك به عز وجل في عباداته.", "تقرير البعث والجزاء وبيان أحواله وما يجري فيه.", "بيان عدالة الله في قضائه بين عباده في عرصات القيامة.", "فضيلة هذه الأمة بقبولها شاهدة على الأمم التي سبقتها."], "k": "«وما قدروا الله حق قدره»… هل يليق بعظمته أن أقدّم عليه خوفاً من الناس أو حباً للدنيا؟"}, {"lbl": "الآيات ٧١ – ٧٥", "q": "وَسِيقَ ٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَآ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَتۡلُونَ عَلَيۡكُمۡ ءَايَٰتِ رَبِّكُمۡ وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ بَلَىٰ وَلَٰكِنۡ حَقَّتۡ كَلِمَةُ ٱلۡعَذَابِ عَلَى ٱلۡكَٰفِرِينَ ﴿٧١﴾ قِيلَ ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ ﴿٧٢﴾ وَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتۡ أَبۡوَٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَٰمٌ عَلَيۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَٰلِدِينَ ﴿٧٣﴾ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ نَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَيۡثُ نَشَآءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ ﴿٧٤﴾ وَتَرَى ٱلۡمَلَـٰٓئِكَةَ حَآفِّينَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡۚ وَقُضِيَ بَيۡنَهُم بِٱلۡحَقِّۚ وَقِيلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٧٥﴾", "w": [["وسيق الذين كفروا", "ساقتهم الملائكة بعنف."], ["إلى جهنم زُمَراً", "جماعات: جماعة المشركين وجماعة المجرمين وغيرهم."], ["وقال لهم خزنتها", "الموكّلون بالنار من الملائكة، الواحد خازن."], ["ألم يأتكم رسل", "الاستفهام للتقرير والتوبيخ."], ["حقّت كلمة العذاب", "وجب العذاب للكافرين."], ["وسيق الذين اتقوا", "ساقتهم الملائكة بلطف على النجائب، الذين أطاعوا ربهم ولم يشركوا به."], ["وفُتحت أبوابها", "والحال أن أبواب الجنة قد فُتحت لاستقبالهم."], ["الحمد لله الذي صدقنا وعده", "أنجز لنا وعده بالجنة."], ["وأورثنا الأرض", "أرض الجنة، نظراً إلى وعده: تلك الجنة التي نورث من عبادنا من كان تقياً."], ["نتبوّأ من الجنة حيث نشاء", "ننزل منها حيث نشاء."], ["فنعم أجر العاملين", "الجنة."], ["حافّين من حول العرش", "محدقين بالعرش من كل جانب."], ["يسبّحون بحمد ربهم", "يقولون: سبحان الله وبحمده."], ["وقيل الحمد لله رب العالمين", "وقالت الملائكة والمؤمنون: الحمد لله على استقرار أهل الجنة في الجنة وأهل النار في النار."]], "m": "بعد الفراغ من الحكم على أهل الموقف أخبر تعالى عن مصير الفريقين: وسيق الذين كفروا، ساقتهم الملائكة بشدة لأنهم لا يريدون الذهاب، إلى جهنم جماعات، حتى إذا جاؤوها فُتحت أبوابها، إذ كانت مغلقة كأبواب السجون لا تُفتح إلا عند المجيء بالسجناء، وقال لهم خزنتها موبّخين: ألم يأتكم رسل منكم يتلون عليكم آيات ربكم المبيّنة للهدى من الضلال، ويدعونكم إلى فعل المحابّ وترك المكاره لتنجوا؟ قالوا: بلى، ولكن حقّت كلمة العذاب على الكافرين ونحن منهم. فتقول الملائكة: ادخلوا أبواب جهنم خالدين فيها، فبئس مأوى المتكبرين. وسيق الذين اتقوا ربهم إلى الجنة سوق لطف وتكريم على النجائب، زمراً: زمرة الجهاد وزمرة الصدقات وزمرة العلماء وزمرة الصلوات، حتى إذا جاؤوها وقد فُتحت أبوابها من قبل لاستقبالهم معزّزين مكرّمين، قال لهم خزنتها: سلام عليكم طبتم، طابت أرواحكم بأعمالكم الطيبة، فنعم التحية مقابل توبيخ الزبانية لأهل النار، فادخلوها خالدين. فقالوا بعد نزولهم قصورها: الحمد لله الذي صدقنا وعده، وأورثنا أرض الجنة ننزل منها حيث نريد، وفيه إشارة إلى أنهم ورثوها من أبويهم آدم وحواء إذ كانت لهما قبل نزولهما منها، فنعم أجر العاملين بالإيمان والتقوى. وترى أيها الرائي الملائكة محدقين بعرش الرحمن يسبّحون بحمد ربهم، وقضى الله بين الخلائق بالعدل، ولما استقر أهل النار وأهل الجنة قيل: الحمد لله رب العالمين، حمدت الملائكة ربها وحمده معهم المؤمنون وهم في دار النعيم المقيم.", "h": ["بيان إهانة أهل النار بسوقهم على أرجلهم بعنف وتأنيبهم وتوبيخهم.", "التنديد بالاستكبار عن عبادة الله تعالى، وعن عباده المؤمنين به المتقين له.", "بيان إكرام الله تعالى لأوليائه، إذ يُحملون على نجائب رحالها من ذهب إلى الجنة، ويلقون فيها تحية وسلاماً: تحية احترام وإكرام، وسلام أمان من كل مكروه.", "بيان نهاية الموقف باستقرار أهل النار من الكفار والفجار في النار، واستقرار أهل الجنة من المؤمنين الأتقياء الأبرار في الجنة دار الأبرار.", "ختم كل عمل بالحمد، فقد ابتدأ الله الخلق بالحمد فقال: الحمد لله الذي خلق السماوات والأرض، وختم بالحمد: وقيل الحمد لله رب العالمين."], "k": "«سلام عليكم طبتم»… أي عمل في يومي سيجعلهم يقولونها لي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (341, 40, 1, 9, 'سورة غافر ١ – ٩', 'غافر: غافر الذنب وقابل التوب ودعاء حملة العرش', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 341) = $j$[{"lbl": "الآيات ١ – ٦", "q": "حمٓ ﴿١﴾ تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ﴿٢﴾ غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ ذِي ٱلطَّوۡلِۖ لَآ إِلَٰهَ إِلَّا هُوَۖ إِلَيۡهِ ٱلۡمَصِيرُ ﴿٣﴾ مَا يُجَٰدِلُ فِيٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُواْ فَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ ﴿٤﴾ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَٱلۡأَحۡزَابُ مِنۢ بَعۡدِهِمۡۖ وَهَمَّتۡ كُلُّ أُمَّةِۭ بِرَسُولِهِمۡ لِيَأۡخُذُوهُۖ وَجَٰدَلُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّ فَأَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ ﴿٥﴾ وَكَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ أَصۡحَٰبُ ٱلنَّارِ ﴿٦﴾", "w": [["حم", "أحد الحروف المقطعة، يُكتب «حم» ويُقرأ «حا ميم»."], ["تنزيل الكتاب من الله", "تنزيل القرآن كائن من الله."], ["العزيز العليم", "الغالب على مراده، العليم بعباده ظاهراً وباطناً."], ["غافر الذنب", "ذنب من تاب إلى الله فرجع إلى طاعته بعد معصيته."], ["شديد العقاب ذي الطَّول", "مشدّد العقوبة على من كفر به، ذي الإنعام الواسع على من آمن به وأطاعه."], ["لا إله إلا هو إليه المصير", "لا معبود بحق إلا هو، إليه مرجع الخلائق كلهم."], ["ما يجادل في آيات الله إلا الذين كفروا", "ما يجادل في القرآن لإبطاله إلا الكافرون."], ["فلا يغرُرك تقلّبهم في البلاد", "لا تغترّ بمعاشهم سالمين فإن عاقبتهم النار."], ["والأحزاب من بعدهم", "وكذّبت الأحزاب من بعد قوم نوح: عاد وثمود وقوم لوط وغيرهم."], ["وهمّت كل أمة برسولهم ليأخذوه", "ليتمكنوا من إصابته بما أرادوا من تعذيب وقتل."], ["ليُدحضوا به الحق", "ليزيلوا به الحق ويبطلوه."], ["فكيف كان عقاب", "كان واقعاً موقعه حيث أهلكهم ولم يُبق منهم أحداً."], ["كذلك حقّت كلمة ربك", "وجبت كلمة العذاب على الذين كفروا."]], "m": "حم: الله أعلم بمراده به، وقد أفادت هذه الحروف فائدتين: الأولى أن المشركين كانوا يمنعون الناس من سماع القرآن، فكانت هذه الحروف بنغمها الخاص تستهويهم فيسمعون. والثانية أنهم لما أصرّوا على أن القرآن ليس وحياً تحدّاهم الله بالإتيان بمثله وهو مؤلف من هذه الحروف، وقوّى هذا أنه غالباً ما يُذكر القرآن بعدها. تنزيل القرآن من الله العزيز في انتقامه من أعدائه الغالب على أمره، العليم بخلقه وحاجاتهم فأنزله لهدايتهم. يغفر ذنب المستغفرين، ويقبل توبة التائبين، ويشدّد العقوبة على من كفر به وعصاه، ذي الإنعام الواسع والفضل العظيم، لا معبود بحق إلا هو، إليه مرجع الخلائق. ثم أخبر رسوله أنه ما يجادل في آيات القرآن الحاوية للحجج القواطع على التوحيد والبعث والنبوة إلا الذين كفروا لظلمة نفوسهم، فاصبر ولا تغترّ بما هم عليه من سعة الرزق وسلامة البدن، فإنهم مُمهَلون لا مُهمَلون؛ والدليل أنه كذّبت قبلهم قوم نوح والأحزاب من بعدهم: عاد وثمود وقوم إبراهيم وقوم لوط وأصحاب مدين وفرعون، وهمّت كل أمة برسولها لتقتله أو تنكّل به، وجادلوا بالباطل كما جادل قومك ليزيلوا به الحق، فأخذتهم فكيف كان عقابي؟ قطع الله دابرهم وأنهى وجودهم. وكما وجب حكمه بإهلاك تلك الأمم حقّت كلمة ربك على الذين كفروا أنهم أصحاب النار، والمراد قوله: لأملأنّ جهنم.", "h": ["تقرير أن القرآن الكريم مصدر تنزيله هو الله تعالى، إذ هو الذي أوحاه ونزّله على رسوله محمد ﷺ، وبذلك تقرّرت نبوته.", "بيان عظمة الرب تعالى المتجلّية في أسمائه: العزيز العليم الحكيم ذي الطول غافر الذنب قابل التوب لا إله إلا هو.", "تقرير التوحيد والبعث والجزاء.", "تقرير مبدأ أن الله تعالى يُمهل ولا يُهمل، وأن بطشه شديد."], "k": "«غافر الذنب وقابل التوب شديد العقاب»… أرجو مغفرته؛ فهل أخشى عقابه بنفس القدر؟"}, {"lbl": "الآيات ٧ – ٩", "q": "ٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ وَيَسۡتَغۡفِرُونَ لِلَّذِينَ ءَامَنُواْۖ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ ﴿٧﴾ رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّـٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّـٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٨﴾ وَقِهِمُ ٱلسَّيِّـَٔاتِۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٩﴾", "w": [["الذين يحملون العرش", "الملائكة حملة العرش."], ["ومن حوله", "والملائكة الذين يحفّون بالعرش من جميع جوانبه."], ["يسبّحون بحمد ربهم", "يقولون: سبحان الله وبحمده، سبحان الله العظيم."], ["ويؤمنون به", "وهم عنده، ولكن هذا من باب الوصف بالكمال."], ["ويستغفرون للذين آمنوا", "يطلبون المغفرة للمؤمنين لرابطة الإيمان بالله التي تجمعهم."], ["ربنا وسعت كل شيء رحمة وعلماً", "يقولون: يا ربنا وسعت كل شيء رحمة وعلماً."], ["فاغفر للذين تابوا واتبعوا سبيلك", "تابوا إليك فعبدوك ووحّدوك واتبعوا سبيلك الذي هو الإسلام."], ["وقِهم عذاب الجحيم", "احفظهم من النار فلا تعذّبهم بها."], ["جنات عدن", "بساتين فيها قصور وأنهار للإقامة الدائمة."], ["التي وعدتهم", "بقوله: إن الله يُدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار."], ["ومن صلح من آبائهم", "من صلح بالإيمان ولم يفسد بالشرك والكفر."], ["وقِهم السيئات", "احفظهم من جزاء السيئات التي عملوها فلا تؤاخذهم بها."], ["فقد رحمته", "حيث سترته ولم تفضحه، وعفوت عنه ولم تعذّبه."], ["وذلك هو الفوز العظيم", "الوقاية من العذاب وإدخال الجنة."]], "m": "يخبر تعالى عن عظمته وموجبات الإيمان به: الذين يحملون عرشه من الملائكة والذين يحفّون به يسبّحون تسبيحاً مقروناً بالحمد: سبحان الله وبحمده، ويؤمنون بوحدانيته، ويستغفرون للذين آمنوا لرابطة الإيمان التي ربطتهم بهم، ولعل هذا سرّ ذكر إيمانهم، لأن المؤمنين إخوة. يقولون متوسّلين إليه بصفاته: ربنا وسعت رحمتك وعلمك سائر المخلوقات، فاغفر للذين تابوا إليك فتركوا الشرك واتبعوا سبيلك الذي هو الإسلام، واحفظهم من عذاب النار، وأدخلهم جنات إقامة، من دخلها لا يخرج منها ولا يبغي عنها حِوَلاً لكمال نعيمها، وأدخل معهم من صلح بالإيمان والتوحيد من آبائهم وأزواجهم وذرياتهم فألحقهم بدرجاتهم وإن قصرت بهم أعمالهم، إنك أنت العزيز الغالب لكل المخلوقات، الحكيم في سائر الكائنات. واحفظهم من جزاء السيئات بأن تغفرها لهم وتسترها عليهم، ومن تقِه جزاء السيئات يوم القيامة فقد رحمته، وذلك أي النجاة من النار ودخول الجنة هو الفوز العظيم، كما قال: فمن زُحزح عن النار وأُدخل الجنة فقد فاز.", "h": ["بيان عظم الرب تعالى.", "بيان فضل الإيمان وأهله.", "فضل التسبيح بقول: سبحان الله وبحمده، فقد صحّ أن من قالها مائة مرة حين يصبح أو حين يمسي غُفرت ذنوبه ولو كانت مثل زبد البحر أي في الكثرة.", "بشرى المؤمنين بأن الله تعالى يجمعهم بآبائهم وأزواجهم وذرياتهم في الجنة، وقد استجاب الله للملائكة وأخبر عن ذلك بقوله: «والذين آمنوا واتبعتهم ذريتهم بإيمان ألحقنا بهم ذريتهم»."], "k": "«ويستغفرون للذين آمنوا»… ملائكة العرش يدعون لي وأنا لا أعرفهم؛ فهل أدعو لإخوتي بظهر الغيب؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 341;
insert into public.tdb_cards(topic, i, body) select 341, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "حمٓ ﴿١﴾ تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ﴿٢﴾ غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ ذِي ٱلطَّوۡلِۖ لَآ إِلَٰهَ إِلَّا هُوَۖ إِلَيۡهِ ٱلۡمَصِيرُ ﴿٣﴾ مَا يُجَٰدِلُ فِيٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُواْ فَلَا يَغۡرُرۡكَ تَقَلُّبُهُمۡ فِي ٱلۡبِلَٰدِ ﴿٤﴾ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَٱلۡأَحۡزَابُ مِنۢ بَعۡدِهِمۡۖ وَهَمَّتۡ كُلُّ أُمَّةِۭ بِرَسُولِهِمۡ لِيَأۡخُذُوهُۖ وَجَٰدَلُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّ فَأَخَذۡتُهُمۡۖ فَكَيۡفَ كَانَ عِقَابِ ﴿٥﴾ وَكَذَٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ أَصۡحَٰبُ ٱلنَّارِ ﴿٦﴾", "w": [["حم", "أحد الحروف المقطعة، يُكتب «حم» ويُقرأ «حا ميم»."], ["تنزيل الكتاب من الله", "تنزيل القرآن كائن من الله."], ["العزيز العليم", "الغالب على مراده، العليم بعباده ظاهراً وباطناً."], ["غافر الذنب", "ذنب من تاب إلى الله فرجع إلى طاعته بعد معصيته."], ["شديد العقاب ذي الطَّول", "مشدّد العقوبة على من كفر به، ذي الإنعام الواسع على من آمن به وأطاعه."], ["لا إله إلا هو إليه المصير", "لا معبود بحق إلا هو، إليه مرجع الخلائق كلهم."], ["ما يجادل في آيات الله إلا الذين كفروا", "ما يجادل في القرآن لإبطاله إلا الكافرون."], ["فلا يغرُرك تقلّبهم في البلاد", "لا تغترّ بمعاشهم سالمين فإن عاقبتهم النار."], ["والأحزاب من بعدهم", "وكذّبت الأحزاب من بعد قوم نوح: عاد وثمود وقوم لوط وغيرهم."], ["وهمّت كل أمة برسولهم ليأخذوه", "ليتمكنوا من إصابته بما أرادوا من تعذيب وقتل."], ["ليُدحضوا به الحق", "ليزيلوا به الحق ويبطلوه."], ["فكيف كان عقاب", "كان واقعاً موقعه حيث أهلكهم ولم يُبق منهم أحداً."], ["كذلك حقّت كلمة ربك", "وجبت كلمة العذاب على الذين كفروا."]], "m": "حم: الله أعلم بمراده به، وقد أفادت هذه الحروف فائدتين: الأولى أن المشركين كانوا يمنعون الناس من سماع القرآن، فكانت هذه الحروف بنغمها الخاص تستهويهم فيسمعون. والثانية أنهم لما أصرّوا على أن القرآن ليس وحياً تحدّاهم الله بالإتيان بمثله وهو مؤلف من هذه الحروف، وقوّى هذا أنه غالباً ما يُذكر القرآن بعدها. تنزيل القرآن من الله العزيز في انتقامه من أعدائه الغالب على أمره، العليم بخلقه وحاجاتهم فأنزله لهدايتهم. يغفر ذنب المستغفرين، ويقبل توبة التائبين، ويشدّد العقوبة على من كفر به وعصاه، ذي الإنعام الواسع والفضل العظيم، لا معبود بحق إلا هو، إليه مرجع الخلائق. ثم أخبر رسوله أنه ما يجادل في آيات القرآن الحاوية للحجج القواطع على التوحيد والبعث والنبوة إلا الذين كفروا لظلمة نفوسهم، فاصبر ولا تغترّ بما هم عليه من سعة الرزق وسلامة البدن، فإنهم مُمهَلون لا مُهمَلون؛ والدليل أنه كذّبت قبلهم قوم نوح والأحزاب من بعدهم: عاد وثمود وقوم إبراهيم وقوم لوط وأصحاب مدين وفرعون، وهمّت كل أمة برسولها لتقتله أو تنكّل به، وجادلوا بالباطل كما جادل قومك ليزيلوا به الحق، فأخذتهم فكيف كان عقابي؟ قطع الله دابرهم وأنهى وجودهم. وكما وجب حكمه بإهلاك تلك الأمم حقّت كلمة ربك على الذين كفروا أنهم أصحاب النار، والمراد قوله: لأملأنّ جهنم.", "h": ["تقرير أن القرآن الكريم مصدر تنزيله هو الله تعالى، إذ هو الذي أوحاه ونزّله على رسوله محمد ﷺ، وبذلك تقرّرت نبوته.", "بيان عظمة الرب تعالى المتجلّية في أسمائه: العزيز العليم الحكيم ذي الطول غافر الذنب قابل التوب لا إله إلا هو.", "تقرير التوحيد والبعث والجزاء.", "تقرير مبدأ أن الله تعالى يُمهل ولا يُهمل، وأن بطشه شديد."], "k": "«غافر الذنب وقابل التوب شديد العقاب»… أرجو مغفرته؛ فهل أخشى عقابه بنفس القدر؟"}, {"lbl": "الآيات ٧ – ٩", "q": "ٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ وَيَسۡتَغۡفِرُونَ لِلَّذِينَ ءَامَنُواْۖ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءٖ رَّحۡمَةٗ وَعِلۡمٗا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ ﴿٧﴾ رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّـٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّـٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٨﴾ وَقِهِمُ ٱلسَّيِّـَٔاتِۚ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوۡمَئِذٖ فَقَدۡ رَحِمۡتَهُۥۚ وَذَٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ ﴿٩﴾", "w": [["الذين يحملون العرش", "الملائكة حملة العرش."], ["ومن حوله", "والملائكة الذين يحفّون بالعرش من جميع جوانبه."], ["يسبّحون بحمد ربهم", "يقولون: سبحان الله وبحمده، سبحان الله العظيم."], ["ويؤمنون به", "وهم عنده، ولكن هذا من باب الوصف بالكمال."], ["ويستغفرون للذين آمنوا", "يطلبون المغفرة للمؤمنين لرابطة الإيمان بالله التي تجمعهم."], ["ربنا وسعت كل شيء رحمة وعلماً", "يقولون: يا ربنا وسعت كل شيء رحمة وعلماً."], ["فاغفر للذين تابوا واتبعوا سبيلك", "تابوا إليك فعبدوك ووحّدوك واتبعوا سبيلك الذي هو الإسلام."], ["وقِهم عذاب الجحيم", "احفظهم من النار فلا تعذّبهم بها."], ["جنات عدن", "بساتين فيها قصور وأنهار للإقامة الدائمة."], ["التي وعدتهم", "بقوله: إن الله يُدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحتها الأنهار."], ["ومن صلح من آبائهم", "من صلح بالإيمان ولم يفسد بالشرك والكفر."], ["وقِهم السيئات", "احفظهم من جزاء السيئات التي عملوها فلا تؤاخذهم بها."], ["فقد رحمته", "حيث سترته ولم تفضحه، وعفوت عنه ولم تعذّبه."], ["وذلك هو الفوز العظيم", "الوقاية من العذاب وإدخال الجنة."]], "m": "يخبر تعالى عن عظمته وموجبات الإيمان به: الذين يحملون عرشه من الملائكة والذين يحفّون به يسبّحون تسبيحاً مقروناً بالحمد: سبحان الله وبحمده، ويؤمنون بوحدانيته، ويستغفرون للذين آمنوا لرابطة الإيمان التي ربطتهم بهم، ولعل هذا سرّ ذكر إيمانهم، لأن المؤمنين إخوة. يقولون متوسّلين إليه بصفاته: ربنا وسعت رحمتك وعلمك سائر المخلوقات، فاغفر للذين تابوا إليك فتركوا الشرك واتبعوا سبيلك الذي هو الإسلام، واحفظهم من عذاب النار، وأدخلهم جنات إقامة، من دخلها لا يخرج منها ولا يبغي عنها حِوَلاً لكمال نعيمها، وأدخل معهم من صلح بالإيمان والتوحيد من آبائهم وأزواجهم وذرياتهم فألحقهم بدرجاتهم وإن قصرت بهم أعمالهم، إنك أنت العزيز الغالب لكل المخلوقات، الحكيم في سائر الكائنات. واحفظهم من جزاء السيئات بأن تغفرها لهم وتسترها عليهم، ومن تقِه جزاء السيئات يوم القيامة فقد رحمته، وذلك أي النجاة من النار ودخول الجنة هو الفوز العظيم، كما قال: فمن زُحزح عن النار وأُدخل الجنة فقد فاز.", "h": ["بيان عظم الرب تعالى.", "بيان فضل الإيمان وأهله.", "فضل التسبيح بقول: سبحان الله وبحمده، فقد صحّ أن من قالها مائة مرة حين يصبح أو حين يمسي غُفرت ذنوبه ولو كانت مثل زبد البحر أي في الكثرة.", "بشرى المؤمنين بأن الله تعالى يجمعهم بآبائهم وأزواجهم وذرياتهم في الجنة، وقد استجاب الله للملائكة وأخبر عن ذلك بقوله: «والذين آمنوا واتبعتهم ذريتهم بإيمان ألحقنا بهم ذريتهم»."], "k": "«ويستغفرون للذين آمنوا»… ملائكة العرش يدعون لي وأنا لا أعرفهم؛ فهل أدعو لإخوتي بظهر الغيب؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (342, 40, 10, 22, 'سورة غافر ١٠ – ٢٢', 'غافر: لمن الملك اليوم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 342) = $j$[{"lbl": "الآيات ١٠ – ١٧", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ يُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِيمَٰنِ فَتَكۡفُرُونَ ﴿١٠﴾ قَالُواْ رَبَّنَآ أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُوجٖ مِّن سَبِيلٖ ﴿١١﴾ ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِيَ ٱللَّهُ وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن يُشۡرَكۡ بِهِۦ تُؤۡمِنُواْۚ فَٱلۡحُكۡمُ لِلَّهِ ٱلۡعَلِيِّ ٱلۡكَبِيرِ ﴿١٢﴾ هُوَ ٱلَّذِي يُرِيكُمۡ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزۡقٗاۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ ﴿١٣﴾ فَٱدۡعُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ﴿١٤﴾ رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلۡعَرۡشِ يُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦ لِيُنذِرَ يَوۡمَ ٱلتَّلَاقِ ﴿١٥﴾ يَوۡمَ هُم بَٰرِزُونَۖ لَا يَخۡفَىٰ عَلَى ٱللَّهِ مِنۡهُمۡ شَيۡءٞۚ لِّمَنِ ٱلۡمُلۡكُ ٱلۡيَوۡمَۖ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ ﴿١٦﴾ ٱلۡيَوۡمَ تُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡۚ لَا ظُلۡمَ ٱلۡيَوۡمَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿١٧﴾", "w": [["يُنادَون لَمقتُ الله", "تناديهم الملائكة: لمقت الله إياكم أكبر من مقتكم أنفسكم، والمقت أشد البغض."], ["إذ تُدعَون إلى الإيمان فتكفرون", "مقت الله لكم حين كنتم في الدنيا تُدعون إلى الإيمان فتكفرون أكبر من مقتكم أنفسكم اليوم."], ["أمتّنا اثنتين وأحييتنا اثنتين", "أمتّنا حين كنا عدماً، وأمتّنا في الدنيا بقبض أرواحنا، وأحييتنا في الدنيا ثم بعد البعث."], ["فاعترفنا بذنوبنا", "التكذيب بآياتك ولقائك والشرك بك."], ["فهل إلى خروج من سبيل", "فهل من طريق إلى العودة إلى الدنيا لنؤمن بك ونوحّدك ونطيعك؟"], ["ذلكم", "العذاب الذي أنتم فيه."], ["بأنه إذا دُعي الله وحده كفرتم", "بسبب أنه إذا دُعي الله وحده كفرتم بالتوحيد."], ["يريكم آياته", "دلائل توحيده وقدرته على بعثكم ومجازاتكم."], ["وما يتذكّر إلا من ينيب", "ما يتعظ إلا من يرجع إلى الله بتوحيده."], ["يُلقي الروح من أمره", "يُلقي الوحي من أمره على من يشاء من عباده."], ["لينذر يوم التلاق", "لينذر الرسول يوم تلاقي أهل السماء وأهل الأرض، يوم القيامة."], ["يوم هم بارزون", "لا يسترهم شيء، لا جبل ولا شجر ولا حجر."], ["لمن الملك اليوم", "لمن السلطان اليوم؟"]], "m": "بعد بيان حال المؤمنين في دار النعيم بيّن حال الكافرين في النار جرياً على أسلوب الترغيب والترهيب: إن الذين كفروا بربهم ولقائه تناديهم الملائكة بعد أن أخذوا في مقت أنفسهم: لمقتُ الله أكبر من مقتكم أنفسكم، لأنكم كنتم تُدعون إلى الإيمان والتوحيد فتكفرون متكبرين. فيقولون في جهنم: ربنا أمتّنا اثنتين وأحييتنا اثنتين، يعنون الموتة الأولى وهم نطف ميتة، والثانية بقبض أرواحهم، والحياة في الدنيا، والحياة بعد البعث، فاعترفنا بذنوبنا من الكفر والشرك والمعاصي، فهل من طريق إلى الخروج والعودة إلى الدنيا لنُصلح ما أفسدنا؟ ولا سبيل إلى ذلك، وبقاؤكم في العذاب جزاء وفاق، ذلكم بأنه إذا دُعي الله وحده كفرتم، وإن يُشرك به تؤمنوا، كقولهم: لبيك لا شريك لك إلا شريكاً هو لك تملكه وما ملك، فالحكم لله العلي الكبير وقد حكم بعذابكم. ثم عاد يخاطب مشركي قريش في الدنيا داعياً لهم: هو الذي يريكم حججه ودلائل وحدانيته، وينزّل لكم من السماء رزقاً من المطر، ومع هذا البيان والإفضال لا يتعظ إلا من شأنه الإنابة. فادعوا الله أيها الموحّدون مخلصين له الدين ولو كره الكافرون فإنه غير ضائركم. هو الله ذو الدرجات الرفيعة والعرش العظيم، يُلقي الوحي من أمره على من يصطفيهم من عباده لينذروا يوم التلاقي، يوم يلتقي أهل الأرض بأهل السماء والمخلوقون بخالقهم، يوم هم بارزون من قبورهم لا يخفى على الله منهم شيء، وفي هذا الموقف يقول الجبار: لمن الملك اليوم؟ فلا يجيبه أحد رهبة، فيجيب نفسه: لله الواحد القهار. اليوم تُجزى كل نفس بما كسبت، لا ظلم اليوم، إن الله سريع الحساب، فلا ينتصف النهار إلا وأهل الجنة في الجنة قائلون في أحسن مقيل.", "h": ["عدم جدوى الاعتذار يوم القيامة، هذا فيما لو أُذن للعبد أن يعتذر فلا ينفعه اعتذار.", "تقرير التوحيد وإبطال الشرك والتنديد.", "بيان أفضال الله على العباد إذ يريهم آياته لهدايتهم ويرزقهم وهم يكفرون به.", "وجوب إخلاص الدعاء وسائر العبادات لله وحده ولو كره ذلك المشركون.", "تقرير النبوة وبيان الحكمة فيها، وهي إنذار الناس من عذاب يوم القيامة حيث الناس بارزون لله لا يخفى على الله منهم شيء، فيحاسبهم بعلمه وعدله، فلا ينقضي نهار إلا وقد استقر أهل الجنة في الجنة وأهل النار في النار."], "k": "«لمن الملك اليوم؟»… سيُسأل هذا السؤال ولا يجيب أحد؛ فلِمن أعمل اليوم؟"}, {"lbl": "الآيات ١٨ – ٢٠", "q": "وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡأٓزِفَةِ إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ كَٰظِمِينَۚ مَا لِلظَّـٰلِمِينَ مِنۡ حَمِيمٖ وَلَا شَفِيعٖ يُطَاعُ ﴿١٨﴾ يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ ﴿١٩﴾ وَٱللَّهُ يَقۡضِي بِٱلۡحَقِّۖ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَقۡضُونَ بِشَيۡءٍۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴿٢٠﴾", "w": [["يوم الآزفة", "يوم القيامة."], ["إذ القلوب لدى الحناجر", "ارتفعت القلوب من شدة الخوف إلى الحناجر."], ["كاظمين", "لقلوبهم يريدون ردّها فلم يقدروا."], ["ما للظالمين من حميم", "ليس للمشركين من محب قريباً كان أو بعيداً."], ["يعلم خائنة الأعين", "يعلم العين إذا سرقت النظر إلى محرم."], ["والله يقضي بالحق", "لكمال قدرته وعلمه يحكم بالحق."], ["والذين يدعون من دونه لا يقضون بشيء", "أصنام مشركي قريش لا تقضي بشيء عدلاً كان أو جوراً لأنها لا تسمع ولا تبصر."]], "m": "بعد بيان الموقف الصعب يوم القيامة قال تعالى لرسوله: وأنذرهم يوم الآزفة، يوم القيامة القريبة، وكل ما هو آتٍ قريب، أنذرهم قربها حتى لا يوافوها بالشرك والمعاصي فيخسروا، إذ القلوب من شدة الخوف ترتفع إلى الحناجر وهم يكظمونها، فلا هي تخرج فيموتوا ولا هي تعود إلى أماكنها فيستريحوا. ما للظالمين من قريب أو حبيب يدفع عنهم العذاب، ولا شفيع تُقبل شفاعته، فيا لفظاعة الحال! يعلم خائنة الأعين وهي العين تسترق النظر إلى المحارم، ويعلم ما تكتمه صدور العباد من خير وشر، ولذا سيكون الحساب دقيقاً، ومن نوقش الحساب عُذّب. والله يحكم بالعدل، والذين يعبدهم المشركون من أصنام لا يقضون بشيء لأنهم لا يسمعون ولا يبصرون، إن الله هو السميع لأقوال عباده البصير بأعمالهم، فإذا حكم حكم بالحق وقدر على إنفاذه، فيجزي السيئة بالسيئة والحسنة بعشر أمثالها.", "h": ["بيان هول يوم القيامة وصعوبة الموقف فيه.", "انعدام الحميم والشفيع للظالمين يوم القيامة.", "بيان سعة علم الله تعالى حتى إنه يعلم خائنة الأعين وما تخفي الصدور.", "قضاء الله عدل وحكمه نافذ، وذلك لكمال علمه وقدرته."], "k": "«يعلم خائنة الأعين»… النظرة التي ظننتها خفية يعلمها؛ فهل أحفظ عيني كما أحفظ لساني؟"}, {"lbl": "الآيتان ٢١ – ٢٢", "q": "۞أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُواْ مِن قَبۡلِهِمۡۚ كَانُواْ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ ﴿٢١﴾ ذَٰلِكَ بِأَنَّهُمۡ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَكَفَرُواْ فَأَخَذَهُمُ ٱللَّهُۚ إِنَّهُۥ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ ﴿٢٢﴾", "w": [["أوَلم يسيروا في الأرض", "أغفل كفار قريش ولم يسيروا في الأرض؟"], ["فينظروا", "بأعينهم."], ["كيف كان عاقبة الذين كانوا من قبلهم", "كانت دماراً وخساراً ووبالاً عليهم."], ["كانوا هم أشد منهم قوة وآثاراً في الأرض", "ولم يغن ذلك عنهم من الله شيئاً."], ["فأخذهم الله بذنوبهم", "عاقبهم بذنوبهم فدمّرهم وأهلكهم."], ["وما كان لهم من الله من واق", "لم يوجد لهم من عقاب الله من واقٍ يقيهم منه."], ["بالبيّنات", "بالحجج والبراهين والأدلة والمعجزات."], ["إنه قوي شديد العقاب", "تعليل لأخذه إياهم."]], "m": "تقدّم تخويف مشركي قريش بعذاب الآخرة، ومبالغة في نصحهم خوّفهم بعذاب الدنيا لعلهم يتوبون: أغفل هؤلاء المعاندون ولم يسيروا في البلاد شمالاً وجنوباً، حيث ديار عاد في الجنوب وديار ثمود في الشمال، فينظروا بأعينهم كيف كان عاقبة من قبلهم؟ كانوا أشد منهم قوة وآثاراً في الأرض من البناء والعمران والقدرة على الحرب، فأخذهم الله بذنوب الشرك والتكذيب والمعاصي، ولم يوجد لهم من عذابه واقٍ. فما لهؤلاء لا يعتبرون؟ والعاقل من اعتبر بغيره. ذلك بأنهم كانت تأتيهم رسلهم بالبيّنات فكفروا فأخذهم الله؛ فما أخذهم إلا بعد أن أنذرهم وأعذر إليهم، إنه قوي شديد العقاب.", "h": ["تقرير الحكمة القائلة: العاقل من اعتبر بغيره.", "الأخذ بالذنوب سنة من سنن الله في الأرض لا تتبدّل ولا تتحوّل.", "من أراد الله عقابه لا يوجد له واقٍ يقيه ولا حامٍ يحميه، ومن تاب تاب الله عليه."], "k": "«فأخذهم الله بذنوبهم»… الذنب لا يمضي بلا أثر؛ فهل أنا ممن يعتبر بغيره؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 342;
insert into public.tdb_cards(topic, i, body) select 342, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠ – ١٧", "q": "إِنَّ ٱلَّذِينَ كَفَرُواْ يُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِيمَٰنِ فَتَكۡفُرُونَ ﴿١٠﴾ قَالُواْ رَبَّنَآ أَمَتَّنَا ٱثۡنَتَيۡنِ وَأَحۡيَيۡتَنَا ٱثۡنَتَيۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُوجٖ مِّن سَبِيلٖ ﴿١١﴾ ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِيَ ٱللَّهُ وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن يُشۡرَكۡ بِهِۦ تُؤۡمِنُواْۚ فَٱلۡحُكۡمُ لِلَّهِ ٱلۡعَلِيِّ ٱلۡكَبِيرِ ﴿١٢﴾ هُوَ ٱلَّذِي يُرِيكُمۡ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزۡقٗاۚ وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ ﴿١٣﴾ فَٱدۡعُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ وَلَوۡ كَرِهَ ٱلۡكَٰفِرُونَ ﴿١٤﴾ رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلۡعَرۡشِ يُلۡقِي ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦ لِيُنذِرَ يَوۡمَ ٱلتَّلَاقِ ﴿١٥﴾ يَوۡمَ هُم بَٰرِزُونَۖ لَا يَخۡفَىٰ عَلَى ٱللَّهِ مِنۡهُمۡ شَيۡءٞۚ لِّمَنِ ٱلۡمُلۡكُ ٱلۡيَوۡمَۖ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ ﴿١٦﴾ ٱلۡيَوۡمَ تُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡۚ لَا ظُلۡمَ ٱلۡيَوۡمَۚ إِنَّ ٱللَّهَ سَرِيعُ ٱلۡحِسَابِ ﴿١٧﴾", "w": [["يُنادَون لَمقتُ الله", "تناديهم الملائكة: لمقت الله إياكم أكبر من مقتكم أنفسكم، والمقت أشد البغض."], ["إذ تُدعَون إلى الإيمان فتكفرون", "مقت الله لكم حين كنتم في الدنيا تُدعون إلى الإيمان فتكفرون أكبر من مقتكم أنفسكم اليوم."], ["أمتّنا اثنتين وأحييتنا اثنتين", "أمتّنا حين كنا عدماً، وأمتّنا في الدنيا بقبض أرواحنا، وأحييتنا في الدنيا ثم بعد البعث."], ["فاعترفنا بذنوبنا", "التكذيب بآياتك ولقائك والشرك بك."], ["فهل إلى خروج من سبيل", "فهل من طريق إلى العودة إلى الدنيا لنؤمن بك ونوحّدك ونطيعك؟"], ["ذلكم", "العذاب الذي أنتم فيه."], ["بأنه إذا دُعي الله وحده كفرتم", "بسبب أنه إذا دُعي الله وحده كفرتم بالتوحيد."], ["يريكم آياته", "دلائل توحيده وقدرته على بعثكم ومجازاتكم."], ["وما يتذكّر إلا من ينيب", "ما يتعظ إلا من يرجع إلى الله بتوحيده."], ["يُلقي الروح من أمره", "يُلقي الوحي من أمره على من يشاء من عباده."], ["لينذر يوم التلاق", "لينذر الرسول يوم تلاقي أهل السماء وأهل الأرض، يوم القيامة."], ["يوم هم بارزون", "لا يسترهم شيء، لا جبل ولا شجر ولا حجر."], ["لمن الملك اليوم", "لمن السلطان اليوم؟"]], "m": "بعد بيان حال المؤمنين في دار النعيم بيّن حال الكافرين في النار جرياً على أسلوب الترغيب والترهيب: إن الذين كفروا بربهم ولقائه تناديهم الملائكة بعد أن أخذوا في مقت أنفسهم: لمقتُ الله أكبر من مقتكم أنفسكم، لأنكم كنتم تُدعون إلى الإيمان والتوحيد فتكفرون متكبرين. فيقولون في جهنم: ربنا أمتّنا اثنتين وأحييتنا اثنتين، يعنون الموتة الأولى وهم نطف ميتة، والثانية بقبض أرواحهم، والحياة في الدنيا، والحياة بعد البعث، فاعترفنا بذنوبنا من الكفر والشرك والمعاصي، فهل من طريق إلى الخروج والعودة إلى الدنيا لنُصلح ما أفسدنا؟ ولا سبيل إلى ذلك، وبقاؤكم في العذاب جزاء وفاق، ذلكم بأنه إذا دُعي الله وحده كفرتم، وإن يُشرك به تؤمنوا، كقولهم: لبيك لا شريك لك إلا شريكاً هو لك تملكه وما ملك، فالحكم لله العلي الكبير وقد حكم بعذابكم. ثم عاد يخاطب مشركي قريش في الدنيا داعياً لهم: هو الذي يريكم حججه ودلائل وحدانيته، وينزّل لكم من السماء رزقاً من المطر، ومع هذا البيان والإفضال لا يتعظ إلا من شأنه الإنابة. فادعوا الله أيها الموحّدون مخلصين له الدين ولو كره الكافرون فإنه غير ضائركم. هو الله ذو الدرجات الرفيعة والعرش العظيم، يُلقي الوحي من أمره على من يصطفيهم من عباده لينذروا يوم التلاقي، يوم يلتقي أهل الأرض بأهل السماء والمخلوقون بخالقهم، يوم هم بارزون من قبورهم لا يخفى على الله منهم شيء، وفي هذا الموقف يقول الجبار: لمن الملك اليوم؟ فلا يجيبه أحد رهبة، فيجيب نفسه: لله الواحد القهار. اليوم تُجزى كل نفس بما كسبت، لا ظلم اليوم، إن الله سريع الحساب، فلا ينتصف النهار إلا وأهل الجنة في الجنة قائلون في أحسن مقيل.", "h": ["عدم جدوى الاعتذار يوم القيامة، هذا فيما لو أُذن للعبد أن يعتذر فلا ينفعه اعتذار.", "تقرير التوحيد وإبطال الشرك والتنديد.", "بيان أفضال الله على العباد إذ يريهم آياته لهدايتهم ويرزقهم وهم يكفرون به.", "وجوب إخلاص الدعاء وسائر العبادات لله وحده ولو كره ذلك المشركون.", "تقرير النبوة وبيان الحكمة فيها، وهي إنذار الناس من عذاب يوم القيامة حيث الناس بارزون لله لا يخفى على الله منهم شيء، فيحاسبهم بعلمه وعدله، فلا ينقضي نهار إلا وقد استقر أهل الجنة في الجنة وأهل النار في النار."], "k": "«لمن الملك اليوم؟»… سيُسأل هذا السؤال ولا يجيب أحد؛ فلِمن أعمل اليوم؟"}, {"lbl": "الآيات ١٨ – ٢٠", "q": "وَأَنذِرۡهُمۡ يَوۡمَ ٱلۡأٓزِفَةِ إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ كَٰظِمِينَۚ مَا لِلظَّـٰلِمِينَ مِنۡ حَمِيمٖ وَلَا شَفِيعٖ يُطَاعُ ﴿١٨﴾ يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ ﴿١٩﴾ وَٱللَّهُ يَقۡضِي بِٱلۡحَقِّۖ وَٱلَّذِينَ يَدۡعُونَ مِن دُونِهِۦ لَا يَقۡضُونَ بِشَيۡءٍۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴿٢٠﴾", "w": [["يوم الآزفة", "يوم القيامة."], ["إذ القلوب لدى الحناجر", "ارتفعت القلوب من شدة الخوف إلى الحناجر."], ["كاظمين", "لقلوبهم يريدون ردّها فلم يقدروا."], ["ما للظالمين من حميم", "ليس للمشركين من محب قريباً كان أو بعيداً."], ["يعلم خائنة الأعين", "يعلم العين إذا سرقت النظر إلى محرم."], ["والله يقضي بالحق", "لكمال قدرته وعلمه يحكم بالحق."], ["والذين يدعون من دونه لا يقضون بشيء", "أصنام مشركي قريش لا تقضي بشيء عدلاً كان أو جوراً لأنها لا تسمع ولا تبصر."]], "m": "بعد بيان الموقف الصعب يوم القيامة قال تعالى لرسوله: وأنذرهم يوم الآزفة، يوم القيامة القريبة، وكل ما هو آتٍ قريب، أنذرهم قربها حتى لا يوافوها بالشرك والمعاصي فيخسروا، إذ القلوب من شدة الخوف ترتفع إلى الحناجر وهم يكظمونها، فلا هي تخرج فيموتوا ولا هي تعود إلى أماكنها فيستريحوا. ما للظالمين من قريب أو حبيب يدفع عنهم العذاب، ولا شفيع تُقبل شفاعته، فيا لفظاعة الحال! يعلم خائنة الأعين وهي العين تسترق النظر إلى المحارم، ويعلم ما تكتمه صدور العباد من خير وشر، ولذا سيكون الحساب دقيقاً، ومن نوقش الحساب عُذّب. والله يحكم بالعدل، والذين يعبدهم المشركون من أصنام لا يقضون بشيء لأنهم لا يسمعون ولا يبصرون، إن الله هو السميع لأقوال عباده البصير بأعمالهم، فإذا حكم حكم بالحق وقدر على إنفاذه، فيجزي السيئة بالسيئة والحسنة بعشر أمثالها.", "h": ["بيان هول يوم القيامة وصعوبة الموقف فيه.", "انعدام الحميم والشفيع للظالمين يوم القيامة.", "بيان سعة علم الله تعالى حتى إنه يعلم خائنة الأعين وما تخفي الصدور.", "قضاء الله عدل وحكمه نافذ، وذلك لكمال علمه وقدرته."], "k": "«يعلم خائنة الأعين»… النظرة التي ظننتها خفية يعلمها؛ فهل أحفظ عيني كما أحفظ لساني؟"}, {"lbl": "الآيتان ٢١ – ٢٢", "q": "۞أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُواْ مِن قَبۡلِهِمۡۚ كَانُواْ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٖ ﴿٢١﴾ ذَٰلِكَ بِأَنَّهُمۡ كَانَت تَّأۡتِيهِمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَكَفَرُواْ فَأَخَذَهُمُ ٱللَّهُۚ إِنَّهُۥ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ ﴿٢٢﴾", "w": [["أوَلم يسيروا في الأرض", "أغفل كفار قريش ولم يسيروا في الأرض؟"], ["فينظروا", "بأعينهم."], ["كيف كان عاقبة الذين كانوا من قبلهم", "كانت دماراً وخساراً ووبالاً عليهم."], ["كانوا هم أشد منهم قوة وآثاراً في الأرض", "ولم يغن ذلك عنهم من الله شيئاً."], ["فأخذهم الله بذنوبهم", "عاقبهم بذنوبهم فدمّرهم وأهلكهم."], ["وما كان لهم من الله من واق", "لم يوجد لهم من عقاب الله من واقٍ يقيهم منه."], ["بالبيّنات", "بالحجج والبراهين والأدلة والمعجزات."], ["إنه قوي شديد العقاب", "تعليل لأخذه إياهم."]], "m": "تقدّم تخويف مشركي قريش بعذاب الآخرة، ومبالغة في نصحهم خوّفهم بعذاب الدنيا لعلهم يتوبون: أغفل هؤلاء المعاندون ولم يسيروا في البلاد شمالاً وجنوباً، حيث ديار عاد في الجنوب وديار ثمود في الشمال، فينظروا بأعينهم كيف كان عاقبة من قبلهم؟ كانوا أشد منهم قوة وآثاراً في الأرض من البناء والعمران والقدرة على الحرب، فأخذهم الله بذنوب الشرك والتكذيب والمعاصي، ولم يوجد لهم من عذابه واقٍ. فما لهؤلاء لا يعتبرون؟ والعاقل من اعتبر بغيره. ذلك بأنهم كانت تأتيهم رسلهم بالبيّنات فكفروا فأخذهم الله؛ فما أخذهم إلا بعد أن أنذرهم وأعذر إليهم، إنه قوي شديد العقاب.", "h": ["تقرير الحكمة القائلة: العاقل من اعتبر بغيره.", "الأخذ بالذنوب سنة من سنن الله في الأرض لا تتبدّل ولا تتحوّل.", "من أراد الله عقابه لا يوجد له واقٍ يقيه ولا حامٍ يحميه، ومن تاب تاب الله عليه."], "k": "«فأخذهم الله بذنوبهم»… الذنب لا يمضي بلا أثر؛ فهل أنا ممن يعتبر بغيره؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (343, 40, 23, 29, 'سورة غافر ٢٣ – ٢٩', 'غافر: أتقتلون رجلاً أن يقول ربي الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 343) = $j$[{"lbl": "الآيات ٢٣ – ٢٧", "q": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ﴿٢٣﴾ إِلَىٰ فِرۡعَوۡنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُواْ سَٰحِرٞ كَذَّابٞ ﴿٢٤﴾ فَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ﴿٢٥﴾ وَقَالَ فِرۡعَوۡنُ ذَرُونِيٓ أَقۡتُلۡ مُوسَىٰ وَلۡيَدۡعُ رَبَّهُۥٓۖ إِنِّيٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمۡ أَوۡ أَن يُظۡهِرَ فِي ٱلۡأَرۡضِ ٱلۡفَسَادَ ﴿٢٦﴾ وَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ لَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ ﴿٢٧﴾", "w": [["بآياتنا وسلطان مبين", "بحججنا وبرهان بيّن ظاهر."], ["هامان وقارون", "هامان وزير فرعون، وقارون رجل الملايين."], ["فقالوا ساحر كذّاب", "لما رأوا آية العصا واليد البيضاء قالوا ذلك صدّاً لقومهم حتى لا يؤمنوا به."], ["فلما جاءهم بالحق من عندنا", "جاءهم موسى بالصدق فيما أخبرهم به من أنه رسول الله، وطالبهم بإرسال بني إسرائيل معه."], ["اقتلوا أبناء الذين آمنوا معه", "الأولاد الذكران."], ["واستحيوا نساءهم", "بناتهم، بمعنى اتركوهن حيّات."], ["وما كيد الكافرين إلا في ضلال", "ما مكرهم إلا في خسران وضياع."], ["ذروني أقتل موسى وليدع ربه", "دعوني أقتله، وليدع ربه ليمنعه مني."], ["أن يبدّل دينكم", "يغيّر عبادتكم لآلهتكم إلى عبادة إلهه."], ["أو أن يُظهر في الأرض الفساد", "بالقتل والتخريب ونحوه."], ["إني عذت بربي وربكم", "استجرت بخالقي وخالقكم."], ["من كل متكبر لا يؤمن بيوم الحساب", "من كل إنسان متكبر لا يؤمن بيوم الحساب والجزاء."]], "m": "بعد تلك الدعوة الربانية لقريش، والمشركون لا يزدادون إلا عتواً، قصّ الله على رسوله قصة موسى مع فرعون ليسلّيه ويصبّره، وليعلمه أن البلاء مهما اشتد يعقبه الفرج، وأن الله ناصره كما نصر موسى: ولقد أرسلنا موسى بن عمران بأدلتنا وبرهان ظاهر إلى فرعون، وهامان وزيره، وقارون من أرباب الملايين، وهو وإن كان من بني إسرائيل إلا أنه مالأ فرعون ووقف في صفه، فلما بلّغهم موسى الحجج قالوا: ساحر كذّاب، حماية لمصالحهم وخوفاً من تغيير الوضع عليهم. فلما جاءهم بالصدق من عند الله كان ردّ فعلهم أن أمروا بقتل الذكور من أولاد الذين آمنوا معه واستحياء بناتهم للخدمة والامتهان، وما كيد الكافرين إلا في ضلال، وهذا عام في كل كيد كافر يبطله الله ولا يضرّ به أولياءه. وقال فرعون، بعد أن انهزم في ميادين عدة وأراد أن يسترد بعض ما فقد: اتركوني أقتل موسى وليدع ربه ليمنعه مني، إني أخاف أن يغلب عليكم فتدينوا بدينه، أو أن يُظهر في الأرض الفساد. فقال موسى لما سمع تهديده: إني عذت بربي وربكم من كل متكبر لا يؤمن بيوم الحساب؛ فأعلمهم أنه استجار بالله وتحصّن به فلا يقدر أحد على قتله، لأن من يؤمن بيوم الحساب لا يُقدم على القتل، وإنما يُقدم عليه من لا يؤمن بحساب ولا جزاء.", "h": ["تسلية الرسول ﷺ وحمله على الصبر والتحمل وهو في أشد الظروف صعوبة.", "عدم تورّع الظلمة في كل زمان عن الكذب وتلفيق التهم للأبرياء.", "التهديد بالقتل شنشنة الجبارين والطغاة في العالم.", "أحسن ملاذ للمؤمن من كل خوف هو الله تعالى رب المستضعفين."], "k": "«إني عذت بربي وربكم»… حين يهدّدني أحد، هل أستجير بالله أولاً؟"}, {"lbl": "الآيتان ٢٨ – ٢٩", "q": "وَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ وَإِن يَكُ كَٰذِبٗا فَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ مُسۡرِفٞ كَذَّابٞ ﴿٢٨﴾ يَٰقَوۡمِ لَكُمُ ٱلۡمُلۡكُ ٱلۡيَوۡمَ ظَٰهِرِينَ فِي ٱلۡأَرۡضِ فَمَن يَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ إِن جَآءَنَاۚ قَالَ فِرۡعَوۡنُ مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ وَمَآ أَهۡدِيكُمۡ إِلَّا سَبِيلَ ٱلرَّشَادِ ﴿٢٩﴾", "w": [["وقال رجل مؤمن من آل فرعون", "هو شمعان ابن عم فرعون."], ["أتقتلون رجلاً أن يقول ربي الله", "لأن يقول ربي الله؟ والرجل هو موسى ﵇."], ["بالبيّنات من ربكم", "بالمعجزات الظاهرات."], ["فعليه كذبه", "ضرر كذبه عليه لا عليكم."], ["يُصبكم بعض الذي يعدكم", "بعض العذاب الذي يعدكم به في الدنيا عاجلاً."], ["من هو مسرف كذّاب", "مسرف في الكفر والظلم، كذّاب لا يقول الصدق."], ["ظاهرين في الأرض", "غالبين في بلاد مصر وأراضيها."], ["فمن ينصرنا من بأس الله إن جاءنا", "من عذاب الله إن جاءنا وقد قتلنا أولياءه."], ["ما أُريكم إلا ما أرى", "ما أشير به عليكم إلا ما أشير به على نفسي، وهو قتل موسى."], ["وما أهديكم إلا سبيل الرشاد", "إلا طريق الرشد والصواب."]], "m": "ما زال السياق فيما دار في قصر فرعون: أبدى فرعون رغبته في إعدام موسى معلّلاً بأمرين: أن يبدّل دين الدولة والشعب، وأن يُظهر الشغب في البلاد. وهذا رجل مؤمن من رجالات القصر يكتم إيمانه بموسى خوفاً من فرعون وملئه، هو ابن عم فرعون واسمه شمعان، قال منكراً عليهم قرار القتل: أتقتلون رجلاً لأن قال ربي الله، وقد جاءكم بالحجج كالعصا واليد من ربكم الحق؟ وإن فرضنا أنه كاذب فضرر كذبه عائد عليه، وإن يك صادقاً وهو صادق يصبكم بعض الذي يعدكم من العذاب العاجل، إن الله لا يوفّق إلى النصر من هو متجاوز الحد في الظلم كذّاب يعيش على الكذب. ثم أقبل يعظهم: يا قوم لكم الملك اليوم غالبين في أرض مصر، لكن إن أسرفنا فقتلنا أولياء الله فجاءنا بأسه فمن ينصرنا؟ لا ناصر لنا من الله أبداً. فردّ فرعون: ما أشير عليكم إلا بما رأيته صائباً، يعني قتل موسى، وما أهديكم إلا طريق الحق والصواب، وكذب.", "h": ["فضل الإيمان وفضل صاحبه، فقد ورد الثناء على هذا الرجل في ثلاثة رجال هم: مؤمن آل فرعون هذا، وحبيب النجار مؤمن آل ياسين، وأبو بكر الصديق رضي الله عنه.", "فصاحة مؤمن آل فرعون هي ثمرة إيمانه وبركته العاجلة، فإن لكلماته وقعاً كبيراً في النفوس.", "التنديد بالإسراف في كل شيء، والكذب والافتراء في كل شيء وعلى أي شيء.", "من عجيب أمر فرعون ادعاؤه أنه يهدي إلى الرشد والسداد والصواب في القول والعمل، حتى ضُرب به المثل فقيل: فرعون يهدي إلى الرشد."], "k": "«أتقتلون رجلاً أن يقول ربي الله»… قالها وحده في قصر الطاغية؛ فهل أقول الحق حين يسكت الجميع؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 343;
insert into public.tdb_cards(topic, i, body) select 343, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٣ – ٢٧", "q": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ ﴿٢٣﴾ إِلَىٰ فِرۡعَوۡنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُواْ سَٰحِرٞ كَذَّابٞ ﴿٢٤﴾ فَلَمَّا جَآءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُواْ ٱقۡتُلُوٓاْ أَبۡنَآءَ ٱلَّذِينَ ءَامَنُواْ مَعَهُۥ وَٱسۡتَحۡيُواْ نِسَآءَهُمۡۚ وَمَا كَيۡدُ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٖ ﴿٢٥﴾ وَقَالَ فِرۡعَوۡنُ ذَرُونِيٓ أَقۡتُلۡ مُوسَىٰ وَلۡيَدۡعُ رَبَّهُۥٓۖ إِنِّيٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمۡ أَوۡ أَن يُظۡهِرَ فِي ٱلۡأَرۡضِ ٱلۡفَسَادَ ﴿٢٦﴾ وَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ لَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ ﴿٢٧﴾", "w": [["بآياتنا وسلطان مبين", "بحججنا وبرهان بيّن ظاهر."], ["هامان وقارون", "هامان وزير فرعون، وقارون رجل الملايين."], ["فقالوا ساحر كذّاب", "لما رأوا آية العصا واليد البيضاء قالوا ذلك صدّاً لقومهم حتى لا يؤمنوا به."], ["فلما جاءهم بالحق من عندنا", "جاءهم موسى بالصدق فيما أخبرهم به من أنه رسول الله، وطالبهم بإرسال بني إسرائيل معه."], ["اقتلوا أبناء الذين آمنوا معه", "الأولاد الذكران."], ["واستحيوا نساءهم", "بناتهم، بمعنى اتركوهن حيّات."], ["وما كيد الكافرين إلا في ضلال", "ما مكرهم إلا في خسران وضياع."], ["ذروني أقتل موسى وليدع ربه", "دعوني أقتله، وليدع ربه ليمنعه مني."], ["أن يبدّل دينكم", "يغيّر عبادتكم لآلهتكم إلى عبادة إلهه."], ["أو أن يُظهر في الأرض الفساد", "بالقتل والتخريب ونحوه."], ["إني عذت بربي وربكم", "استجرت بخالقي وخالقكم."], ["من كل متكبر لا يؤمن بيوم الحساب", "من كل إنسان متكبر لا يؤمن بيوم الحساب والجزاء."]], "m": "بعد تلك الدعوة الربانية لقريش، والمشركون لا يزدادون إلا عتواً، قصّ الله على رسوله قصة موسى مع فرعون ليسلّيه ويصبّره، وليعلمه أن البلاء مهما اشتد يعقبه الفرج، وأن الله ناصره كما نصر موسى: ولقد أرسلنا موسى بن عمران بأدلتنا وبرهان ظاهر إلى فرعون، وهامان وزيره، وقارون من أرباب الملايين، وهو وإن كان من بني إسرائيل إلا أنه مالأ فرعون ووقف في صفه، فلما بلّغهم موسى الحجج قالوا: ساحر كذّاب، حماية لمصالحهم وخوفاً من تغيير الوضع عليهم. فلما جاءهم بالصدق من عند الله كان ردّ فعلهم أن أمروا بقتل الذكور من أولاد الذين آمنوا معه واستحياء بناتهم للخدمة والامتهان، وما كيد الكافرين إلا في ضلال، وهذا عام في كل كيد كافر يبطله الله ولا يضرّ به أولياءه. وقال فرعون، بعد أن انهزم في ميادين عدة وأراد أن يسترد بعض ما فقد: اتركوني أقتل موسى وليدع ربه ليمنعه مني، إني أخاف أن يغلب عليكم فتدينوا بدينه، أو أن يُظهر في الأرض الفساد. فقال موسى لما سمع تهديده: إني عذت بربي وربكم من كل متكبر لا يؤمن بيوم الحساب؛ فأعلمهم أنه استجار بالله وتحصّن به فلا يقدر أحد على قتله، لأن من يؤمن بيوم الحساب لا يُقدم على القتل، وإنما يُقدم عليه من لا يؤمن بحساب ولا جزاء.", "h": ["تسلية الرسول ﷺ وحمله على الصبر والتحمل وهو في أشد الظروف صعوبة.", "عدم تورّع الظلمة في كل زمان عن الكذب وتلفيق التهم للأبرياء.", "التهديد بالقتل شنشنة الجبارين والطغاة في العالم.", "أحسن ملاذ للمؤمن من كل خوف هو الله تعالى رب المستضعفين."], "k": "«إني عذت بربي وربكم»… حين يهدّدني أحد، هل أستجير بالله أولاً؟"}, {"lbl": "الآيتان ٢٨ – ٢٩", "q": "وَقَالَ رَجُلٞ مُّؤۡمِنٞ مِّنۡ ءَالِ فِرۡعَوۡنَ يَكۡتُمُ إِيمَٰنَهُۥٓ أَتَقۡتُلُونَ رَجُلًا أَن يَقُولَ رَبِّيَ ٱللَّهُ وَقَدۡ جَآءَكُم بِٱلۡبَيِّنَٰتِ مِن رَّبِّكُمۡۖ وَإِن يَكُ كَٰذِبٗا فَعَلَيۡهِ كَذِبُهُۥۖ وَإِن يَكُ صَادِقٗا يُصِبۡكُم بَعۡضُ ٱلَّذِي يَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا يَهۡدِي مَنۡ هُوَ مُسۡرِفٞ كَذَّابٞ ﴿٢٨﴾ يَٰقَوۡمِ لَكُمُ ٱلۡمُلۡكُ ٱلۡيَوۡمَ ظَٰهِرِينَ فِي ٱلۡأَرۡضِ فَمَن يَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ إِن جَآءَنَاۚ قَالَ فِرۡعَوۡنُ مَآ أُرِيكُمۡ إِلَّا مَآ أَرَىٰ وَمَآ أَهۡدِيكُمۡ إِلَّا سَبِيلَ ٱلرَّشَادِ ﴿٢٩﴾", "w": [["وقال رجل مؤمن من آل فرعون", "هو شمعان ابن عم فرعون."], ["أتقتلون رجلاً أن يقول ربي الله", "لأن يقول ربي الله؟ والرجل هو موسى ﵇."], ["بالبيّنات من ربكم", "بالمعجزات الظاهرات."], ["فعليه كذبه", "ضرر كذبه عليه لا عليكم."], ["يُصبكم بعض الذي يعدكم", "بعض العذاب الذي يعدكم به في الدنيا عاجلاً."], ["من هو مسرف كذّاب", "مسرف في الكفر والظلم، كذّاب لا يقول الصدق."], ["ظاهرين في الأرض", "غالبين في بلاد مصر وأراضيها."], ["فمن ينصرنا من بأس الله إن جاءنا", "من عذاب الله إن جاءنا وقد قتلنا أولياءه."], ["ما أُريكم إلا ما أرى", "ما أشير به عليكم إلا ما أشير به على نفسي، وهو قتل موسى."], ["وما أهديكم إلا سبيل الرشاد", "إلا طريق الرشد والصواب."]], "m": "ما زال السياق فيما دار في قصر فرعون: أبدى فرعون رغبته في إعدام موسى معلّلاً بأمرين: أن يبدّل دين الدولة والشعب، وأن يُظهر الشغب في البلاد. وهذا رجل مؤمن من رجالات القصر يكتم إيمانه بموسى خوفاً من فرعون وملئه، هو ابن عم فرعون واسمه شمعان، قال منكراً عليهم قرار القتل: أتقتلون رجلاً لأن قال ربي الله، وقد جاءكم بالحجج كالعصا واليد من ربكم الحق؟ وإن فرضنا أنه كاذب فضرر كذبه عائد عليه، وإن يك صادقاً وهو صادق يصبكم بعض الذي يعدكم من العذاب العاجل، إن الله لا يوفّق إلى النصر من هو متجاوز الحد في الظلم كذّاب يعيش على الكذب. ثم أقبل يعظهم: يا قوم لكم الملك اليوم غالبين في أرض مصر، لكن إن أسرفنا فقتلنا أولياء الله فجاءنا بأسه فمن ينصرنا؟ لا ناصر لنا من الله أبداً. فردّ فرعون: ما أشير عليكم إلا بما رأيته صائباً، يعني قتل موسى، وما أهديكم إلا طريق الحق والصواب، وكذب.", "h": ["فضل الإيمان وفضل صاحبه، فقد ورد الثناء على هذا الرجل في ثلاثة رجال هم: مؤمن آل فرعون هذا، وحبيب النجار مؤمن آل ياسين، وأبو بكر الصديق رضي الله عنه.", "فصاحة مؤمن آل فرعون هي ثمرة إيمانه وبركته العاجلة، فإن لكلماته وقعاً كبيراً في النفوس.", "التنديد بالإسراف في كل شيء، والكذب والافتراء في كل شيء وعلى أي شيء.", "من عجيب أمر فرعون ادعاؤه أنه يهدي إلى الرشد والسداد والصواب في القول والعمل، حتى ضُرب به المثل فقيل: فرعون يهدي إلى الرشد."], "k": "«أتقتلون رجلاً أن يقول ربي الله»… قالها وحده في قصر الطاغية؛ فهل أقول الحق حين يسكت الجميع؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (344, 40, 30, 40, 'سورة غافر ٣٠ – ٤٠', 'غافر: يا قوم اتبعون أهدكم سبيل الرشاد', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 344) = $j$[{"lbl": "الآيات ٣٠ – ٣٥", "q": "وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ ﴿٣٠﴾ مِثۡلَ دَأۡبِ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعِبَادِ ﴿٣١﴾ وَيَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ يَوۡمَ ٱلتَّنَادِ ﴿٣٢﴾ يَوۡمَ تُوَلُّونَ مُدۡبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ ﴿٣٣﴾ وَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي شَكّٖ مِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ مُّرۡتَابٌ ﴿٣٤﴾ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡۖ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلۡبِ مُتَكَبِّرٖ جَبَّارٖ ﴿٣٥﴾", "w": [["وقال الذي آمن", "مؤمن آل فرعون."], ["مثل يوم الأحزاب", "عذاباً مثل عذاب الأحزاب، وهم قوم نوح وعاد وثمود."], ["مثل دأب قوم نوح", "مثل جزاء عادة من كفر قبلكم، وهي استمرارهم على الكفر حتى الهلاك."], ["يوم التناد", "يوم القيامة، سُمّي بذلك لكثرة النداءات فيه، إذ ينادي أصحاب الجنة أصحاب النار وأصحاب النار أصحاب الجنة."], ["يوم تُولّون مدبرين", "هاربين من النار إلى الموقف."], ["ولقد جاءكم يوسف من قبل", "يوسف بن يعقوب الصدّيق بن الصدّيق ﵉."], ["قلتم لن يبعث الله من بعده رسولاً", "قلتم هذا من دون دليل فبقيتم كافرين."], ["كذلك يُضل الله من هو مسرف", "مثل إضلالكم هذا يُضل الله من هو مسرف في الشرك."], ["مرتاب", "شاكّ فيما قامت الحجج على صحته."], ["يجادلون في آيات الله بغير سلطان", "يخاصمون في آيات الله لإبطالها بدون حجة."], ["كبُر مقتاً عند الله", "كبُر جدالهم بالباطل مقتاً عند الله وعند الذين آمنوا."], ["كذلك يطبع الله", "مثل إضلالهم يختم الله بالضلال على كل قلب متكبر جبار."]], "m": "ما زال السياق فيما دار من كلام في مجلس الحكم: تناول مؤمن آل فرعون الكلمة بعد أن أعاد فرعون تقرير ما عزم عليه من قتل موسى، وهنا أعلن عن إيمانه الذي كان يكتمه: يا قوم إن أصررتم على قتل موسى أخاف عليكم مثل يوم الأحزاب الذي أخذ الله فيه قوم نوح وعاد وثمود، جزاء عادتهم في الاستمرار على الكفر والتكذيب حتى حلّت بهم نقمة الله. ويا قوم إني أخاف عليكم يوم القيامة الذي تكثر فيه النداءات والصرخات، يوم تولّون فارّين من النار إلى الموقف، ما لكم من الله من عاصم ينجيكم. ثم قال لما رأى أن القوم لم يتأثروا، متعزّياً بعلمه بتدبير الله: ومن يضلل الله فما له من هاد. ولقد جاءكم يوسف بن يعقوب بن إسحاق بن إبراهيم من قبل موسى بالبيّنات الدالة على التوحيد، فما زلتم في شك مما جاءكم به، حتى إذا مات فرحتم بموته وقلتم: لن يبعث الله من بعده رسولاً، متقوّلين على الله بلا علم، كذلك يُضل الله من هو مسرف في الكذب مرتاب لا يعرف اليقين في شيء. ثم أعلمهم أن الذين يجادلون في آيات الله يريدون إبطال الحق بغير حجة، جدالهم أشد شيء يمقته الله ويمقته المؤمنون، وختم كلامه: كذلك يطبع الله على قلب كل متكبر على الإيمان والطاعة، متجبر يريد إجبار الناس على ما يهواه.", "h": ["قوة الإيمان تفجّر قلب المؤمن بأنواع من المعرفة والحكمة.", "التذكير بالأمم الهالكة، إذ العاقل من اعتبر بغيره.", "التخويف من عذاب الآخرة وأهوال القيامة.", "التنديد بالإسراف والارتياب وعدم اليقين.", "حرمة الجدال بغير علم، وأن صاحبه عرضة لمقت المؤمنين بعد مقت الله تعالى.", "عرضة المتكبر الجبار للطبع على قلبه، ويومها يُحرم الهداية فلا يُهدى أبداً."], "k": "«الذين يجادلون في آيات الله بغير سلطان»… هل أجادل لأصل إلى الحق، أم لأنتصر لرأيي؟"}, {"lbl": "الآيات ٣٦ – ٤٠", "q": "وَقَالَ فِرۡعَوۡنُ يَٰهَٰمَٰنُ ٱبۡنِ لِي صَرۡحٗا لَّعَلِّيٓ أَبۡلُغُ ٱلۡأَسۡبَٰبَ ﴿٣٦﴾ أَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبٗاۚ وَكَذَٰلِكَ زُيِّنَ لِفِرۡعَوۡنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِۚ وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ ﴿٣٧﴾ وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ ٱتَّبِعُونِ أَهۡدِكُمۡ سَبِيلَ ٱلرَّشَادِ ﴿٣٨﴾ يَٰقَوۡمِ إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعٞ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ دَارُ ٱلۡقَرَارِ ﴿٣٩﴾ مَنۡ عَمِلَ سَيِّئَةٗ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَاۖ وَمَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِسَابٖ ﴿٤٠﴾", "w": [["يا هامان ابنِ لي صرحاً", "هامان وزير فرعون، والصرح البناء العالي."], ["أسباب السماوات", "طرقها الموصلة إليها."], ["وإني لأظنّه كاذباً", "وإني لأظن موسى كاذباً في زعمه أن له إلهاً غيري."], ["سوء عمله", "قبيح عمله."], ["وصُدّ عن السبيل", "عن طريق الهدى."], ["إلا في تباب", "خسار وضياع بلا فائدة تُذكر."], ["إنما هذه الحياة الدنيا متاع", "ما هذه الدنيا إلا متاع يُتمتّع به وقتاً ثم يزول."], ["دار القرار", "الاستقرار والبقاء الأبدي."], ["يُرزقون فيها بغير حساب", "رزقاً واسعاً بلا تبعة ولا تعقيب."]], "m": "ما زال السياق فيما دار بين مؤمن آل فرعون وفرعون: ردّ فرعون بطريق غير مباشر على ما قاله المؤمن فقال لوزيره: يا هامان ابنِ لي بناءً عالياً لعلي أبلغ طرق السماوات فأطّلع إلى إله موسى، وإني لأظنه كاذباً في دعواه أن له إلهاً غيري؛ وهذا مجرد مناورة كاذبة يريد أن يمرّرها على غيره إبقاءً على مركزه. وكذلك زُيّن لفرعون قبيح عمله، وصُرف عن طريق الحق، وما كيده وتدبيره لقتل موسى وأبناء المؤمنين إلا في خسار وضياع، لأن الله وليّ موسى والمؤمنين. ثم أخبر عن الرجل المؤمن: وقال الذي آمن: يا قوم اتبعوني أهدكم طريق الرشد لتنجوا من العذاب وتفوزوا بالنعيم المقيم. يا قوم إنما هذه الحياة الدنيا متاع قليل يذهب سريعاً، وإن الآخرة هي دار الإقامة الأبدية، فاعملوا لدار البقاء وتجافوا عن دار الفناء، واعلموا أن من عمل سيئة فلا يُجزى إلا مثلها لعدالة الرب، ومن عمل صالحاً مما شرعه الله وهو مؤمن مصدّق بوعده ووعيده، ذكراً كان أو أنثى، فأولئك يدخلون الجنة يُرزقون فيها رزقاً واسعاً لا يلحقهم فيه تبعة ولا تعب.", "h": ["التحذير من تزيين الأعمال القبيحة نتيجة الإدمان عليها والاستمرار على فعلها، فإن من زُيّنت له أعماله السيئة فأصبح يراها حسنة هلك والعياذ بالله.", "التحذير من الاغترار بالدنيا والغفلة عن الآخرة، إذ الأولى زائلة والآخرة باقية، واختيار الباقي على الفاني من شأن العقلاء.", "مشروعية التذكير بالحساب والجزاء وما يتم في الدار الآخرة من سعادة وشقاء."], "k": "«إنما هذه الحياة الدنيا متاع»… كم من وقتي أصرفه لدار القرار؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 344;
insert into public.tdb_cards(topic, i, body) select 344, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٠ – ٣٥", "q": "وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُم مِّثۡلَ يَوۡمِ ٱلۡأَحۡزَابِ ﴿٣٠﴾ مِثۡلَ دَأۡبِ قَوۡمِ نُوحٖ وَعَادٖ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا لِّلۡعِبَادِ ﴿٣١﴾ وَيَٰقَوۡمِ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ يَوۡمَ ٱلتَّنَادِ ﴿٣٢﴾ يَوۡمَ تُوَلُّونَ مُدۡبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنۡ عَاصِمٖۗ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ ﴿٣٣﴾ وَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي شَكّٖ مِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ مُّرۡتَابٌ ﴿٣٤﴾ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡۖ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُواْۚ كَذَٰلِكَ يَطۡبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلۡبِ مُتَكَبِّرٖ جَبَّارٖ ﴿٣٥﴾", "w": [["وقال الذي آمن", "مؤمن آل فرعون."], ["مثل يوم الأحزاب", "عذاباً مثل عذاب الأحزاب، وهم قوم نوح وعاد وثمود."], ["مثل دأب قوم نوح", "مثل جزاء عادة من كفر قبلكم، وهي استمرارهم على الكفر حتى الهلاك."], ["يوم التناد", "يوم القيامة، سُمّي بذلك لكثرة النداءات فيه، إذ ينادي أصحاب الجنة أصحاب النار وأصحاب النار أصحاب الجنة."], ["يوم تُولّون مدبرين", "هاربين من النار إلى الموقف."], ["ولقد جاءكم يوسف من قبل", "يوسف بن يعقوب الصدّيق بن الصدّيق ﵉."], ["قلتم لن يبعث الله من بعده رسولاً", "قلتم هذا من دون دليل فبقيتم كافرين."], ["كذلك يُضل الله من هو مسرف", "مثل إضلالكم هذا يُضل الله من هو مسرف في الشرك."], ["مرتاب", "شاكّ فيما قامت الحجج على صحته."], ["يجادلون في آيات الله بغير سلطان", "يخاصمون في آيات الله لإبطالها بدون حجة."], ["كبُر مقتاً عند الله", "كبُر جدالهم بالباطل مقتاً عند الله وعند الذين آمنوا."], ["كذلك يطبع الله", "مثل إضلالهم يختم الله بالضلال على كل قلب متكبر جبار."]], "m": "ما زال السياق فيما دار من كلام في مجلس الحكم: تناول مؤمن آل فرعون الكلمة بعد أن أعاد فرعون تقرير ما عزم عليه من قتل موسى، وهنا أعلن عن إيمانه الذي كان يكتمه: يا قوم إن أصررتم على قتل موسى أخاف عليكم مثل يوم الأحزاب الذي أخذ الله فيه قوم نوح وعاد وثمود، جزاء عادتهم في الاستمرار على الكفر والتكذيب حتى حلّت بهم نقمة الله. ويا قوم إني أخاف عليكم يوم القيامة الذي تكثر فيه النداءات والصرخات، يوم تولّون فارّين من النار إلى الموقف، ما لكم من الله من عاصم ينجيكم. ثم قال لما رأى أن القوم لم يتأثروا، متعزّياً بعلمه بتدبير الله: ومن يضلل الله فما له من هاد. ولقد جاءكم يوسف بن يعقوب بن إسحاق بن إبراهيم من قبل موسى بالبيّنات الدالة على التوحيد، فما زلتم في شك مما جاءكم به، حتى إذا مات فرحتم بموته وقلتم: لن يبعث الله من بعده رسولاً، متقوّلين على الله بلا علم، كذلك يُضل الله من هو مسرف في الكذب مرتاب لا يعرف اليقين في شيء. ثم أعلمهم أن الذين يجادلون في آيات الله يريدون إبطال الحق بغير حجة، جدالهم أشد شيء يمقته الله ويمقته المؤمنون، وختم كلامه: كذلك يطبع الله على قلب كل متكبر على الإيمان والطاعة، متجبر يريد إجبار الناس على ما يهواه.", "h": ["قوة الإيمان تفجّر قلب المؤمن بأنواع من المعرفة والحكمة.", "التذكير بالأمم الهالكة، إذ العاقل من اعتبر بغيره.", "التخويف من عذاب الآخرة وأهوال القيامة.", "التنديد بالإسراف والارتياب وعدم اليقين.", "حرمة الجدال بغير علم، وأن صاحبه عرضة لمقت المؤمنين بعد مقت الله تعالى.", "عرضة المتكبر الجبار للطبع على قلبه، ويومها يُحرم الهداية فلا يُهدى أبداً."], "k": "«الذين يجادلون في آيات الله بغير سلطان»… هل أجادل لأصل إلى الحق، أم لأنتصر لرأيي؟"}, {"lbl": "الآيات ٣٦ – ٤٠", "q": "وَقَالَ فِرۡعَوۡنُ يَٰهَٰمَٰنُ ٱبۡنِ لِي صَرۡحٗا لَّعَلِّيٓ أَبۡلُغُ ٱلۡأَسۡبَٰبَ ﴿٣٦﴾ أَسۡبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ كَٰذِبٗاۚ وَكَذَٰلِكَ زُيِّنَ لِفِرۡعَوۡنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِۚ وَمَا كَيۡدُ فِرۡعَوۡنَ إِلَّا فِي تَبَابٖ ﴿٣٧﴾ وَقَالَ ٱلَّذِيٓ ءَامَنَ يَٰقَوۡمِ ٱتَّبِعُونِ أَهۡدِكُمۡ سَبِيلَ ٱلرَّشَادِ ﴿٣٨﴾ يَٰقَوۡمِ إِنَّمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا مَتَٰعٞ وَإِنَّ ٱلۡأٓخِرَةَ هِيَ دَارُ ٱلۡقَرَارِ ﴿٣٩﴾ مَنۡ عَمِلَ سَيِّئَةٗ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَاۖ وَمَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِسَابٖ ﴿٤٠﴾", "w": [["يا هامان ابنِ لي صرحاً", "هامان وزير فرعون، والصرح البناء العالي."], ["أسباب السماوات", "طرقها الموصلة إليها."], ["وإني لأظنّه كاذباً", "وإني لأظن موسى كاذباً في زعمه أن له إلهاً غيري."], ["سوء عمله", "قبيح عمله."], ["وصُدّ عن السبيل", "عن طريق الهدى."], ["إلا في تباب", "خسار وضياع بلا فائدة تُذكر."], ["إنما هذه الحياة الدنيا متاع", "ما هذه الدنيا إلا متاع يُتمتّع به وقتاً ثم يزول."], ["دار القرار", "الاستقرار والبقاء الأبدي."], ["يُرزقون فيها بغير حساب", "رزقاً واسعاً بلا تبعة ولا تعقيب."]], "m": "ما زال السياق فيما دار بين مؤمن آل فرعون وفرعون: ردّ فرعون بطريق غير مباشر على ما قاله المؤمن فقال لوزيره: يا هامان ابنِ لي بناءً عالياً لعلي أبلغ طرق السماوات فأطّلع إلى إله موسى، وإني لأظنه كاذباً في دعواه أن له إلهاً غيري؛ وهذا مجرد مناورة كاذبة يريد أن يمرّرها على غيره إبقاءً على مركزه. وكذلك زُيّن لفرعون قبيح عمله، وصُرف عن طريق الحق، وما كيده وتدبيره لقتل موسى وأبناء المؤمنين إلا في خسار وضياع، لأن الله وليّ موسى والمؤمنين. ثم أخبر عن الرجل المؤمن: وقال الذي آمن: يا قوم اتبعوني أهدكم طريق الرشد لتنجوا من العذاب وتفوزوا بالنعيم المقيم. يا قوم إنما هذه الحياة الدنيا متاع قليل يذهب سريعاً، وإن الآخرة هي دار الإقامة الأبدية، فاعملوا لدار البقاء وتجافوا عن دار الفناء، واعلموا أن من عمل سيئة فلا يُجزى إلا مثلها لعدالة الرب، ومن عمل صالحاً مما شرعه الله وهو مؤمن مصدّق بوعده ووعيده، ذكراً كان أو أنثى، فأولئك يدخلون الجنة يُرزقون فيها رزقاً واسعاً لا يلحقهم فيه تبعة ولا تعب.", "h": ["التحذير من تزيين الأعمال القبيحة نتيجة الإدمان عليها والاستمرار على فعلها، فإن من زُيّنت له أعماله السيئة فأصبح يراها حسنة هلك والعياذ بالله.", "التحذير من الاغترار بالدنيا والغفلة عن الآخرة، إذ الأولى زائلة والآخرة باقية، واختيار الباقي على الفاني من شأن العقلاء.", "مشروعية التذكير بالحساب والجزاء وما يتم في الدار الآخرة من سعادة وشقاء."], "k": "«إنما هذه الحياة الدنيا متاع»… كم من وقتي أصرفه لدار القرار؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (345, 40, 41, 52, 'سورة غافر ٤١ – ٥٢', 'غافر: وأفوّض أمري إلى الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 345) = $j$[{"lbl": "الآيات ٤١ – ٤٦", "q": "۞وَيَٰقَوۡمِ مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ ﴿٤١﴾ تَدۡعُونَنِي لِأَكۡفُرَ بِٱللَّهِ وَأُشۡرِكَ بِهِۦ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞ وَأَنَا۠ أَدۡعُوكُمۡ إِلَى ٱلۡعَزِيزِ ٱلۡغَفَّـٰرِ ﴿٤٢﴾ لَا جَرَمَ أَنَّمَا تَدۡعُونَنِيٓ إِلَيۡهِ لَيۡسَ لَهُۥ دَعۡوَةٞ فِي ٱلدُّنۡيَا وَلَا فِي ٱلۡأٓخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلۡمُسۡرِفِينَ هُمۡ أَصۡحَٰبُ ٱلنَّارِ ﴿٤٣﴾ فَسَتَذۡكُرُونَ مَآ أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ ﴿٤٤﴾ فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ ﴿٤٥﴾ ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ ﴿٤٦﴾", "w": [["أدعوكم إلى النجاة", "من الخسران في الدنيا والآخرة، وذلك بالإيمان والعمل الصالح."], ["وتدعونني إلى النار", "إلى عذاب النار، وذلك بالكفر والشرك بالله تعالى."], ["ما ليس لي به علم", "لا علم لي بصحة إشراكه في عبادة الله تعالى."], ["وأنا أدعوكم إلى العزيز الغفّار", "إلى الإيمان وعبادة الله الغالب على أمره، الغفّار لذنوب التائبين من عباده."], ["لا جرم أنما تدعونني إليه", "حقاً أن ما تدعونني إلى الإيمان به وعبادته."], ["ليس له دعوة في الدنيا ولا في الآخرة", "ليس له دعوة حق إلى عبادته، ولا دعوة استجابة بأن يستجيب لمن دعاه، لا في الدنيا ولا في الآخرة."], ["وأن المسرفين هم أصحاب النار", "المسرفين في الكفر والشرك والمعاصي هم أهل النار."], ["فوقاه الله سيئات ما مكروا", "حفظه الله من مكرهم به ليقتلوه."], ["وحاق بآل فرعون سوء العذاب", "عذاب الغرق، إذ غرق فرعون وجنده أجمعون."], ["النار يُعرضون عليها غدواً وعشياً", "يُعرضون عليها صباحاً ومساءً، وذلك أن أرواحهم في أجواف طير سود تُعرض على النار."], ["أدخلوا آل فرعون أشد العذاب", "ويوم القيامة يقال: أدخلوا آل فرعون أشد العذاب."]], "m": "ما زال السياق في نصائح مؤمن آل فرعون: ويا قوم ما لي أدعوكم إلى النجاة من النار بالإيمان والعمل الصالح وترك الشرك، وتدعونني إلى النار بدعوتكم لي إلى الكفر بالله وأن أشرك به ما لا علم لي بصحة إشراكه في عبادته، وأنا أدعوكم إلى العزيز الغالب الذي لا يُغلب، الغفّار لذنوب التائبين مهما كانت، وأنتم تدعونني إلى أذلّ شيء وأحقره. حقاً أن ما تدعونني إليه ليس له دعوة حق ولا يستجيب دعاءً أبداً لا في الدنيا ولا في الآخرة، وأن مردّنا إلى الله لا محالة، فالواجب أن نؤمن به ونعبده ونوحّده، وأن المسرفين الذين تجاوزوا الحد في الكفر والمعاصي هم أصحاب النار الذين لا يفارقونها. ويبدو أنه قال لما رفضوا دعوته وهمّوا بقتله: فستذكرون ما أقول لكم، وأفوّض أمري إلى الله، إن الله بصير بالعباد. فوقاه الله سيئات ما مكروا ليقتلوه، فهرب منهم فبعث فرعون رجالاً في طلبه فلم يقدروا عليه، ونجا مع موسى وبني إسرائيل، وحاق بآل فرعون سوء العذاب بأن أغرقهم الله في البحر أجمعين. وأرواح آل فرعون تُعرض في البرزخ على النار غدواً وعشياً، وذلك بأن تكون في أجواف طير سود، على خلاف أرواح المؤمنين فإنها تكون في أجواف طير خضر ترعى في الجنة، إلى يوم القيامة، ويوم تقوم الساعة يقال: أدخلوا آل فرعون أشد العذاب، وهو عذاب جهنم.", "h": ["بيان الفرق الكبير بين من يدعو إلى النجاة وبين من يدعو إلى النار، بين من يدعو إلى العزيز الغفّار ليؤمَن به ويُعبد، وبين من يدعو إلى أوثان لا تسمع ولا تبصر وهي أحقر شيء وأذله، وبين من يدعو من لا يستجيب له في الدنيا والآخرة وبين من يدعو من يستجيب له في الدنيا والآخرة.", "التنديد بالإسراف في كل شيء.", "نِعم ما ختم به مؤمن آل فرعون وعظه ونصحه لقومه: «فستذكرون ما أقول لكم وأفوّض أمري إلى الله إن الله بصير بالعباد».", "إثبات عذاب القبر ونعيمه، إذ آل فرعون تُعرض أرواحهم على النار صباح مساء."], "k": "«وأفوّض أمري إلى الله»… بعد أن أؤدّي ما عليّ، هل أترك النتائج له وأستريح؟"}, {"lbl": "الآيات ٤٧ – ٥٢", "q": "وَإِذۡ يَتَحَآجُّونَ فِي ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَـٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِيبٗا مِّنَ ٱلنَّارِ ﴿٤٧﴾ قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُلّٞ فِيهَآ إِنَّ ٱللَّهَ قَدۡ حَكَمَ بَيۡنَ ٱلۡعِبَادِ ﴿٤٨﴾ وَقَالَ ٱلَّذِينَ فِي ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدۡعُواْ رَبَّكُمۡ يُخَفِّفۡ عَنَّا يَوۡمٗا مِّنَ ٱلۡعَذَابِ ﴿٤٩﴾ قَالُوٓاْ أَوَلَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُكُم بِٱلۡبَيِّنَٰتِۖ قَالُواْ بَلَىٰۚ قَالُواْ فَٱدۡعُواْۗ وَمَا دُعَـٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ ﴿٥٠﴾ إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيَوۡمَ يَقُومُ ٱلۡأَشۡهَٰدُ ﴿٥١﴾ يَوۡمَ لَا يَنفَعُ ٱلظَّـٰلِمِينَ مَعۡذِرَتُهُمۡۖ وَلَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ ﴿٥٢﴾", "w": [["وإذ يتحاجّون في النار", "وأنذرهم واذكر لهم إذ يتخاصمون في النار."], ["فيقول الضعفاء", "الأتباع الذين اتبعوا الأغنياء والأقوياء."], ["إنا كنا لكم تبعاً", "تابعين لكم فيما كنتم تعتقدونه وتفعلونه."], ["فهل أنتم مغنون عنا نصيباً من النار", "فهل تدفعون عنا شيئاً من النار؟"], ["إن الله قد حكم بين العباد", "فلا مراجعة أبداً، فقد حكم لأهل الإيمان والتقوى بالجنة ولأهل الشرك والمعاصي بالنار."], ["لخزنة جهنم", "جمع خازن، وهو الموكّل بالنار وأهلها."], ["يخفّف عنا يوماً من العذاب", "قدر يوم من أيام الدنيا، إذ الآخرة يوم واحد لا ليل له."], ["إنا لننصر رسلنا والذين آمنوا في الحياة الدنيا", "بأن نُظهر دينهم، أو نهلك قومهم وننجيهم من الهلاك."], ["ويوم يقوم الأشهاد", "وننصرهم يوم يقوم الأشهاد، وهم الملائكة يشهدون للرسل."], ["ولهم اللعنة ولهم سوء الدار", "البعد من الرحمة، وسوء الدار الآخرة أي شدة عذابها."]], "m": "هذا عرض آخر للنار يُعرض على كفار قريش ليشاهدوا مصيرهم إن لم يتوبوا: واذكر لهم إذ يتخاصمون في النار، فيقول الضعفاء الأتباع الذين كانوا يتبعون أغنياء البلاد وأقوياءها طمعاً فيهم وخوفاً منهم، للذين استكبروا عن الإيمان ومتابعة الرسل: إنا كنا لكم تابعين، فهل تخفّفون عنا حظاً من عذاب النار؟ فقال المستكبرون: إنا كلٌّ فيها، إن الله قد حكم بين العباد فقضى بالجنة لأهل الإيمان والتقوى وبالنار لأهل الشرك والمعاصي. ولم تنته الخصومة إلا إلى زيادة الحسرة والغم. وقال الذين في النار لخزنة جهنم: ادعوا ربكم يخفّف عنا مقدار يوم من العذاب. فقالت الملائكة: أوَلم تك تأتيكم رسلكم بالحجج الظاهرة؟ قالوا: بلى، قالوا: فادعوا أنتم، ولا يُستجاب لكم، وما دعاء الكافرين إلا في ضلال. ثم قرّر حقيقة عظمى: إن من سنة الله في رسله أنه ينصرهم بانتصار دينهم وإن طال الزمن واشتدت المحن، أو بإهلاك أممهم المكذّبة وإنجائهم والمؤمنين معهم، وينصرهم في الآخرة يوم يقوم الأشهاد، وهم الملائكة يشهدون للرسل بالبلاغ وعلى الكافرين بالتكذيب، يوم لا ينفع الظالمين معذرتهم إن أُذن لهم في الاعتذار، ولهم البعد من الرحمة، ولهم سوء الدار الآخرة وهو أشد عذابها.", "h": ["بيان تخاصم أهل النار، وهو ما يتم من خصومة بين الأتباع والمتبوعين.", "التنديد بالكبر والاستكبار، إذ الكبر عائق عن الطاعة والاستقامة.", "عدم استجابة دعاء الكافر في الدنيا والآخرة إلا ما شاء الله.", "عدم قبول المعذرة يوم القيامة.", "عدم استجابة الدعاء في النار.", "بيان وعد الله لرسله والمؤمنين، وهو أنه ينصرهم بأحد أمرين: الأول أن ينصر دينهم ويظهره ويقرّره وإن طال الزمن، والثاني أن يهلك عدوهم وينجيهم."], "k": "«إنا كنا لكم تبعاً»… من أتبع اليوم بلا تفكير؟ وهل سيغني عني شيئاً يومها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 345;
insert into public.tdb_cards(topic, i, body) select 345, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٦", "q": "۞وَيَٰقَوۡمِ مَا لِيٓ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِيٓ إِلَى ٱلنَّارِ ﴿٤١﴾ تَدۡعُونَنِي لِأَكۡفُرَ بِٱللَّهِ وَأُشۡرِكَ بِهِۦ مَا لَيۡسَ لِي بِهِۦ عِلۡمٞ وَأَنَا۠ أَدۡعُوكُمۡ إِلَى ٱلۡعَزِيزِ ٱلۡغَفَّـٰرِ ﴿٤٢﴾ لَا جَرَمَ أَنَّمَا تَدۡعُونَنِيٓ إِلَيۡهِ لَيۡسَ لَهُۥ دَعۡوَةٞ فِي ٱلدُّنۡيَا وَلَا فِي ٱلۡأٓخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلۡمُسۡرِفِينَ هُمۡ أَصۡحَٰبُ ٱلنَّارِ ﴿٤٣﴾ فَسَتَذۡكُرُونَ مَآ أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ ﴿٤٤﴾ فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُواْۖ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوٓءُ ٱلۡعَذَابِ ﴿٤٥﴾ ٱلنَّارُ يُعۡرَضُونَ عَلَيۡهَا غُدُوّٗا وَعَشِيّٗاۚ وَيَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوٓاْ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ ﴿٤٦﴾", "w": [["أدعوكم إلى النجاة", "من الخسران في الدنيا والآخرة، وذلك بالإيمان والعمل الصالح."], ["وتدعونني إلى النار", "إلى عذاب النار، وذلك بالكفر والشرك بالله تعالى."], ["ما ليس لي به علم", "لا علم لي بصحة إشراكه في عبادة الله تعالى."], ["وأنا أدعوكم إلى العزيز الغفّار", "إلى الإيمان وعبادة الله الغالب على أمره، الغفّار لذنوب التائبين من عباده."], ["لا جرم أنما تدعونني إليه", "حقاً أن ما تدعونني إلى الإيمان به وعبادته."], ["ليس له دعوة في الدنيا ولا في الآخرة", "ليس له دعوة حق إلى عبادته، ولا دعوة استجابة بأن يستجيب لمن دعاه، لا في الدنيا ولا في الآخرة."], ["وأن المسرفين هم أصحاب النار", "المسرفين في الكفر والشرك والمعاصي هم أهل النار."], ["فوقاه الله سيئات ما مكروا", "حفظه الله من مكرهم به ليقتلوه."], ["وحاق بآل فرعون سوء العذاب", "عذاب الغرق، إذ غرق فرعون وجنده أجمعون."], ["النار يُعرضون عليها غدواً وعشياً", "يُعرضون عليها صباحاً ومساءً، وذلك أن أرواحهم في أجواف طير سود تُعرض على النار."], ["أدخلوا آل فرعون أشد العذاب", "ويوم القيامة يقال: أدخلوا آل فرعون أشد العذاب."]], "m": "ما زال السياق في نصائح مؤمن آل فرعون: ويا قوم ما لي أدعوكم إلى النجاة من النار بالإيمان والعمل الصالح وترك الشرك، وتدعونني إلى النار بدعوتكم لي إلى الكفر بالله وأن أشرك به ما لا علم لي بصحة إشراكه في عبادته، وأنا أدعوكم إلى العزيز الغالب الذي لا يُغلب، الغفّار لذنوب التائبين مهما كانت، وأنتم تدعونني إلى أذلّ شيء وأحقره. حقاً أن ما تدعونني إليه ليس له دعوة حق ولا يستجيب دعاءً أبداً لا في الدنيا ولا في الآخرة، وأن مردّنا إلى الله لا محالة، فالواجب أن نؤمن به ونعبده ونوحّده، وأن المسرفين الذين تجاوزوا الحد في الكفر والمعاصي هم أصحاب النار الذين لا يفارقونها. ويبدو أنه قال لما رفضوا دعوته وهمّوا بقتله: فستذكرون ما أقول لكم، وأفوّض أمري إلى الله، إن الله بصير بالعباد. فوقاه الله سيئات ما مكروا ليقتلوه، فهرب منهم فبعث فرعون رجالاً في طلبه فلم يقدروا عليه، ونجا مع موسى وبني إسرائيل، وحاق بآل فرعون سوء العذاب بأن أغرقهم الله في البحر أجمعين. وأرواح آل فرعون تُعرض في البرزخ على النار غدواً وعشياً، وذلك بأن تكون في أجواف طير سود، على خلاف أرواح المؤمنين فإنها تكون في أجواف طير خضر ترعى في الجنة، إلى يوم القيامة، ويوم تقوم الساعة يقال: أدخلوا آل فرعون أشد العذاب، وهو عذاب جهنم.", "h": ["بيان الفرق الكبير بين من يدعو إلى النجاة وبين من يدعو إلى النار، بين من يدعو إلى العزيز الغفّار ليؤمَن به ويُعبد، وبين من يدعو إلى أوثان لا تسمع ولا تبصر وهي أحقر شيء وأذله، وبين من يدعو من لا يستجيب له في الدنيا والآخرة وبين من يدعو من يستجيب له في الدنيا والآخرة.", "التنديد بالإسراف في كل شيء.", "نِعم ما ختم به مؤمن آل فرعون وعظه ونصحه لقومه: «فستذكرون ما أقول لكم وأفوّض أمري إلى الله إن الله بصير بالعباد».", "إثبات عذاب القبر ونعيمه، إذ آل فرعون تُعرض أرواحهم على النار صباح مساء."], "k": "«وأفوّض أمري إلى الله»… بعد أن أؤدّي ما عليّ، هل أترك النتائج له وأستريح؟"}, {"lbl": "الآيات ٤٧ – ٥٢", "q": "وَإِذۡ يَتَحَآجُّونَ فِي ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَـٰٓؤُاْ لِلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُنَّا لَكُمۡ تَبَعٗا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِيبٗا مِّنَ ٱلنَّارِ ﴿٤٧﴾ قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا كُلّٞ فِيهَآ إِنَّ ٱللَّهَ قَدۡ حَكَمَ بَيۡنَ ٱلۡعِبَادِ ﴿٤٨﴾ وَقَالَ ٱلَّذِينَ فِي ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدۡعُواْ رَبَّكُمۡ يُخَفِّفۡ عَنَّا يَوۡمٗا مِّنَ ٱلۡعَذَابِ ﴿٤٩﴾ قَالُوٓاْ أَوَلَمۡ تَكُ تَأۡتِيكُمۡ رُسُلُكُم بِٱلۡبَيِّنَٰتِۖ قَالُواْ بَلَىٰۚ قَالُواْ فَٱدۡعُواْۗ وَمَا دُعَـٰٓؤُاْ ٱلۡكَٰفِرِينَ إِلَّا فِي ضَلَٰلٍ ﴿٥٠﴾ إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيَوۡمَ يَقُومُ ٱلۡأَشۡهَٰدُ ﴿٥١﴾ يَوۡمَ لَا يَنفَعُ ٱلظَّـٰلِمِينَ مَعۡذِرَتُهُمۡۖ وَلَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوٓءُ ٱلدَّارِ ﴿٥٢﴾", "w": [["وإذ يتحاجّون في النار", "وأنذرهم واذكر لهم إذ يتخاصمون في النار."], ["فيقول الضعفاء", "الأتباع الذين اتبعوا الأغنياء والأقوياء."], ["إنا كنا لكم تبعاً", "تابعين لكم فيما كنتم تعتقدونه وتفعلونه."], ["فهل أنتم مغنون عنا نصيباً من النار", "فهل تدفعون عنا شيئاً من النار؟"], ["إن الله قد حكم بين العباد", "فلا مراجعة أبداً، فقد حكم لأهل الإيمان والتقوى بالجنة ولأهل الشرك والمعاصي بالنار."], ["لخزنة جهنم", "جمع خازن، وهو الموكّل بالنار وأهلها."], ["يخفّف عنا يوماً من العذاب", "قدر يوم من أيام الدنيا، إذ الآخرة يوم واحد لا ليل له."], ["إنا لننصر رسلنا والذين آمنوا في الحياة الدنيا", "بأن نُظهر دينهم، أو نهلك قومهم وننجيهم من الهلاك."], ["ويوم يقوم الأشهاد", "وننصرهم يوم يقوم الأشهاد، وهم الملائكة يشهدون للرسل."], ["ولهم اللعنة ولهم سوء الدار", "البعد من الرحمة، وسوء الدار الآخرة أي شدة عذابها."]], "m": "هذا عرض آخر للنار يُعرض على كفار قريش ليشاهدوا مصيرهم إن لم يتوبوا: واذكر لهم إذ يتخاصمون في النار، فيقول الضعفاء الأتباع الذين كانوا يتبعون أغنياء البلاد وأقوياءها طمعاً فيهم وخوفاً منهم، للذين استكبروا عن الإيمان ومتابعة الرسل: إنا كنا لكم تابعين، فهل تخفّفون عنا حظاً من عذاب النار؟ فقال المستكبرون: إنا كلٌّ فيها، إن الله قد حكم بين العباد فقضى بالجنة لأهل الإيمان والتقوى وبالنار لأهل الشرك والمعاصي. ولم تنته الخصومة إلا إلى زيادة الحسرة والغم. وقال الذين في النار لخزنة جهنم: ادعوا ربكم يخفّف عنا مقدار يوم من العذاب. فقالت الملائكة: أوَلم تك تأتيكم رسلكم بالحجج الظاهرة؟ قالوا: بلى، قالوا: فادعوا أنتم، ولا يُستجاب لكم، وما دعاء الكافرين إلا في ضلال. ثم قرّر حقيقة عظمى: إن من سنة الله في رسله أنه ينصرهم بانتصار دينهم وإن طال الزمن واشتدت المحن، أو بإهلاك أممهم المكذّبة وإنجائهم والمؤمنين معهم، وينصرهم في الآخرة يوم يقوم الأشهاد، وهم الملائكة يشهدون للرسل بالبلاغ وعلى الكافرين بالتكذيب، يوم لا ينفع الظالمين معذرتهم إن أُذن لهم في الاعتذار، ولهم البعد من الرحمة، ولهم سوء الدار الآخرة وهو أشد عذابها.", "h": ["بيان تخاصم أهل النار، وهو ما يتم من خصومة بين الأتباع والمتبوعين.", "التنديد بالكبر والاستكبار، إذ الكبر عائق عن الطاعة والاستقامة.", "عدم استجابة دعاء الكافر في الدنيا والآخرة إلا ما شاء الله.", "عدم قبول المعذرة يوم القيامة.", "عدم استجابة الدعاء في النار.", "بيان وعد الله لرسله والمؤمنين، وهو أنه ينصرهم بأحد أمرين: الأول أن ينصر دينهم ويظهره ويقرّره وإن طال الزمن، والثاني أن يهلك عدوهم وينجيهم."], "k": "«إنا كنا لكم تبعاً»… من أتبع اليوم بلا تفكير؟ وهل سيغني عني شيئاً يومها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (346, 40, 53, 63, 'سورة غافر ٥٣ – ٦٣', 'غافر: ادعوني أستجب لكم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 346) = $j$[{"lbl": "الآيات ٥٣ – ٥٧", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡكِتَٰبَ ﴿٥٣﴾ هُدٗى وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ ﴿٥٤﴾ فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ ﴿٥٥﴾ إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ مَّا هُم بِبَٰلِغِيهِۚ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴿٥٦﴾ لَخَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَكۡبَرُ مِنۡ خَلۡقِ ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٥٧﴾", "w": [["ولقد آتينا موسى الهدى", "أعطينا موسى المعجزات والتوراة."], ["وأورثنا بني إسرائيل الكتاب", "أبقينا فيهم التوراة كتاب الهداية الإلهية يهتدون به في ظلمات الحياة، ويذكرون به الله في تراكم النسيان."], ["فاصبر إن وعد الله حق", "اصبر يا محمد على ما تلاقي من قومك، إن وعد الله بنصرك حق."], ["واستغفر لذنبك", "ليُقتدى بك في ذلك، ولزيادة طهارة روحك وتزكية نفسك."], ["وسبّح بحمد ربك", "نزّه ربك وقدّسه بالصلاة والذكر والتسبيح فيها وخارجها."], ["بالعشيّ والإبكار", "بالمساء وأول النهار، أي في أوقات الصلوات الخمس كلها."], ["إن في صدورهم إلا كِبر", "ما في صدورهم إلا كبر حملهم على الجدال في الحق، لا أن لهم علماً يجادلون به."], ["فاستعذ بالله", "استعذ من شرهم بالله السميع لأقوالهم العليم بأعمالهم ونياتهم."], ["لخلق السماوات والأرض", "لخلقهما ابتداءً ولأول مرة."], ["أكبر من خلق الناس", "أعظم من خلق الناس مرة أخرى بعد الأولى."]], "m": "هذا شروع في تسلية الرسول ﷺ عما يلاقي من قومه: فقد سبق أن أرسل موسى وآتاه التوراة وأورثها في بني إسرائيل هدى لهم في ظلمات الحياة إلى الدين الصحيح الذي هو الإسلام، وذكرى يتذكّر بها أولو العقول، ولاقى موسى من قومه أشد مما لاقيت، فاصبر على ما تعانيه من قريش فإن العاقبة لك، فإن وعد الله حق، وقد قال: إنا لننصر رسلنا. ثم أرشده إلى مقوّمات الصبر: ذكر الله بالاستغفار والدعاء والصلاة والتسبيح فيها وخارجها، فأعظم عون على الصبر الصلاة، ولذا كان ﷺ إذا حزبه أمر فزع إلى الصلاة. إن الذين يجادلون في آيات الله بغير حجة من علم إلهي أتاهم بالوحي، ما في صدورهم إلا كبر لا يصلون إليه بحال، وهو الرئاسة عليك والتحكم فيك وفي أصحابك، فاستعذ بالله من شرهم ومكرهم، إنه هو السميع البصير، فلن يمكّن لهم منك أبداً. ثم ردّ على منكري البعث القائلين: أإذا متنا وكنا تراباً وعظاماً أإنا لمبعوثون؟ فقال: لخلق السماوات والأرض ابتداءً من غير مثال سابق ولا مادة موجودة أكبر من خلق الناس مرة أخرى، ولكن أكثر الناس لا يعلمون هذه الحقائق لجهلهم، وإلا فإعادة الشيء أهون من بدئه عقلاً.", "h": ["بيان منّة الله تعالى على موسى وبني إسرائيل، تتكرّر لمحمد ﷺ وأمته بإنزال الكتاب وتوريثه فيهم هدى وذكرى لأولي الألباب.", "وجوب الصبر والتحمل في ذات الله، والاستعانة على ذلك بالاستغفار والذكر والصلاة.", "أكثر من يجادل بالباطل ليزيل به الحق إنما يجادل من كبر، يريد الوصول إلى التعالي والغلبة والقهر للآخرين.", "تقرير عقيدة البعث بالبرهان العقلي، وهو أن البدء أصعب من الإعادة، ومن بدأ أعاد."], "k": "«فاصبر… واستغفر لذنبك وسبّح بحمد ربك»… الصبر له وقود؛ فهل أتزوّد منه بالذكر والصلاة؟"}, {"lbl": "الآيات ٥٨ – ٦٣", "q": "وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَلَا ٱلۡمُسِيٓءُۚ قَلِيلٗا مَّا تَتَذَكَّرُونَ ﴿٥٨﴾ إِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞ لَّا رَيۡبَ فِيهَا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ ﴿٥٩﴾ وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ﴿٦٠﴾ ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ﴿٦١﴾ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ خَٰلِقُ كُلِّ شَيۡءٖ لَّآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ ﴿٦٢﴾ كَذَٰلِكَ يُؤۡفَكُ ٱلَّذِينَ كَانُواْ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ ﴿٦٣﴾", "w": [["وما يستوي الأعمى والبصير", "لا يستويان، فكذلك الكافر والمؤمن لا يستويان."], ["والذين آمنوا وعملوا الصالحات ولا المسيء", "لا يستويان أيضاً، فكذلك لا يستوي الموقن والشاك."], ["إن الساعة لآتية", "ساعة نهاية هذه الحياة وإقبال الأخرى جائية لا شك."], ["إن الذين يستكبرون عن عبادتي", "عن دعائي."], ["سيدخلون جهنم داخرين", "صاغرين ذليلين."], ["لتسكنوا فيه", "لتنقطعوا عن الحركة فتستريحوا."], ["والنهار مبصراً", "مضيئاً لتتمكنوا فيه من الحركة والعمل."], ["ذلكم الله ربكم", "الذي أمركم بدعائه ووعدكم بالاستجابة، وجعل لكم الليل والنهار، لا إله لكم غيره ولا رب لكم سواه."], ["فأنّى تُؤفكون", "كيف تُصرفون عنه وهو ربكم إلى أوثان لا تسمع ولا تبصر؟"], ["كذلك يُؤفك الذين كانوا بآيات الله يجحدون", "كما صُرف أولئك عن الإيمان يُصرف الجاحدون بآيات الله عن الحق."]], "m": "ما زال السياق في دعوة قريش إلى الإيمان: ما يستوي في حكم العقلاء الأعمى الذي لا يبصر شيئاً والبصير، فكذلك لا يستوي المؤمن السميع البصير والكافر الأعمى عن الدلائل الأصم عن نداء الحق، ولا المحسن العامل للصالحات والمسيء العامل للسيئات، فلِمَ لا يتعظ القوم؟ إنهم لظلمة نفوسهم قليلاً ما يتذكرون. إن الساعة التي كذّبوا بها ليستمروا على الباطل لآتية حتماً، ولكن أكثر الناس لا يؤمنون بها لانكبابهم على شهواتهم. ولما قرّر ربوبيته قال: وقال ربكم ادعوني أستجب لكم، سلوني أعطكم وأطيعوني أثبكم، فأنتم عبادي وأنا ربكم، إن الذين يستكبرون عن عبادتي ودعائي سيدخلون جهنم صاغرين ذليلين. ثم عرّفهم بنفسه ليؤمنوا به ويعبدوه: الله الذي جعل لكم الليل مظلماً لتنقطعوا فيه عن العمل فتستريحوا، والنهار مضيئاً للعمل وقضاء حاجاتكم، وإفضاله أكثر من أن يُذكر، إن الله لذو فضل على الناس ولكن أكثرهم لا يشكرون، فلا يحمدونه بألسنتهم ولا يطيعونه بجوارحهم لاستيلاء الشيطان والغفلة عليهم. ذلكم الله ربكم خالق كل شيء لا معبود بحق إلا هو، فكيف تُصرفون عنه إلى أوثان لا تنفع ولا تضر؟ كذلك يُصرف الجاحدون بآيات الله في كل زمان ومكان، لأن الآيات حجج، فالمكذّب بها سيكذّب بكل شيء حتى بنفسه.", "h": ["بيان حقيقة، وهي أن الضدّين لا يجتمعان: فالكفر والإيمان، والإحسان والإساءة، والعمى والبصر، والصمم والسمع، كلها لا يستوي بعضها ببعض، فمحاولة الجمع بينها محاولة باطلة.", "قرب الساعة مع تحتّم مجيئها، والأدلة على ذلك العقلية والنقلية كثيرة جداً.", "فضل الدعاء، وقد ورد أن النبي ﷺ قال: «ليسأل أحدكم ربه حاجته كلها حتى شسع نعله». وللدعاء المستجاب شروط، منها: أن يكون القلب متعلقاً بالله معرضاً عما سواه، وألا يسأل ما فيه إثم، ولا يعتدي في الدعاء فيسأل ما لم تجرِ سنة الله به، كأن يسأل أن يرى الجنة يقظة، أو أن يعود شاباً وهو شيخ كبير، أو أن يُرزق الولد وهو لا يتزوج.", "الدعاء هو العبادة، ولذا من دعا غير الله فقد أشرك بالله.", "بيان إنعام الله وإفضاله، والمطالبة بشكر الله تعالى بحمده والثناء عليه وبطاعته."], "k": "«ادعوني أستجب لكم»… ما الحاجة التي أحملها ولم أرفعها إليه بعد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 346;
insert into public.tdb_cards(topic, i, body) select 346, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٣ – ٥٧", "q": "وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِيٓ إِسۡرَـٰٓءِيلَ ٱلۡكِتَٰبَ ﴿٥٣﴾ هُدٗى وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ ﴿٥٤﴾ فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ ﴿٥٥﴾ إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ بِغَيۡرِ سُلۡطَٰنٍ أَتَىٰهُمۡ إِن فِي صُدُورِهِمۡ إِلَّا كِبۡرٞ مَّا هُم بِبَٰلِغِيهِۚ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴿٥٦﴾ لَخَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَكۡبَرُ مِنۡ خَلۡقِ ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٥٧﴾", "w": [["ولقد آتينا موسى الهدى", "أعطينا موسى المعجزات والتوراة."], ["وأورثنا بني إسرائيل الكتاب", "أبقينا فيهم التوراة كتاب الهداية الإلهية يهتدون به في ظلمات الحياة، ويذكرون به الله في تراكم النسيان."], ["فاصبر إن وعد الله حق", "اصبر يا محمد على ما تلاقي من قومك، إن وعد الله بنصرك حق."], ["واستغفر لذنبك", "ليُقتدى بك في ذلك، ولزيادة طهارة روحك وتزكية نفسك."], ["وسبّح بحمد ربك", "نزّه ربك وقدّسه بالصلاة والذكر والتسبيح فيها وخارجها."], ["بالعشيّ والإبكار", "بالمساء وأول النهار، أي في أوقات الصلوات الخمس كلها."], ["إن في صدورهم إلا كِبر", "ما في صدورهم إلا كبر حملهم على الجدال في الحق، لا أن لهم علماً يجادلون به."], ["فاستعذ بالله", "استعذ من شرهم بالله السميع لأقوالهم العليم بأعمالهم ونياتهم."], ["لخلق السماوات والأرض", "لخلقهما ابتداءً ولأول مرة."], ["أكبر من خلق الناس", "أعظم من خلق الناس مرة أخرى بعد الأولى."]], "m": "هذا شروع في تسلية الرسول ﷺ عما يلاقي من قومه: فقد سبق أن أرسل موسى وآتاه التوراة وأورثها في بني إسرائيل هدى لهم في ظلمات الحياة إلى الدين الصحيح الذي هو الإسلام، وذكرى يتذكّر بها أولو العقول، ولاقى موسى من قومه أشد مما لاقيت، فاصبر على ما تعانيه من قريش فإن العاقبة لك، فإن وعد الله حق، وقد قال: إنا لننصر رسلنا. ثم أرشده إلى مقوّمات الصبر: ذكر الله بالاستغفار والدعاء والصلاة والتسبيح فيها وخارجها، فأعظم عون على الصبر الصلاة، ولذا كان ﷺ إذا حزبه أمر فزع إلى الصلاة. إن الذين يجادلون في آيات الله بغير حجة من علم إلهي أتاهم بالوحي، ما في صدورهم إلا كبر لا يصلون إليه بحال، وهو الرئاسة عليك والتحكم فيك وفي أصحابك، فاستعذ بالله من شرهم ومكرهم، إنه هو السميع البصير، فلن يمكّن لهم منك أبداً. ثم ردّ على منكري البعث القائلين: أإذا متنا وكنا تراباً وعظاماً أإنا لمبعوثون؟ فقال: لخلق السماوات والأرض ابتداءً من غير مثال سابق ولا مادة موجودة أكبر من خلق الناس مرة أخرى، ولكن أكثر الناس لا يعلمون هذه الحقائق لجهلهم، وإلا فإعادة الشيء أهون من بدئه عقلاً.", "h": ["بيان منّة الله تعالى على موسى وبني إسرائيل، تتكرّر لمحمد ﷺ وأمته بإنزال الكتاب وتوريثه فيهم هدى وذكرى لأولي الألباب.", "وجوب الصبر والتحمل في ذات الله، والاستعانة على ذلك بالاستغفار والذكر والصلاة.", "أكثر من يجادل بالباطل ليزيل به الحق إنما يجادل من كبر، يريد الوصول إلى التعالي والغلبة والقهر للآخرين.", "تقرير عقيدة البعث بالبرهان العقلي، وهو أن البدء أصعب من الإعادة، ومن بدأ أعاد."], "k": "«فاصبر… واستغفر لذنبك وسبّح بحمد ربك»… الصبر له وقود؛ فهل أتزوّد منه بالذكر والصلاة؟"}, {"lbl": "الآيات ٥٨ – ٦٣", "q": "وَمَا يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَلَا ٱلۡمُسِيٓءُۚ قَلِيلٗا مَّا تَتَذَكَّرُونَ ﴿٥٨﴾ إِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞ لَّا رَيۡبَ فِيهَا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يُؤۡمِنُونَ ﴿٥٩﴾ وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ ﴿٦٠﴾ ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلَّيۡلَ لِتَسۡكُنُواْ فِيهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَشۡكُرُونَ ﴿٦١﴾ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡ خَٰلِقُ كُلِّ شَيۡءٖ لَّآ إِلَٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ ﴿٦٢﴾ كَذَٰلِكَ يُؤۡفَكُ ٱلَّذِينَ كَانُواْ بِـَٔايَٰتِ ٱللَّهِ يَجۡحَدُونَ ﴿٦٣﴾", "w": [["وما يستوي الأعمى والبصير", "لا يستويان، فكذلك الكافر والمؤمن لا يستويان."], ["والذين آمنوا وعملوا الصالحات ولا المسيء", "لا يستويان أيضاً، فكذلك لا يستوي الموقن والشاك."], ["إن الساعة لآتية", "ساعة نهاية هذه الحياة وإقبال الأخرى جائية لا شك."], ["إن الذين يستكبرون عن عبادتي", "عن دعائي."], ["سيدخلون جهنم داخرين", "صاغرين ذليلين."], ["لتسكنوا فيه", "لتنقطعوا عن الحركة فتستريحوا."], ["والنهار مبصراً", "مضيئاً لتتمكنوا فيه من الحركة والعمل."], ["ذلكم الله ربكم", "الذي أمركم بدعائه ووعدكم بالاستجابة، وجعل لكم الليل والنهار، لا إله لكم غيره ولا رب لكم سواه."], ["فأنّى تُؤفكون", "كيف تُصرفون عنه وهو ربكم إلى أوثان لا تسمع ولا تبصر؟"], ["كذلك يُؤفك الذين كانوا بآيات الله يجحدون", "كما صُرف أولئك عن الإيمان يُصرف الجاحدون بآيات الله عن الحق."]], "m": "ما زال السياق في دعوة قريش إلى الإيمان: ما يستوي في حكم العقلاء الأعمى الذي لا يبصر شيئاً والبصير، فكذلك لا يستوي المؤمن السميع البصير والكافر الأعمى عن الدلائل الأصم عن نداء الحق، ولا المحسن العامل للصالحات والمسيء العامل للسيئات، فلِمَ لا يتعظ القوم؟ إنهم لظلمة نفوسهم قليلاً ما يتذكرون. إن الساعة التي كذّبوا بها ليستمروا على الباطل لآتية حتماً، ولكن أكثر الناس لا يؤمنون بها لانكبابهم على شهواتهم. ولما قرّر ربوبيته قال: وقال ربكم ادعوني أستجب لكم، سلوني أعطكم وأطيعوني أثبكم، فأنتم عبادي وأنا ربكم، إن الذين يستكبرون عن عبادتي ودعائي سيدخلون جهنم صاغرين ذليلين. ثم عرّفهم بنفسه ليؤمنوا به ويعبدوه: الله الذي جعل لكم الليل مظلماً لتنقطعوا فيه عن العمل فتستريحوا، والنهار مضيئاً للعمل وقضاء حاجاتكم، وإفضاله أكثر من أن يُذكر، إن الله لذو فضل على الناس ولكن أكثرهم لا يشكرون، فلا يحمدونه بألسنتهم ولا يطيعونه بجوارحهم لاستيلاء الشيطان والغفلة عليهم. ذلكم الله ربكم خالق كل شيء لا معبود بحق إلا هو، فكيف تُصرفون عنه إلى أوثان لا تنفع ولا تضر؟ كذلك يُصرف الجاحدون بآيات الله في كل زمان ومكان، لأن الآيات حجج، فالمكذّب بها سيكذّب بكل شيء حتى بنفسه.", "h": ["بيان حقيقة، وهي أن الضدّين لا يجتمعان: فالكفر والإيمان، والإحسان والإساءة، والعمى والبصر، والصمم والسمع، كلها لا يستوي بعضها ببعض، فمحاولة الجمع بينها محاولة باطلة.", "قرب الساعة مع تحتّم مجيئها، والأدلة على ذلك العقلية والنقلية كثيرة جداً.", "فضل الدعاء، وقد ورد أن النبي ﷺ قال: «ليسأل أحدكم ربه حاجته كلها حتى شسع نعله». وللدعاء المستجاب شروط، منها: أن يكون القلب متعلقاً بالله معرضاً عما سواه، وألا يسأل ما فيه إثم، ولا يعتدي في الدعاء فيسأل ما لم تجرِ سنة الله به، كأن يسأل أن يرى الجنة يقظة، أو أن يعود شاباً وهو شيخ كبير، أو أن يُرزق الولد وهو لا يتزوج.", "الدعاء هو العبادة، ولذا من دعا غير الله فقد أشرك بالله.", "بيان إنعام الله وإفضاله، والمطالبة بشكر الله تعالى بحمده والثناء عليه وبطاعته."], "k": "«ادعوني أستجب لكم»… ما الحاجة التي أحملها ولم أرفعها إليه بعد؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (347, 40, 64, 76, 'سورة غافر ٦٤ – ٧٦', 'غافر: فادعوه مخلصين له الدين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 347) = $j$[{"lbl": "الآيات ٦٤ – ٦٨", "q": "ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارٗا وَٱلسَّمَآءَ بِنَآءٗ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴿٦٤﴾ هُوَ ٱلۡحَيُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٦٥﴾ ۞قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِيَ ٱلۡبَيِّنَٰتُ مِن رَّبِّي وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ ﴿٦٦﴾ هُوَ ٱلَّذِي خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ يُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡ ثُمَّ لِتَكُونُواْ شُيُوخٗاۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوٓاْ أَجَلٗا مُّسَمّٗى وَلَعَلَّكُمۡ تَعۡقِلُونَ ﴿٦٧﴾ هُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُۖ فَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ ﴿٦٨﴾", "w": [["الأرض قراراً", "قارّة بكم لا تتحرك فيفسد ما عليها من إنشاء وتعمير."], ["والسماء بناءً", "محكمة إحكام البناء فلا تسقط عليكم ولا يسقط منها شيء."], ["وصوّركم", "في أرحام أمهاتكم فأحسن صوركم."], ["من الطيبات", "الحلال المستلذّ غير المستقذر، وهي كثيرة."], ["فتبارك الله", "تعاظم وكثرت بركاته."], ["فادعوه مخلصين له الدين", "اعبدوه وحده ولا تشركوا به شيئاً في عباداته دعاءً كان أو غيره."], ["قل إني نُهيت", "نهاني ربي أن أعبد الأوثان التي تعبدون."], ["وأُمرت أن أُسلم لرب العالمين", "أمرني ربي أن أسلم له وجهي وأخلص له عملي."], ["هو الذي خلقكم من تراب", "خلق أبانا آدم من تراب، وخلقنا نحن ذريته مما ذُكر من أطوار."], ["ثم لتبلغوا أشُدّكم", "كمال أجسامكم وعقولكم في سن ما فوق الثلاثين."], ["ومنكم من يُتوفّى من قبل", "من يتوفّاه ربه قبل سن الشيخوخة والهرم."], ["ولتبلغوا أجلاً مسمى", "لتعيشوا حتى نهاية العمر المحددة لكل إنسان."], ["ولعلكم تعقلون", "طوّركم هذه الأطوار رجاء أن تعقلوا دلائل قدرة الله وعلمه وحكمته فتؤمنوا به."], ["يحيي ويميت", "يخلق الإنسان وقد كان عدماً، ويميته عند نهاية أجله."], ["فإذا قضى أمراً", "حكم بوجوده."], ["فإنما يقول له كن فيكون", "لا يحتاج إلى وسائط، وإنما هي الإرادة، فإذا أراد شيئاً قال له كن فيكون."]], "m": "ما زال السياق في تعريف العباد بربهم حتى يؤمنوا به ويعبدوه، إذ كمالهم وسعادتهم متوقفان على ذلك: الله الذي جعل لكم الأرض قارّة ثابتة لا تتحرك بكم فتضطرب حياتكم، والسماء بناءً محفوظاً من التصدع والسقوط، وصوّركم في أرحام أمهاتكم فأحسن صوركم، ورزقكم من الطيبات من حلال الطعام والشراب واللباس والمراكب، ذلكم الله ربكم لا رب لكم سواه، فتبارك الله رب العالمين ومالكهم والمدبّر لأمرهم، هو الحي الذي لا يموت، لا إله إلا هو، فادعوه مخلصين له الدين لا تشركوا بعبادته أحداً، قائلين: الحمد لله رب العالمين. قل يا نبينا لقومك: إني نهاني ربي أن أعبد ما تدعون من دون الله من أصنام لا تنفع ولا تضر لما جاءني من الحجج على بطلان عبادتها، وأمرني أن أُسلم لرب العالمين فأنقاد لأمره ونهيه وأفوّض أمري إليه. هو الذي خلقكم من تراب نظراً إلى أصلكم آدم، ثم من نطفة، ثم من علقة دم متجمد، ثم يخرجكم أطفالاً، ثم لتبلغوا اكتمال أبدانكم وعقولكم بتخطيكم الثلاثين، ثم لتكونوا شيوخاً بتجاوزكم الستين، ومنكم من يُتوفّى قبل الشيخوخة وما أكثرهم، ولتبلغوا أجلاً مسمى، ولعلكم إذا تفكّرتم في هذه الأطوار تعرفون أن ربكم واحد. هو الذي يحيي النطف الميتة فإذا هي بشر أحياء، ويميت الأحياء عند نهاية آجالهم، ومن أعظم مظاهر قدرته أنه يقول للشيء إذا أراده: كن فيكون، ولا يتخلّف أبداً. هذا هو الله، وجبت محبته وطاعته ولزمت معرفته.", "h": ["بيان مظاهر قدرة الله تعالى في الخلق والإيجاد والإرزاق والإحياء والإماتة، وكلها معرّفة به تعالى، وموجبة له العبادة والمحبة والإنابة والرغبة والرهبة، ونافية لها عما سواه من سائر خلقه.", "تقرير التوحيد ووجوب عبادة الله تعالى وحده لا شريك له.", "بيان خلق الإنسان وأطوار حياته، وهي من الآيات الكونية الموجبة للإيمان بالله وتوحيده في عبادته، إذ هو الخالق الرازق المحيي المميت، لا إله غيره ولا رب سواه."], "k": "«ومنكم من يُتوفّى من قبل»… لا أضمن أن أبلغ الشيخوخة؛ فهل أعيش كمن قد يُتوفّى اليوم؟"}, {"lbl": "الآيات ٦٩ – ٧٦", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصۡرَفُونَ ﴿٦٩﴾ ٱلَّذِينَ كَذَّبُواْ بِٱلۡكِتَٰبِ وَبِمَآ أَرۡسَلۡنَا بِهِۦ رُسُلَنَاۖ فَسَوۡفَ يَعۡلَمُونَ ﴿٧٠﴾ إِذِ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَٰقِهِمۡ وَٱلسَّلَٰسِلُ يُسۡحَبُونَ ﴿٧١﴾ فِي ٱلۡحَمِيمِ ثُمَّ فِي ٱلنَّارِ يُسۡجَرُونَ ﴿٧٢﴾ ثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ ﴿٧٣﴾ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمۡ نَكُن نَّدۡعُواْ مِن قَبۡلُ شَيۡـٔٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلۡكَٰفِرِينَ ﴿٧٤﴾ ذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ ﴿٧٥﴾ ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ ﴿٧٦﴾", "w": [["يجادلون في آيات الله", "في القرآن وما حواه من حجج وبراهين دالة على الحق."], ["أنّى يُصرفون", "كيف يُصرفون عن الحق مع وضوح الأدلة؟"], ["الذين كذّبوا بالكتاب", "بالقرآن."], ["وبما أرسلنا به رسلنا", "من وجوب الإسلام لله بعبادته وحده وطاعته والإيمان بلقائه."], ["فسوف يعلمون", "عقوبة تكذيبهم."], ["إذ الأغلال في أعناقهم", "وقت وجود الأغلال في أعناقهم يعلمون عاقبة كفرهم."], ["ثم في النار يُسجَرون", "يُوقَدون."], ["أين ما كنتم تشركون", "يُسألون تبكيتاً لهم وخزياً."], ["قالوا ضلّوا عنا", "غابوا عنا فلم نرهم."], ["بل لم نكن ندعو من قبل شيئاً", "أنكروا عبادة الأصنام، أو لم يعتبروا عبادتها شيئاً، وهو كذلك."], ["بما كنتم تفرحون في الأرض بغير الحق", "بالشرك والمعاصي."], ["وبما كنتم تمرحون", "بالتوسع في الفرح، لأن المرح شدة الفرح."], ["فبئس مثوى المتكبرين", "دخول جهنم والخلود فيها بئس مأوى للمتكبرين."]], "m": "ما زال السياق في الدعوة إلى التوحيد والبعث وتقرير النبوة: ألم تر يا محمد إلى الذين يجادلون في آيات الله القرآنية لإبطالها وصرف الناس عنها؟ وهذا تعجيب من حالهم: كيف يُصرفون عن الحق بعد ظهور أدلته؟ الذين كذّبوا بالقرآن وبما أرسلنا به رسلنا من التوحيد والإيمان فسوف يعلمون عاقبة تكذيبهم وقت تكون الأغلال في أعناقهم والسلاسل في أرجلهم، تسحبهم الزبانية في الحميم، وهو ماء حار متناهٍ في الحرارة، ثم في النار يوقدون كما توقد بالحطب. هذا عذاب جسماني، ووراءه عذاب روحي إذ تقول لهم الملائكة تبكيتاً: أين أوثانكم التي كنتم تعبدونها مع الله؟ فيقولون: غابوا عنا فلم نرهم، بل ما كنا ندعو من قبل شيئاً؛ إنكار حملهم عليه الخوف، أو هو بحسب الواقع، إذ عبادة الأصنام ليست شيئاً لبطلانها. كذلك يُضل الله الكافرين. ذلكم العذاب بسبب فرحكم في الدنيا بالباطل من شرك وتكذيب وفسق، وبسبب مرحكم، ادخلوا أبواب جهنم باباً بعد باب، وهي أبواب الدركات، خالدين فيها لا تموتون ولا تخرجون، فبئس مثوى المتكبرين.", "h": ["التعجيب من حال المكذّبين بآيات الله المجادلين فيها، كيف يُصرفون عن الحق بعد وضوح أدلته وقوة براهينه.", "إبراز صورة واضحة للمكذبين بالآيات المجادلين لإبطال الحق وهم في جهنم يقاسون العذاب، بعد أن وُضعت الأغلال في أعناقهم والسلاسل في أرجلهم يُسحبون في الحميم.", "ذمّ الفرح بغير فضل الله ورحمته، وذمّ المرح وهو أشد الفرح.", "ذمّ التكبر وسوء عاقبة المتكبرين الذين يمنعهم الكبر من الاعتراف بالحق، ويحملهم على احتقار الناس وازدراء الضعفاء منهم."], "k": "«بما كنتم تفرحون في الأرض بغير الحق»… بماذا أفرح؟ وهل فرحي بما يرضي الله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 347;
insert into public.tdb_cards(topic, i, body) select 347, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٤ – ٦٨", "q": "ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارٗا وَٱلسَّمَآءَ بِنَآءٗ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴿٦٤﴾ هُوَ ٱلۡحَيُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ﴿٦٥﴾ ۞قُلۡ إِنِّي نُهِيتُ أَنۡ أَعۡبُدَ ٱلَّذِينَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِيَ ٱلۡبَيِّنَٰتُ مِن رَّبِّي وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَٰلَمِينَ ﴿٦٦﴾ هُوَ ٱلَّذِي خَلَقَكُم مِّن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ مِنۡ عَلَقَةٖ ثُمَّ يُخۡرِجُكُمۡ طِفۡلٗا ثُمَّ لِتَبۡلُغُوٓاْ أَشُدَّكُمۡ ثُمَّ لِتَكُونُواْ شُيُوخٗاۚ وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوٓاْ أَجَلٗا مُّسَمّٗى وَلَعَلَّكُمۡ تَعۡقِلُونَ ﴿٦٧﴾ هُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُۖ فَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ ﴿٦٨﴾", "w": [["الأرض قراراً", "قارّة بكم لا تتحرك فيفسد ما عليها من إنشاء وتعمير."], ["والسماء بناءً", "محكمة إحكام البناء فلا تسقط عليكم ولا يسقط منها شيء."], ["وصوّركم", "في أرحام أمهاتكم فأحسن صوركم."], ["من الطيبات", "الحلال المستلذّ غير المستقذر، وهي كثيرة."], ["فتبارك الله", "تعاظم وكثرت بركاته."], ["فادعوه مخلصين له الدين", "اعبدوه وحده ولا تشركوا به شيئاً في عباداته دعاءً كان أو غيره."], ["قل إني نُهيت", "نهاني ربي أن أعبد الأوثان التي تعبدون."], ["وأُمرت أن أُسلم لرب العالمين", "أمرني ربي أن أسلم له وجهي وأخلص له عملي."], ["هو الذي خلقكم من تراب", "خلق أبانا آدم من تراب، وخلقنا نحن ذريته مما ذُكر من أطوار."], ["ثم لتبلغوا أشُدّكم", "كمال أجسامكم وعقولكم في سن ما فوق الثلاثين."], ["ومنكم من يُتوفّى من قبل", "من يتوفّاه ربه قبل سن الشيخوخة والهرم."], ["ولتبلغوا أجلاً مسمى", "لتعيشوا حتى نهاية العمر المحددة لكل إنسان."], ["ولعلكم تعقلون", "طوّركم هذه الأطوار رجاء أن تعقلوا دلائل قدرة الله وعلمه وحكمته فتؤمنوا به."], ["يحيي ويميت", "يخلق الإنسان وقد كان عدماً، ويميته عند نهاية أجله."], ["فإذا قضى أمراً", "حكم بوجوده."], ["فإنما يقول له كن فيكون", "لا يحتاج إلى وسائط، وإنما هي الإرادة، فإذا أراد شيئاً قال له كن فيكون."]], "m": "ما زال السياق في تعريف العباد بربهم حتى يؤمنوا به ويعبدوه، إذ كمالهم وسعادتهم متوقفان على ذلك: الله الذي جعل لكم الأرض قارّة ثابتة لا تتحرك بكم فتضطرب حياتكم، والسماء بناءً محفوظاً من التصدع والسقوط، وصوّركم في أرحام أمهاتكم فأحسن صوركم، ورزقكم من الطيبات من حلال الطعام والشراب واللباس والمراكب، ذلكم الله ربكم لا رب لكم سواه، فتبارك الله رب العالمين ومالكهم والمدبّر لأمرهم، هو الحي الذي لا يموت، لا إله إلا هو، فادعوه مخلصين له الدين لا تشركوا بعبادته أحداً، قائلين: الحمد لله رب العالمين. قل يا نبينا لقومك: إني نهاني ربي أن أعبد ما تدعون من دون الله من أصنام لا تنفع ولا تضر لما جاءني من الحجج على بطلان عبادتها، وأمرني أن أُسلم لرب العالمين فأنقاد لأمره ونهيه وأفوّض أمري إليه. هو الذي خلقكم من تراب نظراً إلى أصلكم آدم، ثم من نطفة، ثم من علقة دم متجمد، ثم يخرجكم أطفالاً، ثم لتبلغوا اكتمال أبدانكم وعقولكم بتخطيكم الثلاثين، ثم لتكونوا شيوخاً بتجاوزكم الستين، ومنكم من يُتوفّى قبل الشيخوخة وما أكثرهم، ولتبلغوا أجلاً مسمى، ولعلكم إذا تفكّرتم في هذه الأطوار تعرفون أن ربكم واحد. هو الذي يحيي النطف الميتة فإذا هي بشر أحياء، ويميت الأحياء عند نهاية آجالهم، ومن أعظم مظاهر قدرته أنه يقول للشيء إذا أراده: كن فيكون، ولا يتخلّف أبداً. هذا هو الله، وجبت محبته وطاعته ولزمت معرفته.", "h": ["بيان مظاهر قدرة الله تعالى في الخلق والإيجاد والإرزاق والإحياء والإماتة، وكلها معرّفة به تعالى، وموجبة له العبادة والمحبة والإنابة والرغبة والرهبة، ونافية لها عما سواه من سائر خلقه.", "تقرير التوحيد ووجوب عبادة الله تعالى وحده لا شريك له.", "بيان خلق الإنسان وأطوار حياته، وهي من الآيات الكونية الموجبة للإيمان بالله وتوحيده في عبادته، إذ هو الخالق الرازق المحيي المميت، لا إله غيره ولا رب سواه."], "k": "«ومنكم من يُتوفّى من قبل»… لا أضمن أن أبلغ الشيخوخة؛ فهل أعيش كمن قد يُتوفّى اليوم؟"}, {"lbl": "الآيات ٦٩ – ٧٦", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِيٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصۡرَفُونَ ﴿٦٩﴾ ٱلَّذِينَ كَذَّبُواْ بِٱلۡكِتَٰبِ وَبِمَآ أَرۡسَلۡنَا بِهِۦ رُسُلَنَاۖ فَسَوۡفَ يَعۡلَمُونَ ﴿٧٠﴾ إِذِ ٱلۡأَغۡلَٰلُ فِيٓ أَعۡنَٰقِهِمۡ وَٱلسَّلَٰسِلُ يُسۡحَبُونَ ﴿٧١﴾ فِي ٱلۡحَمِيمِ ثُمَّ فِي ٱلنَّارِ يُسۡجَرُونَ ﴿٧٢﴾ ثُمَّ قِيلَ لَهُمۡ أَيۡنَ مَا كُنتُمۡ تُشۡرِكُونَ ﴿٧٣﴾ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا بَل لَّمۡ نَكُن نَّدۡعُواْ مِن قَبۡلُ شَيۡـٔٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلۡكَٰفِرِينَ ﴿٧٤﴾ ذَٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ ﴿٧٥﴾ ٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ ﴿٧٦﴾", "w": [["يجادلون في آيات الله", "في القرآن وما حواه من حجج وبراهين دالة على الحق."], ["أنّى يُصرفون", "كيف يُصرفون عن الحق مع وضوح الأدلة؟"], ["الذين كذّبوا بالكتاب", "بالقرآن."], ["وبما أرسلنا به رسلنا", "من وجوب الإسلام لله بعبادته وحده وطاعته والإيمان بلقائه."], ["فسوف يعلمون", "عقوبة تكذيبهم."], ["إذ الأغلال في أعناقهم", "وقت وجود الأغلال في أعناقهم يعلمون عاقبة كفرهم."], ["ثم في النار يُسجَرون", "يُوقَدون."], ["أين ما كنتم تشركون", "يُسألون تبكيتاً لهم وخزياً."], ["قالوا ضلّوا عنا", "غابوا عنا فلم نرهم."], ["بل لم نكن ندعو من قبل شيئاً", "أنكروا عبادة الأصنام، أو لم يعتبروا عبادتها شيئاً، وهو كذلك."], ["بما كنتم تفرحون في الأرض بغير الحق", "بالشرك والمعاصي."], ["وبما كنتم تمرحون", "بالتوسع في الفرح، لأن المرح شدة الفرح."], ["فبئس مثوى المتكبرين", "دخول جهنم والخلود فيها بئس مأوى للمتكبرين."]], "m": "ما زال السياق في الدعوة إلى التوحيد والبعث وتقرير النبوة: ألم تر يا محمد إلى الذين يجادلون في آيات الله القرآنية لإبطالها وصرف الناس عنها؟ وهذا تعجيب من حالهم: كيف يُصرفون عن الحق بعد ظهور أدلته؟ الذين كذّبوا بالقرآن وبما أرسلنا به رسلنا من التوحيد والإيمان فسوف يعلمون عاقبة تكذيبهم وقت تكون الأغلال في أعناقهم والسلاسل في أرجلهم، تسحبهم الزبانية في الحميم، وهو ماء حار متناهٍ في الحرارة، ثم في النار يوقدون كما توقد بالحطب. هذا عذاب جسماني، ووراءه عذاب روحي إذ تقول لهم الملائكة تبكيتاً: أين أوثانكم التي كنتم تعبدونها مع الله؟ فيقولون: غابوا عنا فلم نرهم، بل ما كنا ندعو من قبل شيئاً؛ إنكار حملهم عليه الخوف، أو هو بحسب الواقع، إذ عبادة الأصنام ليست شيئاً لبطلانها. كذلك يُضل الله الكافرين. ذلكم العذاب بسبب فرحكم في الدنيا بالباطل من شرك وتكذيب وفسق، وبسبب مرحكم، ادخلوا أبواب جهنم باباً بعد باب، وهي أبواب الدركات، خالدين فيها لا تموتون ولا تخرجون، فبئس مثوى المتكبرين.", "h": ["التعجيب من حال المكذّبين بآيات الله المجادلين فيها، كيف يُصرفون عن الحق بعد وضوح أدلته وقوة براهينه.", "إبراز صورة واضحة للمكذبين بالآيات المجادلين لإبطال الحق وهم في جهنم يقاسون العذاب، بعد أن وُضعت الأغلال في أعناقهم والسلاسل في أرجلهم يُسحبون في الحميم.", "ذمّ الفرح بغير فضل الله ورحمته، وذمّ المرح وهو أشد الفرح.", "ذمّ التكبر وسوء عاقبة المتكبرين الذين يمنعهم الكبر من الاعتراف بالحق، ويحملهم على احتقار الناس وازدراء الضعفاء منهم."], "k": "«بما كنتم تفرحون في الأرض بغير الحق»… بماذا أفرح؟ وهل فرحي بما يرضي الله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (348, 40, 77, 85, 'سورة غافر ٧٧ – ٨٥', 'غافر: فاصبر إن وعد الله حق', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 348) = $j$[{"lbl": "الآيات ٧٧ – ٨١", "q": "فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۚ فَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا يُرۡجَعُونَ ﴿٧٧﴾ وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ مِنۡهُم مَّن قَصَصۡنَا عَلَيۡكَ وَمِنۡهُم مَّن لَّمۡ نَقۡصُصۡ عَلَيۡكَۗ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ فَإِذَا جَآءَ أَمۡرُ ٱللَّهِ قُضِيَ بِٱلۡحَقِّ وَخَسِرَ هُنَالِكَ ٱلۡمُبۡطِلُونَ ﴿٧٨﴾ ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَنۡعَٰمَ لِتَرۡكَبُواْ مِنۡهَا وَمِنۡهَا تَأۡكُلُونَ ﴿٧٩﴾ وَلَكُمۡ فِيهَا مَنَٰفِعُ وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةٗ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ ﴿٨٠﴾ وَيُرِيكُمۡ ءَايَٰتِهِۦ فَأَيَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ ﴿٨١﴾", "w": [["فاصبر إن وعد الله حق", "اصبر يا رسولنا على دعوتهم متحمّلاً أذاهم، فإن وعد ربك بنصرك حق."], ["فإما نُرينّك بعض الذي نعدهم", "من العذاب في حياتك."], ["منهم من قصصنا عليك", "ذكرنا لك قصصهم وأخبارهم، وهم خمسة وعشرون."], ["أن يأتي بآية إلا بإذن الله", "لأنهم عبيد مربوبون لا يفعلون إلا ما يأذن لهم به."], ["وخسر هنالك المبطلون", "هلك أهل الباطل بعذاب الله فخسروا كل شيء."], ["جعل لكم الأنعام", "الإبل، وإن كان لفظ الأنعام يشمل البقر والغنم أيضاً."], ["ولكم فيها منافع", "من اللبن والنسل والوبر."], ["ولتبلغوا عليها حاجة في صدوركم", "حمل الأثقال وحمل أنفسكم من بلد إلى بلد، لأنها كسفن البر."], ["فأيّ آيات الله تنكرون", "فأي آية من تلك الآيات تنكرون؟ فإنها لظهورها لا تقبل الإنكار."]], "m": "بعد تلك الدعوة الإلهية للمشركين التي تلطّف فيها الأسلوب وتنوّعت المعاني، والمشركون يزدادون عتواً، أمر تعالى رسوله بالصبر على الاستمرار في دعوته متحمّلاً الأذى: فاصبر إن وعد الله بنصرك وإظهار دعوة الحق حق ولو كره المشركون، فإما نرينّك بعض الذي نعدهم من العذاب الدنيوي أو نتوفّينّك قبل ذلك فإلينا يرجعون فنعذّبهم بأشد أنواع العذاب في جهنم، وننعم عليك بجوارنا أنت والمؤمنون معك. ولقد أرسلنا رسلاً كثيرين من قبلك، منهم من قصصنا عليك خبرهم ومنهم من لم نقصص، بحسب الفائدة من القصص وعدمها، وما كان لأحدهم أن يأتي بمعجزة خارقة كما طالب قومك إلا بإذن الله، إذ هو الوهّاب لما يشاء لمن يشاء، فإذا جاء أمر الله بإهلاك المطالبين بالآيات تحدياً وعناداً حكم بين الرسول وقومه فنجّى رسوله والمؤمنين، وخسر هنالك المبطلون. ثم عرّفهم بنفسه مقرّراً ربوبيته الموجبة لألوهيته: الله الذي جعل لكم الأنعام لتركبوا منها وهي الإبل، ومنها تأكلون كالبقر والغنم، ولكم فيها منافع من الدرّ والوبر والصوف والشعر والجلود، ولتبلغوا عليها حمل أثقالكم إلى أماكن بعيدة لا تصلونها بدونها، فالإبل سفائن البر، وعليها وعلى السفن تُحملون. ويريكم آياته في أنفسكم وفي الآفاق، فأي آيات الله تنكرون وكلها في غاية الظهور؟", "h": ["وجوب الصبر على دعوة الحق والعمل في ذلك إلى أن يحكم الله تعالى.", "الآيات لا تُعطى لأحد إلا بإذن الله تعالى، إذ هو المعطي لها، فهي تابعة لمشيئته.", "من الرسل من لم يقصص الله تعالى أخبارهم، ومنهم من قصّ وهم خمسة وعشرون نبياً ورسولاً، وعدم القص لأخبارهم لا ينافي بيان عددهم إجمالاً لحديث أبي ذر في مسند أحمد: قلت: يا رسول الله كم عدّة الأنبياء؟ قال: «مائة ألف وأربعة وعشرون ألفاً، الرسل من ذلك ثلاثمائة وخمسة عشر جمّاً غفيراً».", "ذكر منّة الله على الناس في جعل الأنعام صالحة للانتفاع بها أكلاً وركوباً لبعضها، لعلهم يشكرون بالإيمان والطاعة والتوحيد."], "k": "«فأيّ آيات الله تنكرون»… أمرّ على نعمه كل يوم؛ فهل أراها آيات أم أتعوّدها؟"}, {"lbl": "الآيات ٨٢ – ٨٥", "q": "أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَكۡثَرَ مِنۡهُمۡ وَأَشَدَّ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ ﴿٨٢﴾ فَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٨٣﴾ فَلَمَّا رَأَوۡاْ بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِينَ ﴿٨٤﴾ فَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦۖ وَخَسِرَ هُنَالِكَ ٱلۡكَٰفِرُونَ ﴿٨٥﴾", "w": [["أفلم يسيروا في الأرض", "أعجزوا فلم يسيروا في الأرض شمالاً وجنوباً وغرباً؟"], ["كيف كان عاقبة الذين من قبلهم", "عاقبة المكذبين من قبلهم: قوم عاد وثمود وأصحاب الأيكة."], ["وآثاراً في الأرض", "وأكثر تأثيراً في الأرض من حيث الإنشاء والتعمير."], ["فما أغنى عنهم ما كانوا يكسبون", "لم يمنع العذاب عنهم كسبهم الطائل وقوتهم المادية."], ["فرحوا بما عندهم من العلم", "فرح الكافرون بما عندهم من العلم الذي هو الجهل."], ["فلم يكُ ينفعهم إيمانهم لما رأوا بأسنا", "لما رأوا عذابنا الشديد النازل بهم."]], "m": "ما زال السياق في طلب هداية قريش بما يعرض عليهم من صور حية لمن كذّب ولمن آمن: أعجزوا فلم يسيروا في أرض الجزيرة شمالاً ليروا آثار ثمود في مدائنها، وجنوباً ليروا آثار عاد، وغرباً ليروا آثار أصحاب الأيكة قوم شعيب وقرى قوم لوط، فينظروا نظر تفكّر واعتبار كيف كان عاقبة الذين من قبلهم؟ كانوا أكثر منهم وأشد قوة وآثاراً في الأرض من مصانع وقصور وجنات، فما أغنى عنهم لما جاءهم العذاب ما كانوا يكسبون من مال ورجال وقوة مادية. فلما جاءتهم رسلهم بالحجج الظاهرة على التوحيد والبعث وصدقهم في الرسالة فرحوا بما عندهم من العلم المادي، وسخروا من العلم الروحي واستهزؤوا بأهله، وأحاط بهم العذاب الذي كان نتيجة كفرهم واستهزائهم، فلما رأوا عذاب الله الشديد أعلنوا توبتهم: آمنا بالله وحده وكفرنا بما كنا به مشركين. فلم يك ينفعهم إيمانهم لما رأوا بأسنا، سنة الله التي قد خلت في عباده: أن الإيمان لا ينفع عند معاينة العذاب، إذ لو كان يُقبل عند رؤيته لما كفر كافر ولما دخل النار أحد. وخسر هنالك عند رؤية العذاب الكافرون المكذّبون المستهزئون.", "h": ["مشروعية السير في البلاد للعظة والاعتبار تقوية للإيمان.", "القوى المادية لا تغني عن أصحابها شيئاً إذا أرادهم الله بسوء.", "بيان سنة بشرية، وهي أن الماديين يغترّون بمعارفهم المادية ليستغنوا بها عن العلوم الروحية في نظرهم، إلا أنها لا تغني عنهم شيئاً عند حلول العذاب بهم في الدنيا وفي الآخرة."], "k": "«فرحوا بما عندهم من العلم»… هل يغنيني ما أعرفه من علوم الدنيا عن معرفة ربي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 348;
insert into public.tdb_cards(topic, i, body) select 348, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٧ – ٨١", "q": "فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞۚ فَإِمَّا نُرِيَنَّكَ بَعۡضَ ٱلَّذِي نَعِدُهُمۡ أَوۡ نَتَوَفَّيَنَّكَ فَإِلَيۡنَا يُرۡجَعُونَ ﴿٧٧﴾ وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ مِنۡهُم مَّن قَصَصۡنَا عَلَيۡكَ وَمِنۡهُم مَّن لَّمۡ نَقۡصُصۡ عَلَيۡكَۗ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ فَإِذَا جَآءَ أَمۡرُ ٱللَّهِ قُضِيَ بِٱلۡحَقِّ وَخَسِرَ هُنَالِكَ ٱلۡمُبۡطِلُونَ ﴿٧٨﴾ ٱللَّهُ ٱلَّذِي جَعَلَ لَكُمُ ٱلۡأَنۡعَٰمَ لِتَرۡكَبُواْ مِنۡهَا وَمِنۡهَا تَأۡكُلُونَ ﴿٧٩﴾ وَلَكُمۡ فِيهَا مَنَٰفِعُ وَلِتَبۡلُغُواْ عَلَيۡهَا حَاجَةٗ فِي صُدُورِكُمۡ وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ ﴿٨٠﴾ وَيُرِيكُمۡ ءَايَٰتِهِۦ فَأَيَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ ﴿٨١﴾", "w": [["فاصبر إن وعد الله حق", "اصبر يا رسولنا على دعوتهم متحمّلاً أذاهم، فإن وعد ربك بنصرك حق."], ["فإما نُرينّك بعض الذي نعدهم", "من العذاب في حياتك."], ["منهم من قصصنا عليك", "ذكرنا لك قصصهم وأخبارهم، وهم خمسة وعشرون."], ["أن يأتي بآية إلا بإذن الله", "لأنهم عبيد مربوبون لا يفعلون إلا ما يأذن لهم به."], ["وخسر هنالك المبطلون", "هلك أهل الباطل بعذاب الله فخسروا كل شيء."], ["جعل لكم الأنعام", "الإبل، وإن كان لفظ الأنعام يشمل البقر والغنم أيضاً."], ["ولكم فيها منافع", "من اللبن والنسل والوبر."], ["ولتبلغوا عليها حاجة في صدوركم", "حمل الأثقال وحمل أنفسكم من بلد إلى بلد، لأنها كسفن البر."], ["فأيّ آيات الله تنكرون", "فأي آية من تلك الآيات تنكرون؟ فإنها لظهورها لا تقبل الإنكار."]], "m": "بعد تلك الدعوة الإلهية للمشركين التي تلطّف فيها الأسلوب وتنوّعت المعاني، والمشركون يزدادون عتواً، أمر تعالى رسوله بالصبر على الاستمرار في دعوته متحمّلاً الأذى: فاصبر إن وعد الله بنصرك وإظهار دعوة الحق حق ولو كره المشركون، فإما نرينّك بعض الذي نعدهم من العذاب الدنيوي أو نتوفّينّك قبل ذلك فإلينا يرجعون فنعذّبهم بأشد أنواع العذاب في جهنم، وننعم عليك بجوارنا أنت والمؤمنون معك. ولقد أرسلنا رسلاً كثيرين من قبلك، منهم من قصصنا عليك خبرهم ومنهم من لم نقصص، بحسب الفائدة من القصص وعدمها، وما كان لأحدهم أن يأتي بمعجزة خارقة كما طالب قومك إلا بإذن الله، إذ هو الوهّاب لما يشاء لمن يشاء، فإذا جاء أمر الله بإهلاك المطالبين بالآيات تحدياً وعناداً حكم بين الرسول وقومه فنجّى رسوله والمؤمنين، وخسر هنالك المبطلون. ثم عرّفهم بنفسه مقرّراً ربوبيته الموجبة لألوهيته: الله الذي جعل لكم الأنعام لتركبوا منها وهي الإبل، ومنها تأكلون كالبقر والغنم، ولكم فيها منافع من الدرّ والوبر والصوف والشعر والجلود، ولتبلغوا عليها حمل أثقالكم إلى أماكن بعيدة لا تصلونها بدونها، فالإبل سفائن البر، وعليها وعلى السفن تُحملون. ويريكم آياته في أنفسكم وفي الآفاق، فأي آيات الله تنكرون وكلها في غاية الظهور؟", "h": ["وجوب الصبر على دعوة الحق والعمل في ذلك إلى أن يحكم الله تعالى.", "الآيات لا تُعطى لأحد إلا بإذن الله تعالى، إذ هو المعطي لها، فهي تابعة لمشيئته.", "من الرسل من لم يقصص الله تعالى أخبارهم، ومنهم من قصّ وهم خمسة وعشرون نبياً ورسولاً، وعدم القص لأخبارهم لا ينافي بيان عددهم إجمالاً لحديث أبي ذر في مسند أحمد: قلت: يا رسول الله كم عدّة الأنبياء؟ قال: «مائة ألف وأربعة وعشرون ألفاً، الرسل من ذلك ثلاثمائة وخمسة عشر جمّاً غفيراً».", "ذكر منّة الله على الناس في جعل الأنعام صالحة للانتفاع بها أكلاً وركوباً لبعضها، لعلهم يشكرون بالإيمان والطاعة والتوحيد."], "k": "«فأيّ آيات الله تنكرون»… أمرّ على نعمه كل يوم؛ فهل أراها آيات أم أتعوّدها؟"}, {"lbl": "الآيات ٨٢ – ٨٥", "q": "أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَانُوٓاْ أَكۡثَرَ مِنۡهُمۡ وَأَشَدَّ قُوَّةٗ وَءَاثَارٗا فِي ٱلۡأَرۡضِ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ ﴿٨٢﴾ فَلَمَّا جَآءَتۡهُمۡ رُسُلُهُم بِٱلۡبَيِّنَٰتِ فَرِحُواْ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٨٣﴾ فَلَمَّا رَأَوۡاْ بَأۡسَنَا قَالُوٓاْ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِينَ ﴿٨٤﴾ فَلَمۡ يَكُ يَنفَعُهُمۡ إِيمَٰنُهُمۡ لَمَّا رَأَوۡاْ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ فِي عِبَادِهِۦۖ وَخَسِرَ هُنَالِكَ ٱلۡكَٰفِرُونَ ﴿٨٥﴾", "w": [["أفلم يسيروا في الأرض", "أعجزوا فلم يسيروا في الأرض شمالاً وجنوباً وغرباً؟"], ["كيف كان عاقبة الذين من قبلهم", "عاقبة المكذبين من قبلهم: قوم عاد وثمود وأصحاب الأيكة."], ["وآثاراً في الأرض", "وأكثر تأثيراً في الأرض من حيث الإنشاء والتعمير."], ["فما أغنى عنهم ما كانوا يكسبون", "لم يمنع العذاب عنهم كسبهم الطائل وقوتهم المادية."], ["فرحوا بما عندهم من العلم", "فرح الكافرون بما عندهم من العلم الذي هو الجهل."], ["فلم يكُ ينفعهم إيمانهم لما رأوا بأسنا", "لما رأوا عذابنا الشديد النازل بهم."]], "m": "ما زال السياق في طلب هداية قريش بما يعرض عليهم من صور حية لمن كذّب ولمن آمن: أعجزوا فلم يسيروا في أرض الجزيرة شمالاً ليروا آثار ثمود في مدائنها، وجنوباً ليروا آثار عاد، وغرباً ليروا آثار أصحاب الأيكة قوم شعيب وقرى قوم لوط، فينظروا نظر تفكّر واعتبار كيف كان عاقبة الذين من قبلهم؟ كانوا أكثر منهم وأشد قوة وآثاراً في الأرض من مصانع وقصور وجنات، فما أغنى عنهم لما جاءهم العذاب ما كانوا يكسبون من مال ورجال وقوة مادية. فلما جاءتهم رسلهم بالحجج الظاهرة على التوحيد والبعث وصدقهم في الرسالة فرحوا بما عندهم من العلم المادي، وسخروا من العلم الروحي واستهزؤوا بأهله، وأحاط بهم العذاب الذي كان نتيجة كفرهم واستهزائهم، فلما رأوا عذاب الله الشديد أعلنوا توبتهم: آمنا بالله وحده وكفرنا بما كنا به مشركين. فلم يك ينفعهم إيمانهم لما رأوا بأسنا، سنة الله التي قد خلت في عباده: أن الإيمان لا ينفع عند معاينة العذاب، إذ لو كان يُقبل عند رؤيته لما كفر كافر ولما دخل النار أحد. وخسر هنالك عند رؤية العذاب الكافرون المكذّبون المستهزئون.", "h": ["مشروعية السير في البلاد للعظة والاعتبار تقوية للإيمان.", "القوى المادية لا تغني عن أصحابها شيئاً إذا أرادهم الله بسوء.", "بيان سنة بشرية، وهي أن الماديين يغترّون بمعارفهم المادية ليستغنوا بها عن العلوم الروحية في نظرهم، إلا أنها لا تغني عنهم شيئاً عند حلول العذاب بهم في الدنيا وفي الآخرة."], "k": "«فرحوا بما عندهم من العلم»… هل يغنيني ما أعرفه من علوم الدنيا عن معرفة ربي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (349, 41, 1, 12, 'سورة فصلت ١ – ١٢', 'فصلت: كتاب فُصّلت آياته', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 349) = $j$[{"lbl": "الآيات ١ – ٥", "q": "حمٓ ﴿١﴾ تَنزِيلٞ مِّنَ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ﴿٢﴾ كِتَٰبٞ فُصِّلَتۡ ءَايَٰتُهُۥ قُرۡءَانًا عَرَبِيّٗا لِّقَوۡمٖ يَعۡلَمُونَ ﴿٣﴾ بَشِيرٗا وَنَذِيرٗا فَأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا يَسۡمَعُونَ ﴿٤﴾ وَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ ءَاذَانِنَا وَقۡرٞ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابٞ فَٱعۡمَلۡ إِنَّنَا عَٰمِلُونَ ﴿٥﴾", "w": [["حم", "أحد الحروف المقطعة، الله أعلم بمراده به."], ["تنزيل من الرحمن الرحيم", "من الله، إذ هو الرحمن الرحيم."], ["فُصّلت آياته", "بُيّنت آياته غاية البيان بلسان عربي لقوم يعلمون."], ["بشيراً ونذيراً", "مبشّراً أهل الإيمان والعمل الصالح بالفوز، ومنذراً المكذبين الكافرين بالخسران."], ["فأعرض أكثرهم", "أعرض عن سماع القرآن أكثر مشركي مكة."], ["فهم لا يسمعون", "سماع تعقّل وتدبّر لينتفعوا بما يسمعون."], ["في أكنّة", "أغطية، جمع كِنان: ما يُكَنّ فيه الشيء ويُستر."], ["وفي آذاننا وقر", "ثقل فلا نطيق السمع."], ["ومن بيننا وبينك حجاب", "مانع وفاصل بيننا فلا نسمع ما تقول ولا نرى ما تفعل."]], "m": "حم: الله أعلم بمراده به، وقد ذكرنا فائدتين لمثل هذه الحروف في أول سورة غافر. تنزيل من الرحمن الرحيم على عبده ورسوله محمد ﷺ، وليس كما يقول المبطلون، كتاب جليل القدر بُيّنت آياته حال كونه قرآناً عربياً لقوم يعلمون معاني الكلام وأسراره، بشيراً لأهل الإيمان والعمل الصالح بالجنة، ونذيراً للمشركين المكذبين من عذاب النار. ومع بيانه ووضوح ما دعا إليه أعرض أكثر كفار قريش عنه فهم لا يسمعونه ولا يريدون سماعه، وقالوا معتذرين بأقبح الأعذار: قلوبنا في أغطية تسترها فلا نفهم ما تدعونا إليه من التوحيد والبعث، وفي آذاننا ثقل فلا نقوى على سماع ما تقول، ومن بيننا وبينك حائل فلا نسمع ما تقول ولا نرى ما تعمل، فاتركنا كما تركناك، واعمل على نصرة دينك فإننا عاملون على نصرة ديننا والحفاظ على معتقداتنا. وهذه نهاية المفاصلة التي أبدتها قريش للرسول ﷺ.", "h": ["تعيّن تعلّم اللغة العربية على كل مسلم يريد أن يفهم كلام الله القرآن العظيم.", "اشتمال القرآن على أسلوب الترغيب والترهيب، وهي البشارة والنذارة.", "بيان شدة عداوة المشركين للتوحيد والداعين إليه في كل زمان ومكان."], "k": "«قرآناً عربياً لقوم يعلمون»… كم آية أقرؤها ولا أفهم معناها؛ فهل أتعلّم لغته لأفهمه؟"}, {"lbl": "الآيات ٦ – ٨", "q": "قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَيۡلٞ لِّلۡمُشۡرِكِينَ ﴿٦﴾ ٱلَّذِينَ لَا يُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ﴿٧﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ ﴿٨﴾", "w": [["قل إنما أنا بشر مثلكم", "لست ملكاً، وإنما أنا بشر مثلكم من بني آدم."], ["يوحى إليّ أنما إلهكم إله واحد", "يوحي الله إليّ أن معبودكم أيها الناس إله واحد لا ثاني له."], ["فاستقيموا إليه", "بإخلاص العبادة له دون سواه."], ["واستغفروه", "اطلبوا منه أن يغفر لكم ذنوبكم التي كانت قبل الاستقامة، وهي الشرك والمعاصي."], ["وويل للمشركين", "عذاب شديد سيحلّ بهم لإغضابهم الرب بمضادّته بآلهة باطلة."], ["لا يؤتون الزكاة", "زكاة أموالهم، وزكاة أنفسهم بما يطهّرها من أوضار الشرك والمعاصي."], ["لهم أجر غير ممنون", "ثواب الآخرة، وهو الجنة ونعيمها، لا ينقطع بحال."]], "m": "بعد تلك المفاصلة التي قام بها المشركون حفاظاً على الوثنية أمر تعالى رسوله أن يقول لهم: إنما أنا بشر مثلكم في آدميتي، لم أدّعِ يوماً غيرها فلم أقل إني ملك، إلا أني أفضلكم بشيء هو أنه يوحى إليّ من ربي، والموحى به أنما إلهكم الحق إله واحد لا شريك له في ربوبيته ولا في ألوهيته، فاخلعوا تلك الأوثان واستقيموا إليه بإخلاص العبادة، واستغفروه من الشرك والمعاصي. ثم أخبر أن الويل، وهو مرّ العذاب، للمشركين بربهم الذين لا يؤتون زكاة أموالهم، وهم بالآخرة كافرون لا يؤمنون بالبعث والجزاء. إن الذين آمنوا بالله ووعده ووعيده وشرعه، وعملوا الصالحات بأداء الفرائض والكثير من النوافل بعد تجنّبهم الشرك والكبائر، لهم أجر غير مقطوع، وهو الجنة إذ نعيمها لا ينقطع على من ناله.", "h": ["تقرير النبوة والتوحيد.", "وجوب الاستقامة على شرع الله.", "وجوب الاستغفار من كل ذنب صغيراً كان أو كبيراً.", "وجوب الزكاة في الأموال، ووجوب تزكية النفوس بالإيمان وصالح الأعمال."], "k": "«فاستقيموا إليه واستغفروه»… الاستقامة يتخلّلها تقصير، فيأتي الاستغفار يرمّمها؛ فهل أجمع بينهما؟"}, {"lbl": "الآيات ٩ – ١٢", "q": "۞قُلۡ أَئِنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِي خَلَقَ ٱلۡأَرۡضَ فِي يَوۡمَيۡنِ وَتَجۡعَلُونَ لَهُۥٓ أَندَادٗاۚ ذَٰلِكَ رَبُّ ٱلۡعَٰلَمِينَ ﴿٩﴾ وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوۡقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقۡوَٰتَهَا فِيٓ أَرۡبَعَةِ أَيَّامٖ سَوَآءٗ لِّلسَّآئِلِينَ ﴿١٠﴾ ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِيَ دُخَانٞ فَقَالَ لَهَا وَلِلۡأَرۡضِ ٱئۡتِيَا طَوۡعًا أَوۡ كَرۡهٗا قَالَتَآ أَتَيۡنَا طَآئِعِينَ ﴿١١﴾ فَقَضَىٰهُنَّ سَبۡعَ سَمَٰوَاتٖ فِي يَوۡمَيۡنِ وَأَوۡحَىٰ فِي كُلِّ سَمَآءٍ أَمۡرَهَاۚ وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَحِفۡظٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ﴿١٢﴾", "w": [["بالذي خلق الأرض في يومين", "الأحد والاثنين."], ["وتجعلون له أنداداً", "شركاء، وهذا داخل في حيّز الإنكار الشديد عليهم."], ["ذلك رب العالمين", "الله مالك العالمين، وهم كل ما سواه."], ["وجعل فيها رواسي", "جبالاً ثوابت."], ["وبارك فيها", "في الأرض بكثرة المياه والزروع والضروع."], ["وقدّر فيها أقواتها", "أقوات الناس والبهائم."], ["في أربعة أيام", "في تمام أربعة أيام، وهي الأحد والاثنين والثلاثاء والأربعاء."], ["سواءً للسائلين", "سواء لمن يسأل، فإنها لا زيادة فيها ولا نقصان."], ["ثم استوى إلى السماء", "قصد بإرادته الربانية إلى السماء وهي دخان قبل أن تكون سماء."], ["فقضاهنّ سبع سماوات في يومين", "الخميس والجمعة، ولذا سُميت الجمعة لاجتماع الخلق فيها."], ["وأوحى في كل سماء أمرها", "ما أراد أن يكون فيها من الخلق والأعمال."], ["بمصابيح", "بنجوم."], ["وحفظاً", "وحفظناها من استراق الشياطين السمع بالشهب."], ["ذلك تقدير العزيز العليم", "خلق العزيز في ملكه العليم بخلقه."]], "m": "بعد إصرار المشركين على التكذيب أمر تعالى رسوله أن يقول لهم: أئنكم لتكفرون بالذي خلق الأرض في يومين؟ إن كفركم عجب، هل تعلمون بمن تكفرون؟ إنكم تكفرون بالذي خلق الأكوان كلها علويّها وسفليّها في ستة أيام، وهذه الأكوان كلها آيات شاهدات على وجوده وقدرته وعلمه، وموجبة له الربوبية والألوهية دون غيره. وأعجب من ذلك أنكم تجعلون له شركاء تسوّونهم به وهم أصنام لا تسمع ولا تبصر، ذلك رب العالمين ومالكهم. وجعل في الأرض جبالاً ثوابت ترسو حتى لا تميد بأهلها، وبارك فيها بكثرة المياه والرزق والخيرات، وقدّر فيها أقواتها تقديراً يعجز البيان عن وصفه والآلات الحاسبة عن عدّه، في أربعة أيام سواءً لمن يسأل عنها: الأحد والاثنين والثلاثاء والأربعاء. ثم استوى إلى السماء، قصد بإرادته إلى السماء وهي دخان، بخار ارتفع من الماء الذي كان عرشه عليه، فقال لها وللأرض: ائتيا طوعاً أو كرهاً، قالتا: أتينا طائعين، لم يكن لنا أن نخالف أمر ربنا، فقضاهنّ سبع سماوات في يومين هما الخميس والجمعة، وأوحى في كل سماء ما أراد أن يخلقه فيها من المخلوقات والطاعات، وزيّنا السماء الدنيا بالنجوم، وجعلناها حفظاً من الشياطين أن تسترق السمع، فالملائكة يرجمونهم بالشهب فيحترقون أو يُخبَلون. ذلك تقدير العزيز الغالب على أمره، العليم بتدبير ملكه وأحوال خلقه.", "h": ["الكفر بالله لا ذنب فوقه، فما بعد الكفر ذنب، وهو عجيب، وأعجب منه اتخاذ أصنام وأحجار أوثاناً تُعبد مع الله الحي القيوم مالك الملك ذي الجلال والإكرام.", "بيان الأيام التي خلق الله فيها العوالم العلوية والسفلية، وهي ستة أيام، أي على قدر ستة أيام من أيام الدنيا، مبدوءة بالأحد منتهية بالجمعة، وقدرة الله صالحة لخلق السماوات والأرض وما فيهما بكلمة «كن»، ولكن لحِكم عالية أرادها الله، منها تعليم عباده الأناة والتدرّج في إيجاد الأشياء شيئاً فشيئاً.", "لا تعارض بين قوله هنا «ثم استوى إلى السماء» المُشعر بأن خلق السماوات كان بعد خلق الأرض، وبين قوله في النازعات «والأرض بعد ذلك دحاها» المُفهم أن دحو الأرض كان بعد خلق السماء؛ إذ فسّر تعالى دحو الأرض بإخراج مائها ومرعاها، وتقدير الأقوات لا يستلزم إظهار ما قدّره إلى حيّز الوجود، فخلق الأرض في يومين وقدّر الأقوات في يومين، وبعد أن خلق السماوات دحا الأرض فأخرج منها ما قدّره فيها من أقوات.", "بيان فائدتين عظيمتين للنجوم: الأولى أنها زينة السماء بها تضاء وتشرق وتذهب الوحشة منها، والثانية أن تُرمى الشياطين بالشهب من النجوم."], "k": "«قالتا أتينا طائعين»… السماوات والأرض أطاعت بلا تردّد؛ فما الذي يؤخّرني أنا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 349;
insert into public.tdb_cards(topic, i, body) select 349, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "حمٓ ﴿١﴾ تَنزِيلٞ مِّنَ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ ﴿٢﴾ كِتَٰبٞ فُصِّلَتۡ ءَايَٰتُهُۥ قُرۡءَانًا عَرَبِيّٗا لِّقَوۡمٖ يَعۡلَمُونَ ﴿٣﴾ بَشِيرٗا وَنَذِيرٗا فَأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا يَسۡمَعُونَ ﴿٤﴾ وَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ ءَاذَانِنَا وَقۡرٞ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابٞ فَٱعۡمَلۡ إِنَّنَا عَٰمِلُونَ ﴿٥﴾", "w": [["حم", "أحد الحروف المقطعة، الله أعلم بمراده به."], ["تنزيل من الرحمن الرحيم", "من الله، إذ هو الرحمن الرحيم."], ["فُصّلت آياته", "بُيّنت آياته غاية البيان بلسان عربي لقوم يعلمون."], ["بشيراً ونذيراً", "مبشّراً أهل الإيمان والعمل الصالح بالفوز، ومنذراً المكذبين الكافرين بالخسران."], ["فأعرض أكثرهم", "أعرض عن سماع القرآن أكثر مشركي مكة."], ["فهم لا يسمعون", "سماع تعقّل وتدبّر لينتفعوا بما يسمعون."], ["في أكنّة", "أغطية، جمع كِنان: ما يُكَنّ فيه الشيء ويُستر."], ["وفي آذاننا وقر", "ثقل فلا نطيق السمع."], ["ومن بيننا وبينك حجاب", "مانع وفاصل بيننا فلا نسمع ما تقول ولا نرى ما تفعل."]], "m": "حم: الله أعلم بمراده به، وقد ذكرنا فائدتين لمثل هذه الحروف في أول سورة غافر. تنزيل من الرحمن الرحيم على عبده ورسوله محمد ﷺ، وليس كما يقول المبطلون، كتاب جليل القدر بُيّنت آياته حال كونه قرآناً عربياً لقوم يعلمون معاني الكلام وأسراره، بشيراً لأهل الإيمان والعمل الصالح بالجنة، ونذيراً للمشركين المكذبين من عذاب النار. ومع بيانه ووضوح ما دعا إليه أعرض أكثر كفار قريش عنه فهم لا يسمعونه ولا يريدون سماعه، وقالوا معتذرين بأقبح الأعذار: قلوبنا في أغطية تسترها فلا نفهم ما تدعونا إليه من التوحيد والبعث، وفي آذاننا ثقل فلا نقوى على سماع ما تقول، ومن بيننا وبينك حائل فلا نسمع ما تقول ولا نرى ما تعمل، فاتركنا كما تركناك، واعمل على نصرة دينك فإننا عاملون على نصرة ديننا والحفاظ على معتقداتنا. وهذه نهاية المفاصلة التي أبدتها قريش للرسول ﷺ.", "h": ["تعيّن تعلّم اللغة العربية على كل مسلم يريد أن يفهم كلام الله القرآن العظيم.", "اشتمال القرآن على أسلوب الترغيب والترهيب، وهي البشارة والنذارة.", "بيان شدة عداوة المشركين للتوحيد والداعين إليه في كل زمان ومكان."], "k": "«قرآناً عربياً لقوم يعلمون»… كم آية أقرؤها ولا أفهم معناها؛ فهل أتعلّم لغته لأفهمه؟"}, {"lbl": "الآيات ٦ – ٨", "q": "قُلۡ إِنَّمَآ أَنَا۠ بَشَرٞ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞ فَٱسۡتَقِيمُوٓاْ إِلَيۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَيۡلٞ لِّلۡمُشۡرِكِينَ ﴿٦﴾ ٱلَّذِينَ لَا يُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡأٓخِرَةِ هُمۡ كَٰفِرُونَ ﴿٧﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ ﴿٨﴾", "w": [["قل إنما أنا بشر مثلكم", "لست ملكاً، وإنما أنا بشر مثلكم من بني آدم."], ["يوحى إليّ أنما إلهكم إله واحد", "يوحي الله إليّ أن معبودكم أيها الناس إله واحد لا ثاني له."], ["فاستقيموا إليه", "بإخلاص العبادة له دون سواه."], ["واستغفروه", "اطلبوا منه أن يغفر لكم ذنوبكم التي كانت قبل الاستقامة، وهي الشرك والمعاصي."], ["وويل للمشركين", "عذاب شديد سيحلّ بهم لإغضابهم الرب بمضادّته بآلهة باطلة."], ["لا يؤتون الزكاة", "زكاة أموالهم، وزكاة أنفسهم بما يطهّرها من أوضار الشرك والمعاصي."], ["لهم أجر غير ممنون", "ثواب الآخرة، وهو الجنة ونعيمها، لا ينقطع بحال."]], "m": "بعد تلك المفاصلة التي قام بها المشركون حفاظاً على الوثنية أمر تعالى رسوله أن يقول لهم: إنما أنا بشر مثلكم في آدميتي، لم أدّعِ يوماً غيرها فلم أقل إني ملك، إلا أني أفضلكم بشيء هو أنه يوحى إليّ من ربي، والموحى به أنما إلهكم الحق إله واحد لا شريك له في ربوبيته ولا في ألوهيته، فاخلعوا تلك الأوثان واستقيموا إليه بإخلاص العبادة، واستغفروه من الشرك والمعاصي. ثم أخبر أن الويل، وهو مرّ العذاب، للمشركين بربهم الذين لا يؤتون زكاة أموالهم، وهم بالآخرة كافرون لا يؤمنون بالبعث والجزاء. إن الذين آمنوا بالله ووعده ووعيده وشرعه، وعملوا الصالحات بأداء الفرائض والكثير من النوافل بعد تجنّبهم الشرك والكبائر، لهم أجر غير مقطوع، وهو الجنة إذ نعيمها لا ينقطع على من ناله.", "h": ["تقرير النبوة والتوحيد.", "وجوب الاستقامة على شرع الله.", "وجوب الاستغفار من كل ذنب صغيراً كان أو كبيراً.", "وجوب الزكاة في الأموال، ووجوب تزكية النفوس بالإيمان وصالح الأعمال."], "k": "«فاستقيموا إليه واستغفروه»… الاستقامة يتخلّلها تقصير، فيأتي الاستغفار يرمّمها؛ فهل أجمع بينهما؟"}, {"lbl": "الآيات ٩ – ١٢", "q": "۞قُلۡ أَئِنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِي خَلَقَ ٱلۡأَرۡضَ فِي يَوۡمَيۡنِ وَتَجۡعَلُونَ لَهُۥٓ أَندَادٗاۚ ذَٰلِكَ رَبُّ ٱلۡعَٰلَمِينَ ﴿٩﴾ وَجَعَلَ فِيهَا رَوَٰسِيَ مِن فَوۡقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقۡوَٰتَهَا فِيٓ أَرۡبَعَةِ أَيَّامٖ سَوَآءٗ لِّلسَّآئِلِينَ ﴿١٠﴾ ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِيَ دُخَانٞ فَقَالَ لَهَا وَلِلۡأَرۡضِ ٱئۡتِيَا طَوۡعًا أَوۡ كَرۡهٗا قَالَتَآ أَتَيۡنَا طَآئِعِينَ ﴿١١﴾ فَقَضَىٰهُنَّ سَبۡعَ سَمَٰوَاتٖ فِي يَوۡمَيۡنِ وَأَوۡحَىٰ فِي كُلِّ سَمَآءٍ أَمۡرَهَاۚ وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنۡيَا بِمَصَٰبِيحَ وَحِفۡظٗاۚ ذَٰلِكَ تَقۡدِيرُ ٱلۡعَزِيزِ ٱلۡعَلِيمِ ﴿١٢﴾", "w": [["بالذي خلق الأرض في يومين", "الأحد والاثنين."], ["وتجعلون له أنداداً", "شركاء، وهذا داخل في حيّز الإنكار الشديد عليهم."], ["ذلك رب العالمين", "الله مالك العالمين، وهم كل ما سواه."], ["وجعل فيها رواسي", "جبالاً ثوابت."], ["وبارك فيها", "في الأرض بكثرة المياه والزروع والضروع."], ["وقدّر فيها أقواتها", "أقوات الناس والبهائم."], ["في أربعة أيام", "في تمام أربعة أيام، وهي الأحد والاثنين والثلاثاء والأربعاء."], ["سواءً للسائلين", "سواء لمن يسأل، فإنها لا زيادة فيها ولا نقصان."], ["ثم استوى إلى السماء", "قصد بإرادته الربانية إلى السماء وهي دخان قبل أن تكون سماء."], ["فقضاهنّ سبع سماوات في يومين", "الخميس والجمعة، ولذا سُميت الجمعة لاجتماع الخلق فيها."], ["وأوحى في كل سماء أمرها", "ما أراد أن يكون فيها من الخلق والأعمال."], ["بمصابيح", "بنجوم."], ["وحفظاً", "وحفظناها من استراق الشياطين السمع بالشهب."], ["ذلك تقدير العزيز العليم", "خلق العزيز في ملكه العليم بخلقه."]], "m": "بعد إصرار المشركين على التكذيب أمر تعالى رسوله أن يقول لهم: أئنكم لتكفرون بالذي خلق الأرض في يومين؟ إن كفركم عجب، هل تعلمون بمن تكفرون؟ إنكم تكفرون بالذي خلق الأكوان كلها علويّها وسفليّها في ستة أيام، وهذه الأكوان كلها آيات شاهدات على وجوده وقدرته وعلمه، وموجبة له الربوبية والألوهية دون غيره. وأعجب من ذلك أنكم تجعلون له شركاء تسوّونهم به وهم أصنام لا تسمع ولا تبصر، ذلك رب العالمين ومالكهم. وجعل في الأرض جبالاً ثوابت ترسو حتى لا تميد بأهلها، وبارك فيها بكثرة المياه والرزق والخيرات، وقدّر فيها أقواتها تقديراً يعجز البيان عن وصفه والآلات الحاسبة عن عدّه، في أربعة أيام سواءً لمن يسأل عنها: الأحد والاثنين والثلاثاء والأربعاء. ثم استوى إلى السماء، قصد بإرادته إلى السماء وهي دخان، بخار ارتفع من الماء الذي كان عرشه عليه، فقال لها وللأرض: ائتيا طوعاً أو كرهاً، قالتا: أتينا طائعين، لم يكن لنا أن نخالف أمر ربنا، فقضاهنّ سبع سماوات في يومين هما الخميس والجمعة، وأوحى في كل سماء ما أراد أن يخلقه فيها من المخلوقات والطاعات، وزيّنا السماء الدنيا بالنجوم، وجعلناها حفظاً من الشياطين أن تسترق السمع، فالملائكة يرجمونهم بالشهب فيحترقون أو يُخبَلون. ذلك تقدير العزيز الغالب على أمره، العليم بتدبير ملكه وأحوال خلقه.", "h": ["الكفر بالله لا ذنب فوقه، فما بعد الكفر ذنب، وهو عجيب، وأعجب منه اتخاذ أصنام وأحجار أوثاناً تُعبد مع الله الحي القيوم مالك الملك ذي الجلال والإكرام.", "بيان الأيام التي خلق الله فيها العوالم العلوية والسفلية، وهي ستة أيام، أي على قدر ستة أيام من أيام الدنيا، مبدوءة بالأحد منتهية بالجمعة، وقدرة الله صالحة لخلق السماوات والأرض وما فيهما بكلمة «كن»، ولكن لحِكم عالية أرادها الله، منها تعليم عباده الأناة والتدرّج في إيجاد الأشياء شيئاً فشيئاً.", "لا تعارض بين قوله هنا «ثم استوى إلى السماء» المُشعر بأن خلق السماوات كان بعد خلق الأرض، وبين قوله في النازعات «والأرض بعد ذلك دحاها» المُفهم أن دحو الأرض كان بعد خلق السماء؛ إذ فسّر تعالى دحو الأرض بإخراج مائها ومرعاها، وتقدير الأقوات لا يستلزم إظهار ما قدّره إلى حيّز الوجود، فخلق الأرض في يومين وقدّر الأقوات في يومين، وبعد أن خلق السماوات دحا الأرض فأخرج منها ما قدّره فيها من أقوات.", "بيان فائدتين عظيمتين للنجوم: الأولى أنها زينة السماء بها تضاء وتشرق وتذهب الوحشة منها، والثانية أن تُرمى الشياطين بالشهب من النجوم."], "k": "«قالتا أتينا طائعين»… السماوات والأرض أطاعت بلا تردّد؛ فما الذي يؤخّرني أنا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (350, 41, 13, 29, 'سورة فصلت ١٣ – ٢٩', 'فصلت: شهادة الجوارح', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 350) = $j$[{"lbl": "الآيات ١٣ – ١٨", "q": "فَإِنۡ أَعۡرَضُواْ فَقُلۡ أَنذَرۡتُكُمۡ صَٰعِقَةٗ مِّثۡلَ صَٰعِقَةِ عَادٖ وَثَمُودَ ﴿١٣﴾ إِذۡ جَآءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ قَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَـٰٓئِكَةٗ فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ﴿١٤﴾ فَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةٗۖ وَكَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ ﴿١٥﴾ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِيٓ أَيَّامٖ نَّحِسَاتٖ لِّنُذِيقَهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَخۡزَىٰۖ وَهُمۡ لَا يُنصَرُونَ ﴿١٦﴾ وَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ فَأَخَذَتۡهُمۡ صَٰعِقَةُ ٱلۡعَذَابِ ٱلۡهُونِ بِمَا كَانُواْ يَكۡسِبُونَ ﴿١٧﴾ وَنَجَّيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ﴿١٨﴾", "w": [["فإن أعرضوا", "كفار قريش عن الإيمان والتوحيد بعد ذلك البيان المفصّل."], ["أنذرتكم صاعقة", "خوّفتكم عذاباً مهلكاً كالذي أهلك عاداً وثمود."], ["من بين أيديهم ومن خلفهم", "كناية عن أن الرسول بلّغهم بعناية فائقة، يأتيهم من أمامهم ومن خلفهم."], ["لو شاء ربنا لأنزل ملائكة", "بدلاً عنكم أيها الرسل من البشر."], ["بغير الحق", "بغير أن يأذن الله لهم بذلك العلو والاستكبار."], ["ريحاً صرصراً", "ذات صوت يُسمع له صرصرة مع البرودة الشديدة."], ["في أيام نحسات", "مشؤومات عليهم لم يفلحوا بعدها."], ["ولعذاب الآخرة أخزى", "أشد خزياً من عذاب الدنيا."], ["فاستحبّوا العمى على الهدى", "استحبّوا الكفر على الإيمان، إذ الكفر ظلام والإيمان نور."], ["وكانوا يتقون", "الشرك والمعاصي."]], "m": "ما زال السياق في طلب هداية قريش: فإن أعرضوا بعد ذلك البيان المبيّن لقدرة الله وعلمه فقل لهم: خوّفتكم صاعقة تنزل بكم إن أصررتم، مثل صاعقة عاد وثمود. إذ جاءتهم الرسل هود وصالح من بين أيديهم ومن خلفهم، بلّغوهم دعوة الله بعناية فائقة قائلين: ألا تعبدوا إلا الله، فقالوا: لو شاء ربنا لأنزل ملائكة يدعوننا لا أن يرسل بشراً مثلكم، فإنا بما أُرسلتم به كافرون، فأيأسوا الرسل من إجابتهم. فأما عاد قوم هود فاستكبروا في الأرض بغير الحق، حملهم الكبر الناجم عن القوة المادية على رفض دعوة هود، واستكبارهم لا حق لهم فيه لضعفهم أمام قوة الله، وقالوا متحدّين: من أشد منا قوة؟ أوَلم يروا أن الله الذي خلقهم هو أشد منهم قوة؟ إذ كل قوة لهم مصدرها الله، فقوتهم ليست ذاتية ولكنها موهوبة. وكانوا بآياتنا يجحدون، وهذا أكبر ذنب، فأرسلنا عليهم ريحاً باردة ذات صوت مزعج دامت سبع ليال وثمانية أيام فلم تُبق منهم أحداً، في أيام مشؤومات عليهم، لنذيقهم عذاب الخزي في الحياة الدنيا، ولعذاب الآخرة أشد خزياً وهم لا يُنصرون. وأما ثمود قوم صالح فبيّنا لهم الطريق فاستحبّوا الضلال على الهدى، وقتلوا الناقة وهمّوا بقتل صالح، فأخذتهم صاعقة العذاب المهين صباح السبت، صيحة انخلعت لها قلوبهم ورجفت الأرض من تحتهم فهلكوا عن آخرهم، بما كانوا يكسبون من الشرك والظلم. ونجّينا صالحاً ومن معه من المؤمنين الذين آمنوا وكانوا يتقون الشرك والمعاصي، وكانوا أربعة آلاف مؤمن ومؤمنة.", "h": ["التحذير من الإعراض عن إجابة دعوة الحق، والاستمرار في التمرّد والعصيان.", "تقرير التوحيد، وهو أن لا إله إلا الله.", "دعوة الرسل واحدة، وهي الأمر بالكفر بالطاغوت، والإيمان بالله وعبادته وحده بما شرع للناس.", "التنديد بالاستكبار، وأنه سبب الكفر والعصيان.", "لا مصيبة إلا بذنب: «بما كانوا يكسبون» أي من الذنوب.", "الإيمان والتقوى هما سبيل النجاة من العذاب في الدنيا والآخرة، وهما ركنا الولاية، ولاية الله تعالى، لقوله: «ألا إن أولياء الله لا خوف عليهم ولا هم يحزنون الذين آمنوا وكانوا يتقون»."], "k": "«من أشد منا قوة»… ما القوة التي أغترّ بها؛ صحتي أم مالي أم ذكائي؟ وكلها موهوبة."}, {"lbl": "الآيات ١٩ – ٢٤", "q": "وَيَوۡمَ يُحۡشَرُ أَعۡدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ يُوزَعُونَ ﴿١٩﴾ حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُواْ يَعۡمَلُونَ ﴿٢٠﴾ وَقَالُواْ لِجُلُودِهِمۡ لِمَ شَهِدتُّمۡ عَلَيۡنَاۖ قَالُوٓاْ أَنطَقَنَا ٱللَّهُ ٱلَّذِيٓ أَنطَقَ كُلَّ شَيۡءٖۚ وَهُوَ خَلَقَكُمۡ أَوَّلَ مَرَّةٖ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٢١﴾ وَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن يَشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَلَآ أَبۡصَٰرُكُمۡ وَلَا جُلُودُكُمۡ وَلَٰكِن ظَنَنتُمۡ أَنَّ ٱللَّهَ لَا يَعۡلَمُ كَثِيرٗا مِّمَّا تَعۡمَلُونَ ﴿٢٢﴾ وَذَٰلِكُمۡ ظَنُّكُمُ ٱلَّذِي ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم مِّنَ ٱلۡخَٰسِرِينَ ﴿٢٣﴾ فَإِن يَصۡبِرُواْ فَٱلنَّارُ مَثۡوٗى لَّهُمۡۖ وَإِن يَسۡتَعۡتِبُواْ فَمَا هُم مِّنَ ٱلۡمُعۡتَبِينَ ﴿٢٤﴾", "w": [["فهم يُوزَعون", "يُحبس أولهم ليلحق آخرهم ليُساقوا إلى النار مجتمعين."], ["حتى إذا ما جاؤوها", "حتى إذا جاؤوا النار."], ["بما كانوا يعملون", "من الذنوب والمعاصي."], ["وهو خلقكم أول مرة", "بدأ خلقكم في الدنيا فخلقكم ثم أماتكم ثم أحياكم."], ["وما كنتم تستترون", "عند ارتكابكم الفواحش، أي تستخفون من أن يشهد عليكم سمعكم وأبصاركم فتتركوا الذنوب."], ["ولكن ظننتم أن الله لا يعلم", "عند ارتكابكم الفواحش ظننتم أن الله لا يعلم ذلك."], ["أرداكم", "أهلككم."], ["فإن يصبروا فالنار مثوى لهم", "فإن صبروا على العذاب فالنار مأوى لهم."], ["وإن يستعتبوا", "يطلبوا العُتبى، وهي الرضا، فلا يُرضى عنهم."]], "m": "ما زال السياق في دعوة قريش إلى أصول الدين، وهنا عرض لمشهد حيّ من مشاهد القيامة: اذكر لهم يوم يُحشر أعداء الله الذين كفروا به ولم يتقوه إلى النار، يُحبس أولهم ليلحق آخرهم فيساقون جميعاً، حتى إذا انتهوا إليها ادّعوا أنهم مظلومون وأخذوا يتنصّلون من ذنوبهم، وقالوا: لا نقبل شاهداً من غير أنفسنا، فيأمر الله أسماعهم وأبصارهم وجلودهم فتشهد عليهم بما كانوا يعملون. فرجعوا إلى جلودهم يلومونها: لِمَ شهدتم علينا؟ قالت: أنطقنا الله الذي أنطق كل شيء، وهو خلقكم أول مرة ثم أماتكم ثم أحياكم وإليه ترجعون، فالقادر على هذا قادر على أن ينطقنا. وما كنتم تستخفون فتتركوا محارم الله خشية أن يشهد عليكم سمعكم وأبصاركم وجلودكم، بل كنتم تجاهرون بذلك لعدم إيمانكم بالبعث، ولكن ظننتم أن الله لا يعلم كثيراً مما تعملون، وذلكم ظن سيئ ظننتموه بربكم أهلككم فأصبحتم من الخاسرين أنفسهم وأهليهم يوم القيامة. فإن يصبر أعداء الله فالنار مأواهم لا يخرجون منها، وإن يطلبوا الرضا فيُرضى عنهم فما هو بحاصل لهم أبداً، فهم بشرّ التقديرين.", "h": ["تقرير عقيدة البعث والجزاء بعرض مفصّل لحال أهل النار فيها.", "التحذير من فعل الفواحش وكبائر الذنوب، فإن جوارح المرء تشهد عليه.", "التحذير من سوء الظن بالله تعالى، ومن ذلك أن يظن المرء أن الله لا يطّلع عليه، أو لا يعلم ما يرتكبه، أو أنه لا يحاسبه أو لا يجزيه.", "وجوب حسن الظن بالله تعالى، وهو أن يرجو أن يغفر الله له إذا تاب من زلّة زلّها، وأن يرجو رحمته وعفوه إذا كان في حال العجز عن الطاعات، ولا سيما عند العجز عن العمل للمرض والضعف كالكبر ونحوه، فيُغلّب جانب الرجاء على جانب الخوف."], "k": "«وقالوا لجلودهم لِمَ شهدتم علينا»… جوارحي شهود عليّ؛ فبماذا ستشهد يدي وعيني؟"}, {"lbl": "الآيات ٢٥ – ٢٩", "q": "۞وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ خَٰسِرِينَ ﴿٢٥﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ﴿٢٦﴾ فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُواْ عَذَابٗا شَدِيدٗا وَلَنَجۡزِيَنَّهُمۡ أَسۡوَأَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ ﴿٢٧﴾ ذَٰلِكَ جَزَآءُ أَعۡدَآءِ ٱللَّهِ ٱلنَّارُۖ لَهُمۡ فِيهَا دَارُ ٱلۡخُلۡدِ جَزَآءَۢ بِمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ ﴿٢٨﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا ٱلَّذَيۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِيَكُونَا مِنَ ٱلۡأَسۡفَلِينَ ﴿٢٩﴾", "w": [["وقيّضنا لهم قرناء", "بعثنا لكفار مكة المعرضين قرناء من الشياطين."], ["فزيّنوا لهم ما بين أيديهم وما خلفهم", "حسّنوا لهم الكفر والشرك وإنكار البعث والجزاء."], ["وحقّ عليهم القول في أمم قد خلت", "وجب لهم العذاب في جملة أمم مضت قبلهم."], ["والغوا فيه لعلكم تغلبون", "الغطوا فيه بالباطل إذا سمعتم من يقرؤه."], ["ولنجزينّهم أسوأ الذي كانوا يعملون", "بأقبح جزاء أعمالهم التي كانوا يعملون."], ["أعداء الله", "من كفروا به ولم يتقوه."], ["أرنا اللذين أضلّانا من الجن والإنس", "إبليس من الجن، وقابيل بن آدم."], ["نجعلهما تحت أقدامنا", "في أسفل النار ليكونا من الأسفلين."]], "m": "ما زال السياق في دعوة المعرضين من كفار قريش: بعد أن أصرّوا على الباطل والشر فخبثوا خبثاً سهّل لأخباث الجن الاقتران بهم، بعثنا لهم قرناء من الشياطين، فزيّنوا لهم الكفر والمعاصي في الدنيا فهم منغمسون فيها، وزيّنوا لهم إنكار البعث والجنة والنار حتى لا يقصّروا في الشر ولا يفعلوا الخير، فحقّ عليهم العذاب في أمم قد خلت من قبلهم من الجن والإنس، إنهم كانوا خاسرين في حكم الله وقضائه. وقال الذين كفروا بعضهم لبعض: لا تسمعوا لهذا القرآن الذي يقرؤه محمد حتى لا تتأثروا به، والغوا فيه، صيحوا بكلام اللهو وصفّقوا وصفّروا حتى لا يتأثر به من يسمعه، لعلكم تغلبون محمداً على دينه فيبقى دينكم؛ وهذا منتهى الكيد. فردّ الله عليهم: فلنذيقنّ الذين كفروا عذاباً شديداً يوم القيامة، ولنجزينّهم بحسب أقبح سيئاتهم، ذلك جزاء أعداء الله الذين حاربوا رسوله ودعوته وكتابه: النار، لهم فيها دار الإقامة الدائمة، جزاءً بما كانوا بآياتنا يجحدون. ويقول الكافرون وهم في النار: يا ربنا أرنا اللذين كانا سبباً في إضلالنا بتزيين الباطل وتقبيح الحق، من الجن والإنس، نجعلهما تحت أقدامنا في النار ليكونا في الدرك الأسفل منها.", "h": ["بيان سنة الله تعالى في العبد إذا أعرض عن الحق الذي هو الإسلام، فخبث من جرّاء كسبه الشر والباطل وتوغّله في الظلم والفساد؛ يبعث الله تعالى عليه شيطاناً يكون قريناً له، فيزيّن له كل قبيح ويقبّح له كل حسن.", "بيان ما كان المشركون يكيدون به الإسلام ويحاربونه به، حتى باللغو عند قراءة القرآن حتى لا يُسمع ولا يُهتدى به.", "تقرير البعث والجزاء.", "بيان نقمة أهل النار على من كان سبباً في إضلالهم وإغوائهم، ومن سنّ لهم سنة شرّ يعملون بها، كإبليس وقابيل بن آدم؛ إذ الأول سنّ كل شر، والثاني سنّ سنة القتل ظلماً."], "k": "«والغوا فيه»… كم ضجيجاً أسمح له أن يغطي على صوت القرآن في يومي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 350;
insert into public.tdb_cards(topic, i, body) select 350, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٣ – ١٨", "q": "فَإِنۡ أَعۡرَضُواْ فَقُلۡ أَنذَرۡتُكُمۡ صَٰعِقَةٗ مِّثۡلَ صَٰعِقَةِ عَادٖ وَثَمُودَ ﴿١٣﴾ إِذۡ جَآءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَۖ قَالُواْ لَوۡ شَآءَ رَبُّنَا لَأَنزَلَ مَلَـٰٓئِكَةٗ فَإِنَّا بِمَآ أُرۡسِلۡتُم بِهِۦ كَٰفِرُونَ ﴿١٤﴾ فَأَمَّا عَادٞ فَٱسۡتَكۡبَرُواْ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَقَالُواْ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةٗۖ وَكَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ ﴿١٥﴾ فَأَرۡسَلۡنَا عَلَيۡهِمۡ رِيحٗا صَرۡصَرٗا فِيٓ أَيَّامٖ نَّحِسَاتٖ لِّنُذِيقَهُمۡ عَذَابَ ٱلۡخِزۡيِ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَعَذَابُ ٱلۡأٓخِرَةِ أَخۡزَىٰۖ وَهُمۡ لَا يُنصَرُونَ ﴿١٦﴾ وَأَمَّا ثَمُودُ فَهَدَيۡنَٰهُمۡ فَٱسۡتَحَبُّواْ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ فَأَخَذَتۡهُمۡ صَٰعِقَةُ ٱلۡعَذَابِ ٱلۡهُونِ بِمَا كَانُواْ يَكۡسِبُونَ ﴿١٧﴾ وَنَجَّيۡنَا ٱلَّذِينَ ءَامَنُواْ وَكَانُواْ يَتَّقُونَ ﴿١٨﴾", "w": [["فإن أعرضوا", "كفار قريش عن الإيمان والتوحيد بعد ذلك البيان المفصّل."], ["أنذرتكم صاعقة", "خوّفتكم عذاباً مهلكاً كالذي أهلك عاداً وثمود."], ["من بين أيديهم ومن خلفهم", "كناية عن أن الرسول بلّغهم بعناية فائقة، يأتيهم من أمامهم ومن خلفهم."], ["لو شاء ربنا لأنزل ملائكة", "بدلاً عنكم أيها الرسل من البشر."], ["بغير الحق", "بغير أن يأذن الله لهم بذلك العلو والاستكبار."], ["ريحاً صرصراً", "ذات صوت يُسمع له صرصرة مع البرودة الشديدة."], ["في أيام نحسات", "مشؤومات عليهم لم يفلحوا بعدها."], ["ولعذاب الآخرة أخزى", "أشد خزياً من عذاب الدنيا."], ["فاستحبّوا العمى على الهدى", "استحبّوا الكفر على الإيمان، إذ الكفر ظلام والإيمان نور."], ["وكانوا يتقون", "الشرك والمعاصي."]], "m": "ما زال السياق في طلب هداية قريش: فإن أعرضوا بعد ذلك البيان المبيّن لقدرة الله وعلمه فقل لهم: خوّفتكم صاعقة تنزل بكم إن أصررتم، مثل صاعقة عاد وثمود. إذ جاءتهم الرسل هود وصالح من بين أيديهم ومن خلفهم، بلّغوهم دعوة الله بعناية فائقة قائلين: ألا تعبدوا إلا الله، فقالوا: لو شاء ربنا لأنزل ملائكة يدعوننا لا أن يرسل بشراً مثلكم، فإنا بما أُرسلتم به كافرون، فأيأسوا الرسل من إجابتهم. فأما عاد قوم هود فاستكبروا في الأرض بغير الحق، حملهم الكبر الناجم عن القوة المادية على رفض دعوة هود، واستكبارهم لا حق لهم فيه لضعفهم أمام قوة الله، وقالوا متحدّين: من أشد منا قوة؟ أوَلم يروا أن الله الذي خلقهم هو أشد منهم قوة؟ إذ كل قوة لهم مصدرها الله، فقوتهم ليست ذاتية ولكنها موهوبة. وكانوا بآياتنا يجحدون، وهذا أكبر ذنب، فأرسلنا عليهم ريحاً باردة ذات صوت مزعج دامت سبع ليال وثمانية أيام فلم تُبق منهم أحداً، في أيام مشؤومات عليهم، لنذيقهم عذاب الخزي في الحياة الدنيا، ولعذاب الآخرة أشد خزياً وهم لا يُنصرون. وأما ثمود قوم صالح فبيّنا لهم الطريق فاستحبّوا الضلال على الهدى، وقتلوا الناقة وهمّوا بقتل صالح، فأخذتهم صاعقة العذاب المهين صباح السبت، صيحة انخلعت لها قلوبهم ورجفت الأرض من تحتهم فهلكوا عن آخرهم، بما كانوا يكسبون من الشرك والظلم. ونجّينا صالحاً ومن معه من المؤمنين الذين آمنوا وكانوا يتقون الشرك والمعاصي، وكانوا أربعة آلاف مؤمن ومؤمنة.", "h": ["التحذير من الإعراض عن إجابة دعوة الحق، والاستمرار في التمرّد والعصيان.", "تقرير التوحيد، وهو أن لا إله إلا الله.", "دعوة الرسل واحدة، وهي الأمر بالكفر بالطاغوت، والإيمان بالله وعبادته وحده بما شرع للناس.", "التنديد بالاستكبار، وأنه سبب الكفر والعصيان.", "لا مصيبة إلا بذنب: «بما كانوا يكسبون» أي من الذنوب.", "الإيمان والتقوى هما سبيل النجاة من العذاب في الدنيا والآخرة، وهما ركنا الولاية، ولاية الله تعالى، لقوله: «ألا إن أولياء الله لا خوف عليهم ولا هم يحزنون الذين آمنوا وكانوا يتقون»."], "k": "«من أشد منا قوة»… ما القوة التي أغترّ بها؛ صحتي أم مالي أم ذكائي؟ وكلها موهوبة."}, {"lbl": "الآيات ١٩ – ٢٤", "q": "وَيَوۡمَ يُحۡشَرُ أَعۡدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ يُوزَعُونَ ﴿١٩﴾ حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُواْ يَعۡمَلُونَ ﴿٢٠﴾ وَقَالُواْ لِجُلُودِهِمۡ لِمَ شَهِدتُّمۡ عَلَيۡنَاۖ قَالُوٓاْ أَنطَقَنَا ٱللَّهُ ٱلَّذِيٓ أَنطَقَ كُلَّ شَيۡءٖۚ وَهُوَ خَلَقَكُمۡ أَوَّلَ مَرَّةٖ وَإِلَيۡهِ تُرۡجَعُونَ ﴿٢١﴾ وَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن يَشۡهَدَ عَلَيۡكُمۡ سَمۡعُكُمۡ وَلَآ أَبۡصَٰرُكُمۡ وَلَا جُلُودُكُمۡ وَلَٰكِن ظَنَنتُمۡ أَنَّ ٱللَّهَ لَا يَعۡلَمُ كَثِيرٗا مِّمَّا تَعۡمَلُونَ ﴿٢٢﴾ وَذَٰلِكُمۡ ظَنُّكُمُ ٱلَّذِي ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم مِّنَ ٱلۡخَٰسِرِينَ ﴿٢٣﴾ فَإِن يَصۡبِرُواْ فَٱلنَّارُ مَثۡوٗى لَّهُمۡۖ وَإِن يَسۡتَعۡتِبُواْ فَمَا هُم مِّنَ ٱلۡمُعۡتَبِينَ ﴿٢٤﴾", "w": [["فهم يُوزَعون", "يُحبس أولهم ليلحق آخرهم ليُساقوا إلى النار مجتمعين."], ["حتى إذا ما جاؤوها", "حتى إذا جاؤوا النار."], ["بما كانوا يعملون", "من الذنوب والمعاصي."], ["وهو خلقكم أول مرة", "بدأ خلقكم في الدنيا فخلقكم ثم أماتكم ثم أحياكم."], ["وما كنتم تستترون", "عند ارتكابكم الفواحش، أي تستخفون من أن يشهد عليكم سمعكم وأبصاركم فتتركوا الذنوب."], ["ولكن ظننتم أن الله لا يعلم", "عند ارتكابكم الفواحش ظننتم أن الله لا يعلم ذلك."], ["أرداكم", "أهلككم."], ["فإن يصبروا فالنار مثوى لهم", "فإن صبروا على العذاب فالنار مأوى لهم."], ["وإن يستعتبوا", "يطلبوا العُتبى، وهي الرضا، فلا يُرضى عنهم."]], "m": "ما زال السياق في دعوة قريش إلى أصول الدين، وهنا عرض لمشهد حيّ من مشاهد القيامة: اذكر لهم يوم يُحشر أعداء الله الذين كفروا به ولم يتقوه إلى النار، يُحبس أولهم ليلحق آخرهم فيساقون جميعاً، حتى إذا انتهوا إليها ادّعوا أنهم مظلومون وأخذوا يتنصّلون من ذنوبهم، وقالوا: لا نقبل شاهداً من غير أنفسنا، فيأمر الله أسماعهم وأبصارهم وجلودهم فتشهد عليهم بما كانوا يعملون. فرجعوا إلى جلودهم يلومونها: لِمَ شهدتم علينا؟ قالت: أنطقنا الله الذي أنطق كل شيء، وهو خلقكم أول مرة ثم أماتكم ثم أحياكم وإليه ترجعون، فالقادر على هذا قادر على أن ينطقنا. وما كنتم تستخفون فتتركوا محارم الله خشية أن يشهد عليكم سمعكم وأبصاركم وجلودكم، بل كنتم تجاهرون بذلك لعدم إيمانكم بالبعث، ولكن ظننتم أن الله لا يعلم كثيراً مما تعملون، وذلكم ظن سيئ ظننتموه بربكم أهلككم فأصبحتم من الخاسرين أنفسهم وأهليهم يوم القيامة. فإن يصبر أعداء الله فالنار مأواهم لا يخرجون منها، وإن يطلبوا الرضا فيُرضى عنهم فما هو بحاصل لهم أبداً، فهم بشرّ التقديرين.", "h": ["تقرير عقيدة البعث والجزاء بعرض مفصّل لحال أهل النار فيها.", "التحذير من فعل الفواحش وكبائر الذنوب، فإن جوارح المرء تشهد عليه.", "التحذير من سوء الظن بالله تعالى، ومن ذلك أن يظن المرء أن الله لا يطّلع عليه، أو لا يعلم ما يرتكبه، أو أنه لا يحاسبه أو لا يجزيه.", "وجوب حسن الظن بالله تعالى، وهو أن يرجو أن يغفر الله له إذا تاب من زلّة زلّها، وأن يرجو رحمته وعفوه إذا كان في حال العجز عن الطاعات، ولا سيما عند العجز عن العمل للمرض والضعف كالكبر ونحوه، فيُغلّب جانب الرجاء على جانب الخوف."], "k": "«وقالوا لجلودهم لِمَ شهدتم علينا»… جوارحي شهود عليّ؛ فبماذا ستشهد يدي وعيني؟"}, {"lbl": "الآيات ٢٥ – ٢٩", "q": "۞وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ خَٰسِرِينَ ﴿٢٥﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ ﴿٢٦﴾ فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُواْ عَذَابٗا شَدِيدٗا وَلَنَجۡزِيَنَّهُمۡ أَسۡوَأَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ ﴿٢٧﴾ ذَٰلِكَ جَزَآءُ أَعۡدَآءِ ٱللَّهِ ٱلنَّارُۖ لَهُمۡ فِيهَا دَارُ ٱلۡخُلۡدِ جَزَآءَۢ بِمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ ﴿٢٨﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ رَبَّنَآ أَرِنَا ٱلَّذَيۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِيَكُونَا مِنَ ٱلۡأَسۡفَلِينَ ﴿٢٩﴾", "w": [["وقيّضنا لهم قرناء", "بعثنا لكفار مكة المعرضين قرناء من الشياطين."], ["فزيّنوا لهم ما بين أيديهم وما خلفهم", "حسّنوا لهم الكفر والشرك وإنكار البعث والجزاء."], ["وحقّ عليهم القول في أمم قد خلت", "وجب لهم العذاب في جملة أمم مضت قبلهم."], ["والغوا فيه لعلكم تغلبون", "الغطوا فيه بالباطل إذا سمعتم من يقرؤه."], ["ولنجزينّهم أسوأ الذي كانوا يعملون", "بأقبح جزاء أعمالهم التي كانوا يعملون."], ["أعداء الله", "من كفروا به ولم يتقوه."], ["أرنا اللذين أضلّانا من الجن والإنس", "إبليس من الجن، وقابيل بن آدم."], ["نجعلهما تحت أقدامنا", "في أسفل النار ليكونا من الأسفلين."]], "m": "ما زال السياق في دعوة المعرضين من كفار قريش: بعد أن أصرّوا على الباطل والشر فخبثوا خبثاً سهّل لأخباث الجن الاقتران بهم، بعثنا لهم قرناء من الشياطين، فزيّنوا لهم الكفر والمعاصي في الدنيا فهم منغمسون فيها، وزيّنوا لهم إنكار البعث والجنة والنار حتى لا يقصّروا في الشر ولا يفعلوا الخير، فحقّ عليهم العذاب في أمم قد خلت من قبلهم من الجن والإنس، إنهم كانوا خاسرين في حكم الله وقضائه. وقال الذين كفروا بعضهم لبعض: لا تسمعوا لهذا القرآن الذي يقرؤه محمد حتى لا تتأثروا به، والغوا فيه، صيحوا بكلام اللهو وصفّقوا وصفّروا حتى لا يتأثر به من يسمعه، لعلكم تغلبون محمداً على دينه فيبقى دينكم؛ وهذا منتهى الكيد. فردّ الله عليهم: فلنذيقنّ الذين كفروا عذاباً شديداً يوم القيامة، ولنجزينّهم بحسب أقبح سيئاتهم، ذلك جزاء أعداء الله الذين حاربوا رسوله ودعوته وكتابه: النار، لهم فيها دار الإقامة الدائمة، جزاءً بما كانوا بآياتنا يجحدون. ويقول الكافرون وهم في النار: يا ربنا أرنا اللذين كانا سبباً في إضلالنا بتزيين الباطل وتقبيح الحق، من الجن والإنس، نجعلهما تحت أقدامنا في النار ليكونا في الدرك الأسفل منها.", "h": ["بيان سنة الله تعالى في العبد إذا أعرض عن الحق الذي هو الإسلام، فخبث من جرّاء كسبه الشر والباطل وتوغّله في الظلم والفساد؛ يبعث الله تعالى عليه شيطاناً يكون قريناً له، فيزيّن له كل قبيح ويقبّح له كل حسن.", "بيان ما كان المشركون يكيدون به الإسلام ويحاربونه به، حتى باللغو عند قراءة القرآن حتى لا يُسمع ولا يُهتدى به.", "تقرير البعث والجزاء.", "بيان نقمة أهل النار على من كان سبباً في إضلالهم وإغوائهم، ومن سنّ لهم سنة شرّ يعملون بها، كإبليس وقابيل بن آدم؛ إذ الأول سنّ كل شر، والثاني سنّ سنة القتل ظلماً."], "k": "«والغوا فيه»… كم ضجيجاً أسمح له أن يغطي على صوت القرآن في يومي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (351, 41, 30, 39, 'سورة فصلت ٣٠ – ٣٩', 'فصلت: إن الذين قالوا ربنا الله ثم استقاموا', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 351) = $j$[{"lbl": "الآيات ٣٠ – ٣٢", "q": "إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَـٰٓئِكَةُ أَلَّا تَخَافُواْ وَلَا تَحۡزَنُواْ وَأَبۡشِرُواْ بِٱلۡجَنَّةِ ٱلَّتِي كُنتُمۡ تُوعَدُونَ ﴿٣٠﴾ نَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَلَكُمۡ فِيهَا مَا تَشۡتَهِيٓ أَنفُسُكُمۡ وَلَكُمۡ فِيهَا مَا تَدَّعُونَ ﴿٣١﴾ نُزُلٗا مِّنۡ غَفُورٖ رَّحِيمٖ ﴿٣٢﴾", "w": [["قالوا ربنا الله", "قالوا ذلك معلنين إيمانهم بأن الله ربهم الذي لا رب لهم غيره وإلههم الذي لا إله لهم سواه."], ["ثم استقاموا", "ثبتوا على ذلك فلم يبدّلوا ولم يغيّروا ولم يتركوا عبادة الله بفعل الأوامر وترك النواهي."], ["تتنزّل عليهم الملائكة", "عند الموت وعند الخروج من القبر، تتلقّاهم هناك."], ["ألا تخافوا ولا تحزنوا", "لا تخافوا مما أنتم مقبلون عليه فإنه رضوان الله ورحمته، ولا تحزنوا على ما خلّفتم وراءكم."], ["نحن أولياؤكم في الحياة الدنيا وفي الآخرة", "فبحكم ولايتنا لكم في الدنيا والآخرة لا تخافوا ولا تحزنوا."], ["ولكم فيها ما تدّعون", "ما تطلبون من سائر المشتهيات."], ["نُزُلاً من غفور رحيم", "رزقاً مهيّأً لكم من فضل رب غفور رحيم."]], "m": "لما بيّن حال الكافرين في الآخرة وهي أسوأ حال بيّن حال المؤمنين وهي أحسن حال: إن الذين قالوا ربنا الله لا رب لنا غيره ولا إله لنا سواه، ثم استقاموا فلم يشركوا به أحداً، فأدّوا الفرائض واجتنبوا النواهي وماتوا على ذلك، تتنزّل عليهم الملائكة عند الموت تقول لهم: لا تخافوا مما أنتم مقدمون عليه من البرزخ والدار الآخرة، ولا تحزنوا على ما خلّفتم وراءكم، وأبشروا بالجنة التي كنتم توعدونها في الكتاب وعلى لسان الرسول. نحن أولياؤكم في الحياة الدنيا كنا نسدّدكم ونحفظكم من الوقوع في المعاصي، وفي الآخرة نستقبلكم عند الخروج من قبوركم حتى تدخلوا جنة ربكم، ولكم فيها ما تشتهي أنفسكم من الملاذّ، ولكم فيها ما تطلبون، قِرىً وضيافةً من لدن رب غفور لكم رحيم بكم.", "h": ["فضل الإيمان والاستقامة عليه بأداء الفرائض واجتناب النواهي.", "بشرى أهل الإيمان والاستقامة عند الموت بالجنة، وهؤلاء هم أولياء الله المؤمنون المتقون، لهم البشرى في الحياة الدنيا وهي هذه، وفي الآخرة عند خروجهم من قبورهم.", "في الجنة ما تشتهيه الأنفس وتلذّه الأعين، ولأحدهم كل ما يطلبه ويدّعيه، وفوق ذلك النظر إلى وجه الله الكريم، وتلقّي التحية منه والتسليم."], "k": "«ثم استقاموا»… قولها سهل والثبات عليها هو الامتحان؛ فأين أحتاج أن أستقيم اليوم؟"}, {"lbl": "الآيات ٣٣ – ٣٦", "q": "وَمَنۡ أَحۡسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ إِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ ﴿٣٣﴾ وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةٞ كَأَنَّهُۥ وَلِيٌّ حَمِيمٞ ﴿٣٤﴾ وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٖ ﴿٣٥﴾ وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٣٦﴾", "w": [["ومن أحسن قولاً ممن دعا إلى الله", "لا أحد أحسن قولاً ممن دعا إلى توحيد الله."], ["وعمل صالحاً وقال إنني من المسلمين", "وعمل صالحاً، وهو شرط أيضاً، وقال إنني من المسلمين، شرط ثالث."], ["ولا تستوي الحسنة ولا السيئة", "لا تكون الحسنة كالسيئة ولا السيئة كالحسنة."], ["ادفع بالتي هي أحسن", "ادفع أيها المؤمن السيئة بالخصلة التي هي أحسن، كالغضب بالرضا والقطيعة بالصلة."], ["كأنه وليّ حميم", "كأنه صديق قريب في محبته لك إذا فعلت ذلك."], ["وما يُلقّاها إلا الذين صبروا", "وما يُعطى هذه الخصلة التي هي أحسن إلا الصابرون."], ["إلا ذو حظ عظيم", "ثواب عظيم وأجر جزيل في الآخرة، وأما في الدنيا فالخلق الحسن والكمال."], ["وإما ينزغنّك من الشيطان نزغ", "وإن يوسوس لك الشيطان بترك خير أو فعل شر."], ["فاستعذ بالله", "استجر بالله قائلاً: أعوذ بالله من الشيطان الرجيم."], ["إنه هو السميع العليم", "السميع لأقوال عباده العليم بما يصيبهم."]], "m": "لما ذكر بشرى أهل الإيمان ذكر بشرى ثانية لهم: ومن أحسن قولاً ممن دعا إلى الله وعمل صالحاً وقال إنني من المسلمين؟ ثلاثة شروط: الأول دعوته إلى الله بأن يُعبد فيُطاع ولا يُعصى، ويُذكر فلا يُنسى، ويُشكر فلا يُكفر، والثاني أن يعمل صالحاً فيؤدي الفرائض ويجتنب المحارم، والثالث أن يعتزّ بالإسلام فيقول: إنني من المسلمين. فلا أحد أحسن قولاً منه، ويدخل في هذا أولاً الرسل، ثم العلماء، ثم المجاهدون، ثم المؤذنون، ثم الدعاة الهداة المهديون. ولا تستوي الحسنة ولا السيئة: فالإيمان لا يساوى بالكفر، ولا التقوى بالفجور، ولا العدل بالظلم، كما أن الحسنات تتفاضل والسيئات تتفاضل، فصيام رمضان لا يساوي صيام تطوع، وقتل المؤمن لا يستوي مع شتمه. فادفع السيئة بالخصلة التي هي أحسن، فإذا الذي بينك وبينه عداوة قد انقلب في برّه بك واحترامه لك كأنه قريب يحبك. ولما كانت هذه الخصلة لا تتأتّى إلا لذوي النفوس الكاملة قال: وما يُعطاها إلا الذين صبروا، فكان الصبر خلقاً من أخلاقهم، وما يعطاها إلا ذو حظ عظيم في الأخلاق والكمال في الدنيا والأجر العظيم في الآخرة. ثم أرشد رسوله وكل فرد من أمته: إن وسوس لك الشيطان بفعل شر أو ترك خير، أو خطر لك خاطر سوء، فافزع إلى الله واستجر به، إنه هو السميع العليم، فالاستجارة به تحمي العبد من وسواس الشيطان.", "h": ["بيان فضل الدعوة إلى الله تعالى وشرف الدعاة العاملين.", "فضل الإسلام والاعتزاز به والتفاخر الصادق به.", "تقرير أن الحسنة لا تتساوى مع السيئة، كما أن الحسنات تتفاوت والسيئات تتفاوت.", "وجوب دفع السيئة من الأخ المسلم بالحسنة من القول والفعل.", "فضل العبد الذي يكمُل في نفسه وخلقه فيصبح يدفع السيئة بالحسنة.", "وجوب الاستعاذة بالله من الشيطان الرجيم إذا وسوس أو ألقى بخاطر سوء، إذ لا يقي منه ولا يحفظ إلا الله السميع العليم."], "k": "«ادفع بالتي هي أحسن»… من أساء إليّ مؤخراً؟ وما الحسنة التي أستطيع أن أردّ بها؟"}, {"lbl": "الآيات ٣٧ – ٣٩", "q": "وَمِنۡ ءَايَٰتِهِ ٱلَّيۡلُ وَٱلنَّهَارُ وَٱلشَّمۡسُ وَٱلۡقَمَرُۚ لَا تَسۡجُدُواْ لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَٱسۡجُدُواْۤ لِلَّهِۤ ٱلَّذِي خَلَقَهُنَّ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ ﴿٣٧﴾ فَإِنِ ٱسۡتَكۡبَرُواْ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيۡلِ وَٱلنَّهَارِ وَهُمۡ لَا يَسۡـَٔمُونَ۩ ﴿٣٨﴾ وَمِنۡ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَٰشِعَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِيٓ أَحۡيَاهَا لَمُحۡيِ ٱلۡمَوۡتَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٣٩﴾", "w": [["ومن آياته", "من جملة آياته الدالة على ألوهية الرب وحده."], ["الليل والنهار", "وجود الليل والنهار والشمس والقمر."], ["لا تسجدوا للشمس ولا للقمر", "لا تعبدوهما فإنهما من جملة مخلوقاته."], ["إن كنتم إياه تعبدون", "إن كنتم حقاً تريدون عبادته فاعبدوه وحده."], ["فالذين عند ربك", "الملائكة."], ["وهم لا يسأمون", "لا يملّون من عبادته ولا يكلّون."], ["ترى الأرض خاشعة", "يابسة جامدة لا نبات فيها ولا حياة."], ["اهتزّت وربت", "تحرّكت وانتفخت وظهر النبات فيها."], ["إن الذي أحياها لمحيي الموتى", "إن الذي أحيا الأرض قادر على إحياء الموتى يوم القيامة."]], "m": "ومن آياته الدالة على وجوده وقدرته وعلمه والموجبة لعبادته وتوحيده الليل والنهار وتعاقبهما بانتظام، والشمس والقمر وسيرهما في فلكيهما بدقة فائقة وحساب دقيق، فلا تسجدوا للشمس ولا للقمر أيها الناس فإنهما مخلوقان، واسجدوا لخالقهما إن كنتم إياه تعبدون كما تزعمون. فإن استكبروا عن الاستجابة فاعلم أن الذين عند ربك وهم الملائكة يسبّحون له بالليل والنهار وهم لا يسأمون. ومن علامات قدرته على إحياء الموتى للبعث أنك ترى الأرض أيام الجدب هامدة جامدة، فإذا أنزل عليها ماء المطر تحرّكت تربتها وانتفخت وعلاها النبات وظهرت فيها الحياة؛ كذلك إذا أراد الله إحياء الموتى أنزل عليهم ماءً من السماء بين النفختين، نفخة الفناء ونفخة البعث، فينبتون كما ينبت البقل. إن الذي أحياها لمحيي الموتى، إنه على كل شيء أراده قدير، إذا أراد شيئاً إنما يقول له كن فيكون.", "h": ["تقرير التوحيد بالأدلة القطعية الموجبة لله العبادة دون غيره من خلقه.", "بيان أن هناك من الناس من يعبدون الشمس ويسجدون لها من العرب والعجم، وأن ذلك شرك باطل؛ فالعبادة لا تكون للمخلوقات الخاضعة في حياتها للخالق، وإنما تكون لخالقها ومسخّرها لمنافع خلقه.", "تقرير عقيدة البعث والجزاء بذكر دليل من أظهر الأدلة، وهو موت الأرض بالجدب ثم حياتها بالغيث؛ إذ لا فرق بين حياة النبات بالماء وحياة الإنسان بالماء كذلك، فبعد نفخة الفناء ومضيّ أربعين عاماً ينزل من السماء ماء فيحيا الناس وينبتون من عَجْب الذنب كما ينبت النبات بالبذرة الكامنة في التربة.", "تقرير قدرة الله على كل شيء أراده، وهذه الصفة خاصة به تعالى موجبة لعبادته وطاعته بعد الإيمان به وتأليهه."], "k": "«ترى الأرض خاشعة فإذا أنزلنا عليها الماء اهتزّت»… قلبي حين يجفّ، يحييه ماء الذكر."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 351;
insert into public.tdb_cards(topic, i, body) select 351, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٠ – ٣٢", "q": "إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَـٰٓئِكَةُ أَلَّا تَخَافُواْ وَلَا تَحۡزَنُواْ وَأَبۡشِرُواْ بِٱلۡجَنَّةِ ٱلَّتِي كُنتُمۡ تُوعَدُونَ ﴿٣٠﴾ نَحۡنُ أَوۡلِيَآؤُكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَفِي ٱلۡأٓخِرَةِۖ وَلَكُمۡ فِيهَا مَا تَشۡتَهِيٓ أَنفُسُكُمۡ وَلَكُمۡ فِيهَا مَا تَدَّعُونَ ﴿٣١﴾ نُزُلٗا مِّنۡ غَفُورٖ رَّحِيمٖ ﴿٣٢﴾", "w": [["قالوا ربنا الله", "قالوا ذلك معلنين إيمانهم بأن الله ربهم الذي لا رب لهم غيره وإلههم الذي لا إله لهم سواه."], ["ثم استقاموا", "ثبتوا على ذلك فلم يبدّلوا ولم يغيّروا ولم يتركوا عبادة الله بفعل الأوامر وترك النواهي."], ["تتنزّل عليهم الملائكة", "عند الموت وعند الخروج من القبر، تتلقّاهم هناك."], ["ألا تخافوا ولا تحزنوا", "لا تخافوا مما أنتم مقبلون عليه فإنه رضوان الله ورحمته، ولا تحزنوا على ما خلّفتم وراءكم."], ["نحن أولياؤكم في الحياة الدنيا وفي الآخرة", "فبحكم ولايتنا لكم في الدنيا والآخرة لا تخافوا ولا تحزنوا."], ["ولكم فيها ما تدّعون", "ما تطلبون من سائر المشتهيات."], ["نُزُلاً من غفور رحيم", "رزقاً مهيّأً لكم من فضل رب غفور رحيم."]], "m": "لما بيّن حال الكافرين في الآخرة وهي أسوأ حال بيّن حال المؤمنين وهي أحسن حال: إن الذين قالوا ربنا الله لا رب لنا غيره ولا إله لنا سواه، ثم استقاموا فلم يشركوا به أحداً، فأدّوا الفرائض واجتنبوا النواهي وماتوا على ذلك، تتنزّل عليهم الملائكة عند الموت تقول لهم: لا تخافوا مما أنتم مقدمون عليه من البرزخ والدار الآخرة، ولا تحزنوا على ما خلّفتم وراءكم، وأبشروا بالجنة التي كنتم توعدونها في الكتاب وعلى لسان الرسول. نحن أولياؤكم في الحياة الدنيا كنا نسدّدكم ونحفظكم من الوقوع في المعاصي، وفي الآخرة نستقبلكم عند الخروج من قبوركم حتى تدخلوا جنة ربكم، ولكم فيها ما تشتهي أنفسكم من الملاذّ، ولكم فيها ما تطلبون، قِرىً وضيافةً من لدن رب غفور لكم رحيم بكم.", "h": ["فضل الإيمان والاستقامة عليه بأداء الفرائض واجتناب النواهي.", "بشرى أهل الإيمان والاستقامة عند الموت بالجنة، وهؤلاء هم أولياء الله المؤمنون المتقون، لهم البشرى في الحياة الدنيا وهي هذه، وفي الآخرة عند خروجهم من قبورهم.", "في الجنة ما تشتهيه الأنفس وتلذّه الأعين، ولأحدهم كل ما يطلبه ويدّعيه، وفوق ذلك النظر إلى وجه الله الكريم، وتلقّي التحية منه والتسليم."], "k": "«ثم استقاموا»… قولها سهل والثبات عليها هو الامتحان؛ فأين أحتاج أن أستقيم اليوم؟"}, {"lbl": "الآيات ٣٣ – ٣٦", "q": "وَمَنۡ أَحۡسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ إِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ ﴿٣٣﴾ وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةٞ كَأَنَّهُۥ وَلِيٌّ حَمِيمٞ ﴿٣٤﴾ وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٖ ﴿٣٥﴾ وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيۡطَٰنِ نَزۡغٞ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ﴿٣٦﴾", "w": [["ومن أحسن قولاً ممن دعا إلى الله", "لا أحد أحسن قولاً ممن دعا إلى توحيد الله."], ["وعمل صالحاً وقال إنني من المسلمين", "وعمل صالحاً، وهو شرط أيضاً، وقال إنني من المسلمين، شرط ثالث."], ["ولا تستوي الحسنة ولا السيئة", "لا تكون الحسنة كالسيئة ولا السيئة كالحسنة."], ["ادفع بالتي هي أحسن", "ادفع أيها المؤمن السيئة بالخصلة التي هي أحسن، كالغضب بالرضا والقطيعة بالصلة."], ["كأنه وليّ حميم", "كأنه صديق قريب في محبته لك إذا فعلت ذلك."], ["وما يُلقّاها إلا الذين صبروا", "وما يُعطى هذه الخصلة التي هي أحسن إلا الصابرون."], ["إلا ذو حظ عظيم", "ثواب عظيم وأجر جزيل في الآخرة، وأما في الدنيا فالخلق الحسن والكمال."], ["وإما ينزغنّك من الشيطان نزغ", "وإن يوسوس لك الشيطان بترك خير أو فعل شر."], ["فاستعذ بالله", "استجر بالله قائلاً: أعوذ بالله من الشيطان الرجيم."], ["إنه هو السميع العليم", "السميع لأقوال عباده العليم بما يصيبهم."]], "m": "لما ذكر بشرى أهل الإيمان ذكر بشرى ثانية لهم: ومن أحسن قولاً ممن دعا إلى الله وعمل صالحاً وقال إنني من المسلمين؟ ثلاثة شروط: الأول دعوته إلى الله بأن يُعبد فيُطاع ولا يُعصى، ويُذكر فلا يُنسى، ويُشكر فلا يُكفر، والثاني أن يعمل صالحاً فيؤدي الفرائض ويجتنب المحارم، والثالث أن يعتزّ بالإسلام فيقول: إنني من المسلمين. فلا أحد أحسن قولاً منه، ويدخل في هذا أولاً الرسل، ثم العلماء، ثم المجاهدون، ثم المؤذنون، ثم الدعاة الهداة المهديون. ولا تستوي الحسنة ولا السيئة: فالإيمان لا يساوى بالكفر، ولا التقوى بالفجور، ولا العدل بالظلم، كما أن الحسنات تتفاضل والسيئات تتفاضل، فصيام رمضان لا يساوي صيام تطوع، وقتل المؤمن لا يستوي مع شتمه. فادفع السيئة بالخصلة التي هي أحسن، فإذا الذي بينك وبينه عداوة قد انقلب في برّه بك واحترامه لك كأنه قريب يحبك. ولما كانت هذه الخصلة لا تتأتّى إلا لذوي النفوس الكاملة قال: وما يُعطاها إلا الذين صبروا، فكان الصبر خلقاً من أخلاقهم، وما يعطاها إلا ذو حظ عظيم في الأخلاق والكمال في الدنيا والأجر العظيم في الآخرة. ثم أرشد رسوله وكل فرد من أمته: إن وسوس لك الشيطان بفعل شر أو ترك خير، أو خطر لك خاطر سوء، فافزع إلى الله واستجر به، إنه هو السميع العليم، فالاستجارة به تحمي العبد من وسواس الشيطان.", "h": ["بيان فضل الدعوة إلى الله تعالى وشرف الدعاة العاملين.", "فضل الإسلام والاعتزاز به والتفاخر الصادق به.", "تقرير أن الحسنة لا تتساوى مع السيئة، كما أن الحسنات تتفاوت والسيئات تتفاوت.", "وجوب دفع السيئة من الأخ المسلم بالحسنة من القول والفعل.", "فضل العبد الذي يكمُل في نفسه وخلقه فيصبح يدفع السيئة بالحسنة.", "وجوب الاستعاذة بالله من الشيطان الرجيم إذا وسوس أو ألقى بخاطر سوء، إذ لا يقي منه ولا يحفظ إلا الله السميع العليم."], "k": "«ادفع بالتي هي أحسن»… من أساء إليّ مؤخراً؟ وما الحسنة التي أستطيع أن أردّ بها؟"}, {"lbl": "الآيات ٣٧ – ٣٩", "q": "وَمِنۡ ءَايَٰتِهِ ٱلَّيۡلُ وَٱلنَّهَارُ وَٱلشَّمۡسُ وَٱلۡقَمَرُۚ لَا تَسۡجُدُواْ لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَٱسۡجُدُواْۤ لِلَّهِۤ ٱلَّذِي خَلَقَهُنَّ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ ﴿٣٧﴾ فَإِنِ ٱسۡتَكۡبَرُواْ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيۡلِ وَٱلنَّهَارِ وَهُمۡ لَا يَسۡـَٔمُونَ۩ ﴿٣٨﴾ وَمِنۡ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَٰشِعَةٗ فَإِذَآ أَنزَلۡنَا عَلَيۡهَا ٱلۡمَآءَ ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِيٓ أَحۡيَاهَا لَمُحۡيِ ٱلۡمَوۡتَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ ﴿٣٩﴾", "w": [["ومن آياته", "من جملة آياته الدالة على ألوهية الرب وحده."], ["الليل والنهار", "وجود الليل والنهار والشمس والقمر."], ["لا تسجدوا للشمس ولا للقمر", "لا تعبدوهما فإنهما من جملة مخلوقاته."], ["إن كنتم إياه تعبدون", "إن كنتم حقاً تريدون عبادته فاعبدوه وحده."], ["فالذين عند ربك", "الملائكة."], ["وهم لا يسأمون", "لا يملّون من عبادته ولا يكلّون."], ["ترى الأرض خاشعة", "يابسة جامدة لا نبات فيها ولا حياة."], ["اهتزّت وربت", "تحرّكت وانتفخت وظهر النبات فيها."], ["إن الذي أحياها لمحيي الموتى", "إن الذي أحيا الأرض قادر على إحياء الموتى يوم القيامة."]], "m": "ومن آياته الدالة على وجوده وقدرته وعلمه والموجبة لعبادته وتوحيده الليل والنهار وتعاقبهما بانتظام، والشمس والقمر وسيرهما في فلكيهما بدقة فائقة وحساب دقيق، فلا تسجدوا للشمس ولا للقمر أيها الناس فإنهما مخلوقان، واسجدوا لخالقهما إن كنتم إياه تعبدون كما تزعمون. فإن استكبروا عن الاستجابة فاعلم أن الذين عند ربك وهم الملائكة يسبّحون له بالليل والنهار وهم لا يسأمون. ومن علامات قدرته على إحياء الموتى للبعث أنك ترى الأرض أيام الجدب هامدة جامدة، فإذا أنزل عليها ماء المطر تحرّكت تربتها وانتفخت وعلاها النبات وظهرت فيها الحياة؛ كذلك إذا أراد الله إحياء الموتى أنزل عليهم ماءً من السماء بين النفختين، نفخة الفناء ونفخة البعث، فينبتون كما ينبت البقل. إن الذي أحياها لمحيي الموتى، إنه على كل شيء أراده قدير، إذا أراد شيئاً إنما يقول له كن فيكون.", "h": ["تقرير التوحيد بالأدلة القطعية الموجبة لله العبادة دون غيره من خلقه.", "بيان أن هناك من الناس من يعبدون الشمس ويسجدون لها من العرب والعجم، وأن ذلك شرك باطل؛ فالعبادة لا تكون للمخلوقات الخاضعة في حياتها للخالق، وإنما تكون لخالقها ومسخّرها لمنافع خلقه.", "تقرير عقيدة البعث والجزاء بذكر دليل من أظهر الأدلة، وهو موت الأرض بالجدب ثم حياتها بالغيث؛ إذ لا فرق بين حياة النبات بالماء وحياة الإنسان بالماء كذلك، فبعد نفخة الفناء ومضيّ أربعين عاماً ينزل من السماء ماء فيحيا الناس وينبتون من عَجْب الذنب كما ينبت النبات بالبذرة الكامنة في التربة.", "تقرير قدرة الله على كل شيء أراده، وهذه الصفة خاصة به تعالى موجبة لعبادته وطاعته بعد الإيمان به وتأليهه."], "k": "«ترى الأرض خاشعة فإذا أنزلنا عليها الماء اهتزّت»… قلبي حين يجفّ، يحييه ماء الذكر."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (352, 41, 40, 46, 'سورة فصلت ٤٠ – ٤٦', 'فصلت: لا يأتيه الباطل من بين يديه ولا من خلفه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 352) = $j$[{"lbl": "الآيات ٤٠ – ٤٢", "q": "إِنَّ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ ءَايَٰتِنَا لَا يَخۡفَوۡنَ عَلَيۡنَآۗ أَفَمَن يُلۡقَىٰ فِي ٱلنَّارِ خَيۡرٌ أَم مَّن يَأۡتِيٓ ءَامِنٗا يَوۡمَ ٱلۡقِيَٰمَةِۚ ٱعۡمَلُواْ مَا شِئۡتُمۡ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٌ ﴿٤٠﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ بِٱلذِّكۡرِ لَمَّا جَآءَهُمۡۖ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ ﴿٤١﴾ لَّا يَأۡتِيهِ ٱلۡبَٰطِلُ مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ تَنزِيلٞ مِّنۡ حَكِيمٍ حَمِيدٖ ﴿٤٢﴾", "w": [["يُلحدون في آياتنا", "يجادلون فيها ويميلون بها فيؤوّلونها على غير تأويلها لإبطال حق أو إحقاق باطل."], ["لا يخفون علينا", "مكشوفون أمامنا، وسوف نبطش بهم جزاء إلحادهم."], ["أم من يأتي آمناً يوم القيامة", "نعم، الذي يأتي آمناً يوم القيامة خير ممن يُلقى في النار."], ["اعملوا ما شئتم", "تهديد لهم على إلحادهم، وليس إذناً لهم في العمل."], ["إن الذين كفروا بالذكر", "جحدوا القرآن أو ألحدوا فيه فكفروا بذلك."], ["وإنه لكتاب عزيز", "منيع لا يُقدر على الزيادة فيه ولا النقص منه."], ["لا يأتيه الباطل من بين يديه ولا من خلفه", "لا يقدر شيطان من الجن والإنس أن يزيد فيه شيئاً أو ينقص منه، كما أنه ليس قبله كتاب ينقضه ولا بعده كتاب ينسخه، فهو كله حق وصدق."]], "m": "يتوعّد الجبار عز وجل الذين يُلحدون في آيات كتابه بالتحريف والتبديل والتغيير بأنهم لا يخفون عليه، وأنه سينزل بهم نقمته إن لم يكفّوا. أفمن يُلقى في النار خير أم من يأتي آمناً يوم القيامة؟ لا يوجد عاقل يقول إن الذي يُلقى في النار خير، فالإلقاء في النار سببه الكفر والإلحاد فليتركه من أراد النجاة، والأمن يوم القيامة سببه الإيمان والتوحيد فليؤمن ويوحّد ولا يلحد في آياته من أراد الأمن. اعملوا ما شئتم إنه بما تعملون بصير: هذا يقال للمستهترين بالأحكام الشرعية، وهو تهديد لهم وليس إباحة، ويدلّ على التهديد قوله: إنه بما تعملون بصير. إن الذين كفروا بالقرآن لما جاءهم، وإنه لكتاب منيع بعيد المنال، لا يأتيه الباطل من بين يديه ولا من خلفه بالزيادة والنقصان أو التبديل والتغيير؛ وسكت عن خبر «إن» لأنه أظهر من أن يُذكر، وقد يُقدّر: لنفعلنّ بهم كذا وكذا. تنزيل من حكيم في أفعاله وسائر تصرفاته، حميد بذلك وبغيره من فواضله ونعمه.", "h": ["حرمة الإلحاد في آيات الله بالميل بها عن القصد والخروج بها إلى الباطل.", "التهديد الشديد لكل من يحرّف آيات الله أو يؤوّلها على غير مراد الله منها.", "تقرير مناعة القرآن وحفظ الله تعالى له، وأنه لا يدخله النقص ولا الزيادة إلى أن يرفعه الله إليه، إذ منه بدأ وإليه يعود."], "k": "«لا يأتيه الباطل»… بين يديّ كتاب محفوظ بلا شائبة؛ فهل أعطيه ثقتي كلها؟"}, {"lbl": "الآيات ٤٣ – ٤٦", "q": "مَّا يُقَالُ لَكَ إِلَّا مَا قَدۡ قِيلَ لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ ﴿٤٣﴾ وَلَوۡ جَعَلۡنَٰهُ قُرۡءَانًا أَعۡجَمِيّٗا لَّقَالُواْ لَوۡلَا فُصِّلَتۡ ءَايَٰتُهُۥٓۖ ءَا۬عۡجَمِيّٞ وَعَرَبِيّٞۗ قُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ وَٱلَّذِينَ لَا يُؤۡمِنُونَ فِيٓ ءَاذَانِهِمۡ وَقۡرٞ وَهُوَ عَلَيۡهِمۡ عَمًىۚ أُوْلَـٰٓئِكَ يُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدٖ ﴿٤٤﴾ وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ ﴿٤٥﴾ مَّنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۗ وَمَا رَبُّكَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ ﴿٤٦﴾", "w": [["ما يُقال لك", "من التكذيب أيها الرسول."], ["إلا ما قد قيل للرسل من قبلك", "من التكذيب لهم والكذب عليهم."], ["إن ربك لذو مغفرة", "مغفرة واسعة تشمل كل تائب إليه صادق في توبته."], ["وذو عقاب أليم", "معاقبة شديدة ذات ألم موجع للمصرّين على الكفر."], ["ولو جعلناه قرآناً أعجمياً", "كما اقترحوا إذ قالوا: هلّا أُنزل القرآن بلغة العجم."], ["لولا فُصّلت آياته", "هلّا بُيّنت حتى نفهمها."], ["أأعجميّ وعربي", "أقرآن أعجمي والمنزّل عليه عربي؟ يستنكرون ذلك تعنّتاً وعناداً."], ["هدى وشفاء", "هدى من الضلالة، وشفاء من داء الجهل."], ["في آذانهم وقر وهو عليهم عمى", "ثقل فهم لا يسمعونه، وهو عليهم عمى فلا يفهمونه."], ["أولئك يُنادَون من مكان بعيد", "والمنادى من مكان بعيد لا يسمع ولا يفهم ما يُنادى له."], ["فاختُلف فيه", "بالتصديق والتكذيب، والعمل ببعضه وترك بعضه، كما هي الحال في القرآن."], ["ولولا كلمة سبقت من ربك", "لولا الوعد بجمع الناس ليوم القيامة وحسابهم."], ["لقُضي بينهم", "لحُكم بين المختلفين اليوم فأُكرم الصادقون وأُهين الكاذبون."], ["وما ربك بظلّام للعبيد", "ليس ربك يا رسولنا بذي ظلم للعبيد."]], "m": "بعد توالي الآيات الهادية، وكفار قريش لا يزيدهم ذلك إلا عناداً، ولما كان الرسول بشراً يحتاج إلى عون حتى يصبر، أنزل تعالى هذه الآيات في تسليته: ما يُقال لك من التكذيب إلا ما قد قيل للرسل من قبلك، إن ربك لذو مغفرة لمن تاب، فلذا لا يتعجّل بإهلاك المكذبين رجاء أن يتوبوا، وذو عقاب أليم لمن مات على كفره. ولو جعلناه قرآناً أعجمياً كما اقترح بعضهم لقالوا: هلّا بُيّنت آياته حتى نفهمها، أقرآن أعجمي ونبي عربي؟ مستنكرين متعجّبين، وكل هذا إصرار على عدم الإيمان. قل: هو للذين آمنوا هدى إلى سبل السعادة والكمال، وشفاء من أمراض الشك والشرك والنفاق والعجب والرياء والحسد والكبر، والذين لا يؤمنون في آذانهم ثقل، وهو عليهم عمى، أولئك يُنادون من مكان بعيد فلا يسمعون ولا يفهمون. وتسلية أخرى: ولقد آتينا موسى التوراة فاختُلف فيه، فمنهم المصدّق ومنهم المكذّب، ومنهم العامل بما فيه ومنهم المعرض المتبع لهواه، ولولا كلمة سبقت من ربك لحكم لأهل الصدق بالنجاة ولأهل الكذب بالهلاك، وإنهم لفي شك من القرآن موقع في الريبة من جرّاء المعاندة. وتسلية أعظم: من عمل صالحاً بعد الإيمان فجزاؤه قاصر عليه ينتفع به دون سواه، ومن أساء فعلى نفسه يعود سوؤه، وما ربك بذي ظلم لعباده.", "h": ["تسلية الرسول ﷺ، أي حمله على الصبر والسلوان ليواصل دعوته إلى نهايتها.", "بيان مدى ما كان عليه المشركون من التكذيب للرسول والمعاندة والمجاحدة.", "القرآن دواء وشفاء لأهل الإيمان، وأهل الكفر على العكس من أهل الإيمان.", "بيان سنة الله في الأمم السابقة في اختلافها على أنبيائها وما جاءتها به من الهدى والنور.", "قوله تعالى «من عمل صالحاً فلنفسه ومن أساء فعليها» أُجري مجرى المثل عند العالمين.", "نفي الظلم عن الله مطلقاً."], "k": "«قل هو للذين آمنوا هدى وشفاء»… ما الداء في قلبي الذي أحتاج أن أطلب له الشفاء من القرآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 352;
insert into public.tdb_cards(topic, i, body) select 352, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٠ – ٤٢", "q": "إِنَّ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ ءَايَٰتِنَا لَا يَخۡفَوۡنَ عَلَيۡنَآۗ أَفَمَن يُلۡقَىٰ فِي ٱلنَّارِ خَيۡرٌ أَم مَّن يَأۡتِيٓ ءَامِنٗا يَوۡمَ ٱلۡقِيَٰمَةِۚ ٱعۡمَلُواْ مَا شِئۡتُمۡ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِيرٌ ﴿٤٠﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ بِٱلذِّكۡرِ لَمَّا جَآءَهُمۡۖ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ ﴿٤١﴾ لَّا يَأۡتِيهِ ٱلۡبَٰطِلُ مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ تَنزِيلٞ مِّنۡ حَكِيمٍ حَمِيدٖ ﴿٤٢﴾", "w": [["يُلحدون في آياتنا", "يجادلون فيها ويميلون بها فيؤوّلونها على غير تأويلها لإبطال حق أو إحقاق باطل."], ["لا يخفون علينا", "مكشوفون أمامنا، وسوف نبطش بهم جزاء إلحادهم."], ["أم من يأتي آمناً يوم القيامة", "نعم، الذي يأتي آمناً يوم القيامة خير ممن يُلقى في النار."], ["اعملوا ما شئتم", "تهديد لهم على إلحادهم، وليس إذناً لهم في العمل."], ["إن الذين كفروا بالذكر", "جحدوا القرآن أو ألحدوا فيه فكفروا بذلك."], ["وإنه لكتاب عزيز", "منيع لا يُقدر على الزيادة فيه ولا النقص منه."], ["لا يأتيه الباطل من بين يديه ولا من خلفه", "لا يقدر شيطان من الجن والإنس أن يزيد فيه شيئاً أو ينقص منه، كما أنه ليس قبله كتاب ينقضه ولا بعده كتاب ينسخه، فهو كله حق وصدق."]], "m": "يتوعّد الجبار عز وجل الذين يُلحدون في آيات كتابه بالتحريف والتبديل والتغيير بأنهم لا يخفون عليه، وأنه سينزل بهم نقمته إن لم يكفّوا. أفمن يُلقى في النار خير أم من يأتي آمناً يوم القيامة؟ لا يوجد عاقل يقول إن الذي يُلقى في النار خير، فالإلقاء في النار سببه الكفر والإلحاد فليتركه من أراد النجاة، والأمن يوم القيامة سببه الإيمان والتوحيد فليؤمن ويوحّد ولا يلحد في آياته من أراد الأمن. اعملوا ما شئتم إنه بما تعملون بصير: هذا يقال للمستهترين بالأحكام الشرعية، وهو تهديد لهم وليس إباحة، ويدلّ على التهديد قوله: إنه بما تعملون بصير. إن الذين كفروا بالقرآن لما جاءهم، وإنه لكتاب منيع بعيد المنال، لا يأتيه الباطل من بين يديه ولا من خلفه بالزيادة والنقصان أو التبديل والتغيير؛ وسكت عن خبر «إن» لأنه أظهر من أن يُذكر، وقد يُقدّر: لنفعلنّ بهم كذا وكذا. تنزيل من حكيم في أفعاله وسائر تصرفاته، حميد بذلك وبغيره من فواضله ونعمه.", "h": ["حرمة الإلحاد في آيات الله بالميل بها عن القصد والخروج بها إلى الباطل.", "التهديد الشديد لكل من يحرّف آيات الله أو يؤوّلها على غير مراد الله منها.", "تقرير مناعة القرآن وحفظ الله تعالى له، وأنه لا يدخله النقص ولا الزيادة إلى أن يرفعه الله إليه، إذ منه بدأ وإليه يعود."], "k": "«لا يأتيه الباطل»… بين يديّ كتاب محفوظ بلا شائبة؛ فهل أعطيه ثقتي كلها؟"}, {"lbl": "الآيات ٤٣ – ٤٦", "q": "مَّا يُقَالُ لَكَ إِلَّا مَا قَدۡ قِيلَ لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةٖ وَذُو عِقَابٍ أَلِيمٖ ﴿٤٣﴾ وَلَوۡ جَعَلۡنَٰهُ قُرۡءَانًا أَعۡجَمِيّٗا لَّقَالُواْ لَوۡلَا فُصِّلَتۡ ءَايَٰتُهُۥٓۖ ءَا۬عۡجَمِيّٞ وَعَرَبِيّٞۗ قُلۡ هُوَ لِلَّذِينَ ءَامَنُواْ هُدٗى وَشِفَآءٞۚ وَٱلَّذِينَ لَا يُؤۡمِنُونَ فِيٓ ءَاذَانِهِمۡ وَقۡرٞ وَهُوَ عَلَيۡهِمۡ عَمًىۚ أُوْلَـٰٓئِكَ يُنَادَوۡنَ مِن مَّكَانِۭ بَعِيدٖ ﴿٤٤﴾ وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ فَٱخۡتُلِفَ فِيهِۚ وَلَوۡلَا كَلِمَةٞ سَبَقَتۡ مِن رَّبِّكَ لَقُضِيَ بَيۡنَهُمۡۚ وَإِنَّهُمۡ لَفِي شَكّٖ مِّنۡهُ مُرِيبٖ ﴿٤٥﴾ مَّنۡ عَمِلَ صَٰلِحٗا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَآءَ فَعَلَيۡهَاۗ وَمَا رَبُّكَ بِظَلَّـٰمٖ لِّلۡعَبِيدِ ﴿٤٦﴾", "w": [["ما يُقال لك", "من التكذيب أيها الرسول."], ["إلا ما قد قيل للرسل من قبلك", "من التكذيب لهم والكذب عليهم."], ["إن ربك لذو مغفرة", "مغفرة واسعة تشمل كل تائب إليه صادق في توبته."], ["وذو عقاب أليم", "معاقبة شديدة ذات ألم موجع للمصرّين على الكفر."], ["ولو جعلناه قرآناً أعجمياً", "كما اقترحوا إذ قالوا: هلّا أُنزل القرآن بلغة العجم."], ["لولا فُصّلت آياته", "هلّا بُيّنت حتى نفهمها."], ["أأعجميّ وعربي", "أقرآن أعجمي والمنزّل عليه عربي؟ يستنكرون ذلك تعنّتاً وعناداً."], ["هدى وشفاء", "هدى من الضلالة، وشفاء من داء الجهل."], ["في آذانهم وقر وهو عليهم عمى", "ثقل فهم لا يسمعونه، وهو عليهم عمى فلا يفهمونه."], ["أولئك يُنادَون من مكان بعيد", "والمنادى من مكان بعيد لا يسمع ولا يفهم ما يُنادى له."], ["فاختُلف فيه", "بالتصديق والتكذيب، والعمل ببعضه وترك بعضه، كما هي الحال في القرآن."], ["ولولا كلمة سبقت من ربك", "لولا الوعد بجمع الناس ليوم القيامة وحسابهم."], ["لقُضي بينهم", "لحُكم بين المختلفين اليوم فأُكرم الصادقون وأُهين الكاذبون."], ["وما ربك بظلّام للعبيد", "ليس ربك يا رسولنا بذي ظلم للعبيد."]], "m": "بعد توالي الآيات الهادية، وكفار قريش لا يزيدهم ذلك إلا عناداً، ولما كان الرسول بشراً يحتاج إلى عون حتى يصبر، أنزل تعالى هذه الآيات في تسليته: ما يُقال لك من التكذيب إلا ما قد قيل للرسل من قبلك، إن ربك لذو مغفرة لمن تاب، فلذا لا يتعجّل بإهلاك المكذبين رجاء أن يتوبوا، وذو عقاب أليم لمن مات على كفره. ولو جعلناه قرآناً أعجمياً كما اقترح بعضهم لقالوا: هلّا بُيّنت آياته حتى نفهمها، أقرآن أعجمي ونبي عربي؟ مستنكرين متعجّبين، وكل هذا إصرار على عدم الإيمان. قل: هو للذين آمنوا هدى إلى سبل السعادة والكمال، وشفاء من أمراض الشك والشرك والنفاق والعجب والرياء والحسد والكبر، والذين لا يؤمنون في آذانهم ثقل، وهو عليهم عمى، أولئك يُنادون من مكان بعيد فلا يسمعون ولا يفهمون. وتسلية أخرى: ولقد آتينا موسى التوراة فاختُلف فيه، فمنهم المصدّق ومنهم المكذّب، ومنهم العامل بما فيه ومنهم المعرض المتبع لهواه، ولولا كلمة سبقت من ربك لحكم لأهل الصدق بالنجاة ولأهل الكذب بالهلاك، وإنهم لفي شك من القرآن موقع في الريبة من جرّاء المعاندة. وتسلية أعظم: من عمل صالحاً بعد الإيمان فجزاؤه قاصر عليه ينتفع به دون سواه، ومن أساء فعلى نفسه يعود سوؤه، وما ربك بذي ظلم لعباده.", "h": ["تسلية الرسول ﷺ، أي حمله على الصبر والسلوان ليواصل دعوته إلى نهايتها.", "بيان مدى ما كان عليه المشركون من التكذيب للرسول والمعاندة والمجاحدة.", "القرآن دواء وشفاء لأهل الإيمان، وأهل الكفر على العكس من أهل الإيمان.", "بيان سنة الله في الأمم السابقة في اختلافها على أنبيائها وما جاءتها به من الهدى والنور.", "قوله تعالى «من عمل صالحاً فلنفسه ومن أساء فعليها» أُجري مجرى المثل عند العالمين.", "نفي الظلم عن الله مطلقاً."], "k": "«قل هو للذين آمنوا هدى وشفاء»… ما الداء في قلبي الذي أحتاج أن أطلب له الشفاء من القرآن؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;